"""web_export.py — bake the goat-pro web fork's R2 surface into data/export/web/.

Reads two things and nothing else:
  1. the frozen grades artifact  data/export/mlb_pitcher_grades.json
     (generated by pipeline/bakeoff.py export --target csw_norm; gate_status
     `descriptive-only`, echoed verbatim into meta.json);
  2. the savant mart (pitches_all + lb_* leaderboards) via savant_mart.mart.

Writes the exact keys the forked web app reads (docs/parity-matrix.md MVP
surface). The directory is fully regenerated every run; the R2 sync
(pipeline/r2_sync.py) uploads it under the `goatpro/` key prefix. Nothing here
hand-edits data/export/*.json — the grades artifact is read-only input.

Field semantics that MUST match the web app:
  - grades are 100 + 10z (train_mlb.grade), 100 = average, higher better;
  - per-type rows carry the CLASS grade (FB/BB/CH) with `stuffGradeFrom`
    naming the host type, so the profile's shared-grade note fires;
  - pitch type codes are the SITE codes (CT not FC, CB for CU/KC, SW for ST,
    SL for SV) — PITCH_CONFIG vocabulary;
  - confidence: HIGH >= 400, MODERATE >= 150, LOW >= 50 graded pitches.

Staging — the bake is split into families so a small fix does not rescore the
whole mart (data fixes need only a rebake + r2_sync, never a redeploy):

  python pipeline/web_export.py                          # full bake
  python pipeline/web_export.py --only players           # one family
  python pipeline/web_export.py --only players --player 694973
  python pipeline/web_export.py --check                  # bake twice, diff
  python pipeline/web_export.py --check --write          # ...and on PASS write it (no third bake)

Families: pitchers players arsenal slot vaa savant. `--player` limits the
per-player file loops (players/, slot/) to one id — global files are always
baked whole. `--check` runs the same bake twice into temp dirs and diffs
(meta.json's exportedAt excepted); it exits 1 on any difference, which is the
no-op guarantee: same inputs -> byte-identical outputs -> r2_sync uploads
nothing new. Both check bakes start from an APFS clone of the export dir (files
the bake merges into start the same); `--write` then copies bake A's changes into it,
under the export dir's lock, instead of baking a third time.
"""

import argparse
