def _clean(o):
    """NaN -> None everywhere: the UI must read a missing number, never NaN."""
    if isinstance(o, dict):
        return {k: _clean(v) for k, v in o.items()}
    if isinstance(o, list):
        return [_clean(v) for v in o]
    if isinstance(o, float) and not np.isfinite(o):
        return None
    return o


def jwrite(path: Path, obj, sort_keys: bool = False) -> int:
    path.parent.mkdir(parents=True, exist_ok=True)
    text = json.dumps(_clean(obj), allow_nan=False, sort_keys=sort_keys)
    path.write_text(text)
    return path.stat().st_size


def jwrite_gz(path: Path, obj, sort_keys: bool = False) -> int:
    """Gzipped JSON for the per-player detail files. mtime=0 keeps the archive
    byte-identical across bakes — the --check no-op guarantee extends to .gz."""
    import gzip
    path.parent.mkdir(parents=True, exist_ok=True)
    data = json.dumps(_clean(obj), allow_nan=False, sort_keys=sort_keys).encode()
    path.write_bytes(gzip.compress(data, mtime=0))
    return path.stat().st_size


def pct5(values) -> dict | None:
    v = np.asarray([x for x in values if x is not None and np.isfinite(x)], dtype=float)
    if v.size < 10:
        return None
    p10, p25, p50, p75, p90 = np.percentile(v, [10, 25, 50, 75, 90])
    return {"p10": round(float(p10), 3), "p25": round(float(p25), 3),
            "p50": round(float(p50), 3), "p75": round(float(p75), 3),
            "p90": round(float(p90), 3)}


@functools.lru_cache(maxsize=2)
def p_depth(level: str, seasons: tuple, con) -> tuple[dict, dict]:
    """D-35 (pipeline/hitter_depth.py): contact and bat tracking AGAINST each pitcher-season (>= 50 BF),
    plus the per-game trend rows. Shared by the pitchers and players families."""
    from hitter_depth import pitcher_depth, trends
    PD = {"xwoba": ("xwobaAg", 3), "xba": ("xbaAg", 3), "xslg": ("xslgAg", 3), "xwobacon": ("xwobaconAg", 3),
          "woba": ("wobaAg", 3), "xwoba_gap": ("wobaMinusXwobaAg", 3), "ev_mean": ("evAg", 1),
          "hard_hit": ("hardHitPctAg", 1), "barrel": ("barrelPctAg", 1), "sweet_spot": ("sweetSpotPctAg", 1),
          "pull_air": ("pullAirPctAg", 1), "bat_speed": ("batSpeedAg", 1), "squared_up": ("squaredUpPctAg", 1),
          "blast": ("blastPctAg", 1), "rv100_fb": ("rvPer100Fb", 2), "rv100_br": ("rvPer100Br", 2),
          "rv100_os": ("rvPer100Os", 2)}
    d = pitcher_depth(con, seasons, level=level)
    depth = {(int(r["id"]), int(r["season"])): {k: f(r[c], nd) for c, (k, nd) in PD.items() if c in r}
             for r in d.to_dict("records")}
    xf = ROOT / "pipeline" / "results" / "xrv_v2_pitchers.csv"  # §71/§78 (D-03) xRV/100 + luck, v2 (+ season term): descriptive, MLB only
    if level == "mlb" and xf.exists():
        for r in pd.read_csv(xf).itertuples():
            depth.setdefault((int(r.mlbam), int(r.season)), {}).update(
                {"xrvPer100": f(r.xrv100, 2), "rvLuck": f(r.luck, 2)})
    tf = ROOT / "pipeline" / "results" / "tunnel_pitchers.csv"  # §74 (D-06) Tunnel+: descriptive, MLB only
    if level == "mlb" and tf.exists():
        for r in pd.read_csv(tf).itertuples():
            depth.setdefault((int(r.mlbam), int(r.season)), {}).update(
                {"tunnelPlus": int(r.tunnel_plus), "tunnelPairsN": int(r.n_pairs),
                 "tunnelReliability": f(r.reliability, 2), "tunnelRankable": bool(r.rankable)})
    return depth, trends(con, seasons, who="pitcher", level=level)


@functools.lru_cache(maxsize=1)
def tunnel_pairs() -> dict:
    """§74 (D-06): {(mlbam, season): pairing rows, most-thrown first}, MLB only."""
    tf = ROOT / "pipeline" / "results" / "tunnel_pairs.csv"
    out: dict = {}
    if tf.exists():
        for r in pd.read_csv(tf).sort_values(["n", "from_code", "to_code"], ascending=[False, True, True]).itertuples():
            out.setdefault((int(r.mlbam), int(r.season)), []).append({
                "from": r.from_code, "to": r.to_code, "tunnelPlus": int(r.tunnel_plus), "n": int(r.n),
                "commitSepIn": f(r.commit_sep_in, 1), "plateSepIn": f(r.plate_sep_in, 1),
                "chaseLiftPts": f(r.chase_lift_pts, 2), "reliability": f(r.reliability, 2),
                "rankable": bool(r.rankable)})
    return out


@functools.lru_cache(maxsize=1)
def _proj_bands() -> dict | None:
    path = ROOT / "pipeline" / "results" / "proj_bands.json"  # pipeline/proj_bands.py (D-36)
    return json.loads(path.read_text()) if path.exists() else None


def proj_band_fields(k_proj, prev_plus, bf) -> dict:
    """D-36: 80% bands from measured out-of-fold misses at this batters-faced size. kProjLo/Hi in K/PA;
    rvProj (next-season RV/100, Prevention+ inverted to its own units) with rvProjLo/Hi."""
    b = _proj_bands()
    if not b or bf is None:
        return {}
    from proj_bands import band_for
    out = {}
    kb, pb = band_for(b, "k", bf), band_for(b, "prev", bf)
    if kb and k_proj is not None:
        out.update(kProjLo=f(max(0.0, k_proj + kb["q10"]), 3), kProjHi=f(k_proj + kb["q90"], 3))
    if pb and prev_plus is not None:
        rv = b["prev_mean"] + (prev_plus - 100) * b["prev_sd"] / 10
        out.update(rvProj=f(rv, 2), rvProjLo=f(rv + pb["q10"], 2), rvProjHi=f(rv + pb["q90"], 2))
    return out


def dense_q(values, n: int = 99) -> list[float] | None:
    v = np.asarray([x for x in values if x is not None and np.isfinite(x)], dtype=float)
    if v.size < 30:
        return None
    return [round(float(x), 4) for x in np.percentile(v, np.arange(1, n + 1))]


def f(x, nd=1):
    """None-safe round: the bake emits null rather than NaN the UI would read as 0."""
    if x is None or (isinstance(x, float) and not np.isfinite(x)):
        return None
    return round(round(float(x), 9), nd)  # snap float-sum order noise first: the same input must round the same


def r(x):
    return None if x is None or (isinstance(x, float) and not np.isfinite(x)) else int(round(round(float(x), 9)))


