def fetch_logos(out: Path, seasons_roster_teams: set[str]) -> dict:
    """Download each club's cap logo once, into the web bundle (public/logos,
    committed — that is the durable store) and the export dir (mirrored to R2
    by r2_sync for anything that wants the bucket copy). Skipped when present;
    the file never changes for a club."""
    import urllib.request

    WEB_PUBLIC.mkdir(parents=True, exist_ok=True)
    (out / "logos").mkdir(parents=True, exist_ok=True)
    got = {}
    for abbr in sorted({a for a in MLB_TEAM_IDS if a not in ("OAK", "ARI")} | {a for a in seasons_roster_teams if a in MLB_TEAM_IDS}):
        tid = MLB_TEAM_IDS[abbr]
        dst = WEB_PUBLIC / f"{abbr}.svg"
        mirror = out / "logos" / f"{abbr}.svg"
        if dst.exists() and dst.stat().st_size > 200:
            if not mirror.exists():
                shutil.copyfile(dst, mirror)
            got[abbr] = tid
            continue
        url = LOGOS_SRC.format(tid=tid)
        try:
            req = urllib.request.Request(url, headers={"User-Agent": "goat-pro/1.0 (logos; one-time fetch)"})
            with urllib.request.urlopen(req, timeout=20) as resp:
                data = resp.read()
            if len(data) < 200:
                raise ValueError(f"too small: {len(data)}")
            dst.write_bytes(data)
            mirror.write_bytes(data)
            got[abbr] = tid
            print(f"  logo {abbr} ({tid}): {len(data)} bytes")
        except Exception as e:  # noqa: BLE001 — a missing logo falls back to the pixel badge
            print(f"  ! logo {abbr}: {e}")
        time.sleep(1.5)
    return got


def _files(d: Path, skip: tuple[str, ...]) -> set[Path]:
    return {p.relative_to(d) for p in d.rglob("*")
            if p.is_file() and p.name != "BAKE_LOCK" and p.relative_to(d).parts[0] not in skip}


def _same(pa: Path, pb: Path, rel: Path) -> bool:
    if not pa.exists() or not pb.exists():
        return False
    if rel == Path("meta.json"):  # exportedAt timestamps the run; nothing else may differ
        ja, jb = json.loads(pa.read_text()), json.loads(pb.read_text())
        ja.pop("exportedAt", None), jb.pop("exportedAt", None)
        return ja == jb
    return pa.stat().st_size == pb.stat().st_size and pa.read_bytes() == pb.read_bytes()


def diff_dirs(a: Path, b: Path, skip: tuple[str, ...] = ()) -> list[Path]:
    """Files that differ between two bake dirs (top-level names in `skip` ignored)."""
    return sorted(rel for rel in _files(a, skip) | _files(b, skip) if not _same(a / rel, b / rel, rel))


def seed_dir(src: Path, dst: Path, skip: tuple[str, ...]) -> None:
    """Start a --check bake from a copy of the real export, so files the bake merges into
    (percentiles.json, ...) start the same. APFS clone (cp -c): instant, no extra disk."""
    if not src.exists():
        dst.mkdir(parents=True)
        return
    if subprocess.run(["cp", "-cR", str(src), str(dst)], capture_output=True).returncode:
        shutil.copytree(src, dst)  # not APFS: a real copy
    for name in (*skip, "BAKE_LOCK"):
        p = dst / name
        shutil.rmtree(p) if p.is_dir() else p.unlink(missing_ok=True)


def apply_dir(src: Path, dst: Path, skip: tuple[str, ...]) -> int:
    """Make dst match src (outside `skip`): copy new/changed files, delete ones src dropped."""
    changed = diff_dirs(src, dst, skip)
    print(f"check: {len(changed)} file(s) changed vs the export: {', '.join(map(str, changed[:8]))}"
          + (" ..." if len(changed) > 8 else ""))
    for rel in [*changed, Path("meta.json")]:
        if (src / rel).exists():
            (dst / rel).parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(src / rel, dst / rel)
        else:
            (dst / rel).unlink(missing_ok=True)
    return len(changed)


def fold_site_rows(sub: pd.DataFrame) -> pd.DataFrame:
    """Fold Statcast types to site codes WITHOUT duplicate labels: a pitcher
    throwing both ST and SW (or SL and SV, CU and KC) has two rows per site
    code, and everything downstream keys on the site code. n/n_pa/rv sum,
    means are n-weighted, SDs pool as weighted within + between-of-means."""
    rows = []
    for site, g in sub.groupby("site"):
        n = g["n"].values.astype(float)
        tot = n.sum()
        row: dict = {"site": site, "n": int(tot)}
        if "n_pa" in g:
            row["n_pa"] = int(g["n_pa"].sum())
        if "rv" in g:
            row["rv"] = float(g["rv"].sum())
        for c in ("velo", "ivb", "hb"):
            row[c] = float((g[c].values * n).sum() / tot)
        for mean_col, sd_col in (("ivb", "ivb_sd"), ("hb", "hb_sd")):
            if sd_col not in g:
                continue
            m = g[mean_col].values.astype(float)
            s = g[sd_col].values.astype(float)
            ok = np.isfinite(s) & np.isfinite(m) & (g["n"].values > 2)
            if ok.any():
                var = float((n[ok] * (s[ok] ** 2 + (m[ok] - np.average(m[ok], weights=n[ok])) ** 2)).sum() / n[ok].sum())
                row[sd_col] = var ** 0.5
            else:
                row[sd_col] = None
        rows.append(row)
    return pd.DataFrame(rows)


# MLB half-signal constants, measured by pipeline/measure_discipline_mlb.py
# (method + holdout in the file). One source of truth with the web side, which
# reads the same JSON. A metric with k=None must not be shrunk.
DISC_SHRINK = {
    "zonePct": ("n_zone", "n_pitches", "zonePct"),
    "chasePct": ("n_ooz_swing", "n_ooz", "chasePct"),
    "zSwingPct": ("n_zone_swing", "n_zone", "zSwingPct"),
    "zWhiffPct": ("n_zone_whiff", "n_zone_swing", "zWhiffPct"),
    "oWhiffPct": ("n_ooz_whiff", "n_ooz_swing", "oWhiffPct"),
    "zContactPct": ("n_zone_contact", "n_zone_swing", "zContactPct"),
    "oContactPct": ("n_ooz_swing - n_ooz_whiff", "n_ooz_swing", "oContactPct"),
    "swStrPct": ("whiff", "n_pitches", "swStrPct"),
    "calledStrikePct": ("csw - whiff", "taken", "calledStrikePct"),
    "firstPitchStrikePct": ("n_first_pitch_strike", "n_first_pitch", "firstPitchStrikePct"),
    "putawayPct": ("n_two_strike_csw", "n_two_strike", "putawayPct"),
    "swingPct": ("swings", "n_pitches", "swingPct"),
}
try:
    _MEASURED = json.loads((ROOT / "web" / "lib" / "measured-mlb.json").read_text())
    DISC_HALF: dict[str, int | None] = _MEASURED["DISCIPLINE_HALF_PITCHER_MLB"]
    DISC_HALF_HITTER: dict[str, int | None] = _MEASURED.get("DISCIPLINE_HALF_HITTER_MLB", {})
except (OSError, KeyError):
    DISC_HALF, DISC_HALF_HITTER = {}, {}


def league_rates(season: int, totals) -> dict:
    """League rate per metric for the shrinkage target, from the totals frame
    (kept pitchers only). Computed once per season and cached."""
    cached = _LEAGUE_RATES.get(season)
    if cached is not None:
        return cached
    sub = totals[totals["season"] == season]
    out = {}
    for key, (num, den, _key2) in DISC_SHRINK.items():
        num_sum = float(eval(num, {"__builtins__": {}}, {c: sub[c].sum() for c in sub.columns})) if len(sub) else 0.0
        den_sum = float(eval(den, {"__builtins__": {}}, {c: sub[c].sum() for c in sub.columns})) if len(sub) else 0.0
        out[key] = 100 * num_sum / den_sum if den_sum else None
    _LEAGUE_RATES[season] = out
    return out


_LEAGUE_RATES: dict = {}


def discipline_fields(d: dict, t, season: int | None = None, totals=None) -> None:
    """Pitcher-season plate-discipline rates (P4): the raw rate printed, the
    sample-adjusted twin ranked (`${key}Shrunk`, shrunk toward the season's
    league rate with the measured half-signal k), denominators alongside for
    the tooltips."""
    n = t["n_pitches"]
    d.update({
        "zonePct": f(100 * t["n_zone"] / n, 1) if n else None,
        "chasePct": f(100 * t["n_ooz_swing"] / t["n_ooz"], 1) if t["n_ooz"] else None,
        "zSwingPct": f(100 * t["n_zone_swing"] / t["n_zone"], 1) if t["n_zone"] else None,
        "zWhiffPct": f(100 * t["n_zone_whiff"] / t["n_zone_swing"], 1) if t["n_zone_swing"] else None,
        "oWhiffPct": f(100 * t["n_ooz_whiff"] / t["n_ooz_swing"], 1) if t["n_ooz_swing"] else None,
        "zContactPct": f(100 * t["n_zone_contact"] / t["n_zone_swing"], 1) if t["n_zone_swing"] else None,
        "oContactPct": f(100 * (t["n_ooz_swing"] - t["n_ooz_whiff"]) / t["n_ooz_swing"], 1) if t["n_ooz_swing"] else None,
        "swStrPct": f(100 * t["whiff"] / n, 1) if n else None,
        "calledStrikePct": f(100 * (t["csw"] - t["whiff"]) / t["taken"], 1) if t["taken"] else None,
        "firstPitchStrikePct": f(100 * t["n_first_pitch_strike"] / t["n_first_pitch"], 1) if t["n_first_pitch"] else None,
        "putawayPct": f(100 * t["n_two_strike_csw"] / t["n_two_strike"], 1) if t["n_two_strike"] else None,
        "swingPct": f(100 * t["swings"] / n, 1) if n else None,
        "nPitchesLoc": int(n) if n else None,
        "nOozPitches": int(t["n_ooz"]), "nZonePitches": int(t["n_zone"]),
        "nZoneSwings": int(t["n_zone_swing"]),
        "nFirstPitch": int(t["n_first_pitch"]), "nTwoStrike": int(t["n_two_strike"]),
        "nSwings": int(t["swings"]),
    })
    if season is not None and totals is not None:
        lg = league_rates(season, totals)
        for key, (num, den, out_key) in DISC_SHRINK.items():
            k = DISC_HALF.get(key)
            den_v = float(eval(den, {"__builtins__": {}}, {c: getattr(t, c) for c in
                          ("n_zone", "n_ooz", "n_ooz_swing", "n_ooz_whiff", "n_zone_swing", "n_zone_whiff",
                           "n_zone_contact", "n_first_pitch", "n_first_pitch_strike", "n_two_strike",
                           "n_two_strike_csw", "swings", "taken", "csw", "whiff", "n_pitches")})) if k else 0.0
            raw = d.get(key)
            if k and den_v and raw is not None:
                num_v = den_v * (raw / 100)
                d[f"{out_key}Shrunk"] = f(100 * (num_v + k * (lg[key] or 0) / 100) / (den_v + k), 1)
            else:
                d[f"{out_key}Shrunk"] = None


def overlay_p7(grades: pd.DataFrame) -> pd.DataFrame:
    """Owner 2026-10-27: the P7 family replaces the v2 grades on the site. Stuff+ becomes Whiff+ (same
    `stuffPlus` keys, overall / class / type), Pitching+ becomes the P7 all-in value; K+, Prevention+,
    Control+ are added. ABStuff+ is not shown on the site (owner). A row the P7 export lacks shows nothing,
    never the old number."""
    m = pd.DataFrame(json.loads(MODELS_FILE.read_text())["pitchers"])
    m["stuff_by_type"] = [[{"type": t, "n": e["n"], "grade": e["grade"], "gyro": bool(e.get("sl_gyro"))}
                           for t, e in w.items()]
                          for w in m["whiff_by_type"]]
    m = m.rename(columns={"whiff_plus": "grade", "whiff_by_class": "stuff_by_class"})
    keep = ["mlbam", "season", "grade", "stuff_by_class", "stuff_by_type", "pitching_plus", "pitching_by_class",
            *P7_FIELDS]
    g = grades.drop(columns=[c for c in keep if c not in ("mlbam", "season")], errors="ignore")  # population rows carry None P7 columns
    g = g.merge(m[keep], on=["mlbam", "season"], how="left")
    for c in ("stuff_by_class", "stuff_by_type", "pitching_by_class"):
        g[c] = [x if isinstance(x, list) else [] for x in g[c]]
    return g


# The site-count pitch gates, shared by the detail and visuals families: the
# pitches every measured line, sequence and chart counts.
DETAIL_GATE = """AND pitch_type IN ('FF','SI','FC','SL','CU','KC','SW','SV','ST','CH','FS','FO','EP')
  AND release_speed BETWEEN 55 AND 105 AND release_extension > 3
  AND pfx_z IS NOT NULL AND pfx_x IS NOT NULL AND release_spin_rate IS NOT NULL
  AND p_throws IN ('L','R') AND stand IN ('L','R')"""

AAA_MODELS_FILE = ROOT / "data" / "export" / "aaa_pitcher_models.json"  # pipeline/aaa_export.py (Phase 2)

MILB = ROOT / "data" / "milb"  # pipeline/milb_lines.py (MLB Stats API season lines, every level)


def milb_names(kind: str) -> dict[int, str]:
    """mlbam -> latest name from the minor league lines (AAA players off every MLB roster)."""
    df = pd.read_parquet(MILB / f"{kind}.parquet", columns=["mlbam_id", "player_name", "season"])
    df = df.dropna(subset=["player_name"]).sort_values("season")
    return {int(k): v for k, v in zip(df["mlbam_id"], df["player_name"])}


@functools.lru_cache(maxsize=2)
def official_er(level: str) -> dict[tuple[int, int], tuple[int, int]]:
    """(mlbam, season) -> (earned runs, outs) from the MLB Stats API season lines
    (pipeline/milb_lines.py: --mlb for MLB, the minors file for AAA). Statcast has no
    earned/unearned split, so ERA comes from here; empty if the file is missing."""
    path = MILB / ("mlb_pitchers.parquet" if level == "mlb" else "pitchers.parquet")
    if not path.exists():
        return {}
    d = pd.read_parquet(path, columns=["mlbam_id", "season", "level", "ER", "OUTS"])
    d = d[d["level"] == ("MLB" if level == "mlb" else "AAA")].groupby(["mlbam_id", "season"])[["ER", "OUTS"]].sum()
    return {(int(m), int(s)): (int(r.ER), int(r.OUTS)) for (m, s), r in d.iterrows()}


@functools.lru_cache(maxsize=2)
def official_gs(level: str) -> dict[tuple[int, int], tuple[int, int]]:
    """(mlbam, season) -> (G, GS) from the same Stats API lines as official_er; empty if missing."""
    path = MILB / ("mlb_pitchers.parquet" if level == "mlb" else "pitchers.parquet")
    if not path.exists():
        return {}
    d = pd.read_parquet(path, columns=["mlbam_id", "season", "level", "G", "GS"])
    d = d[d["level"] == ("MLB" if level == "mlb" else "AAA")].groupby(["mlbam_id", "season"])[["G", "GS"]].sum()
    return {(int(m), int(s)): (int(r.G), int(r.GS)) for (m, s), r in d.iterrows()}


def role_of(g: int | None, gs: int | None) -> str | None:
    """Season role: SP when at least half his games were starts (openers count, as in the official GS)."""
    return None if not g else ("SP" if 2 * (gs or 0) >= g else "RP")


def era_of(pid: int, season: int, level: str, runs: float, ip: float) -> float | None:
    """Official ERA where the Stats API line exists, else RA9 from runs while he pitched."""
    er = official_er(level).get((int(pid), int(season)))
    if er and er[1] > 0:
        return 27 * er[0] / er[1]
    return 9 * runs / ip if ip > 0 else None


@functools.lru_cache(maxsize=1)  # one register + MiLB read per bake; uncached it ran once per row (~85% of the pitchers family)
def births() -> dict[int, pd.Timestamp]:
    """mlbam -> birth date: the Chadwick register in the mart, then the MiLB lines for players it lacks."""
    reg = mart.connect().sql("""
        SELECT TRY_CAST(key_mlbam AS BIGINT) AS pid,
               make_date(TRY_CAST(birth_year AS INT), coalesce(TRY_CAST(birth_month AS INT), 7),
                         coalesce(TRY_CAST(birth_day AS INT), 1)) AS b
        FROM register WHERE TRY_CAST(key_mlbam AS BIGINT) IS NOT NULL AND TRY_CAST(birth_year AS INT) IS NOT NULL""").df()
    out = {int(p): pd.Timestamp(b) for p, b in zip(reg["pid"], reg["b"])}
    for kind in ("pitchers", "hitters"):
        m = pd.read_parquet(MILB / f"{kind}.parquet", columns=["mlbam_id", "birth_date"]).dropna()
        for p, b in zip(m["mlbam_id"], pd.to_datetime(m["birth_date"], errors="coerce")):
            if pd.notna(b):
                out.setdefault(int(p), b)
    return out


def pitcher_team_splits(con, season_list: str, stints: dict, level: str, fip_c: dict) -> dict:
    """(pid, season) -> one line per club for pitchers who changed teams, in stint order: raw stats only
    (grades are season-long and stay on the combined row). Runs are RA9 while he pitched for that club."""
    if not stints:
        return {}
    d = con.sql(f"""
        SELECT pitcher AS id, season, CASE WHEN inning_topbot = 'Top' THEN home_team ELSE away_team END AS team,
               COUNT(*) AS n_pitches, COUNT(DISTINCT game_pk) AS g,
               COUNT(DISTINCT (game_pk, at_bat_number)) FILTER (WHERE events IS NOT NULL AND events <> 'truncated_pa') AS pa,
               COUNT(*) FILTER (WHERE events IN ('strikeout','strikeout_double_play')) AS k,
               COUNT(*) FILTER (WHERE events IN ('walk','intent_walk')) AS bb,
               COUNT(*) FILTER (WHERE events = 'hit_by_pitch') AS hbp,
               COUNT(*) FILTER (WHERE events IN {BB_EVENTS}) AS h,
               COUNT(*) FILTER (WHERE events = 'home_run') AS hr,
               SUM(CASE WHEN events IN {OUT_EVENTS_1} THEN 1 WHEN events IN {OUT_EVENTS_2} THEN 2
                        WHEN events IN {OUT_EVENTS_3} THEN 3 ELSE 0 END) AS ev_outs,
               SUM(post_bat_score - bat_score) AS runs,
               COUNT(*) FILTER (WHERE description IN ('called_strike','swinging_strike','swinging_strike_blocked','foul_tip')) AS csw,
               COUNT(*) FILTER (WHERE description IN {WHIFF}) AS whiff,
               COUNT(*) FILTER (WHERE description IN {SWING}) AS swings,
               SUM(delta_pitcher_run_exp) AS rv, AVG(release_speed) AS velo
        FROM pitches_all
        WHERE game_type = 'R' AND season IN ({season_list}) AND pitcher IS NOT NULL
        GROUP BY 1, 2, 3""").df()
    d = d[[(int(a), int(b)) in stints for a, b in zip(d["id"], d["season"])]]
    oo = official_er(level)
    # official per-club ER/outs (pipeline/team_lines.py); missing -> the shared-out fallback below
    tl = MILB / "team_lines.parquet"
    club_off = {}
    if tl.exists():
        t = pd.read_parquet(tl)
        t = t[(t["level"] == level) & t["team"].notna()]
        club_off = {(int(r.mlbam_id), int(r.season), r.team): (int(r.ER), int(r.OUTS)) for r in t.itertuples()}
    # Whiff+ per club from the per-game sums (pipeline/whiff_game.py): same scale as the season grade
    wg = ROOT / "cache" / "whiff_game.parquet"
    club_whiff = {}
    if level == "mlb" and wg.exists():
        games = con.sql(f"""
            SELECT DISTINCT pitcher AS id, season, game_pk,
                   CASE WHEN inning_topbot = 'Top' THEN home_team ELSE away_team END AS team
            FROM pitches_all WHERE game_type = 'R' AND season IN ({season_list}) AND pitcher IS NOT NULL""").df()
        w = pd.read_parquet(wg).rename(columns={"pitcher": "id"}).merge(games, on=["id", "season", "game_pk"])
        w = w.groupby(["id", "season", "team"])[["n", "zsum"]].sum()
        club_whiff = {(int(i), int(s), t): float(np.clip(100 + 10 * r.zsum / r.n, 50, 175))
                      for (i, s, t), r in w.iterrows() if r.n >= 10}
    out = {}
    for (pid, season), grp in d.groupby(["id", "season"]):
        key = (int(pid), int(season))
        # ponytail: Statcast events miss outs on the bases, so the official season outs are shared out by
        # each club's event-out share; exact per-club IP needs per-team official lines.
        off = oo.get(key, (0, 0))[1]
        tot = grp["ev_outs"].sum()
        order = {st["team"]: i for i, st in enumerate(stints[key])}
        lines = []
        for t in grp.itertuples():
            er_outs = club_off.get((*key, t.team))
            outs = er_outs[1] if er_outs else (off * t.ev_outs / tot if off and tot else t.ev_outs)
            ip = outs / 3
            era = 27 * er_outs[0] / er_outs[1] if er_outs and er_outs[1] else (9 * t.runs / ip if ip > 0 else None)
            fip = (13 * t.hr + 3 * (t.bb + t.hbp) - 2 * t.k) / ip + fip_c.get(key[1], 3.1) if ip > 0 else None
            lines.append({"team": t.team, "g": int(t.g), "ip": f(ip, 1),
                          "era": f(era, 2), "eraOfficial": bool(er_outs), "stuffPlus": f(club_whiff.get((*key, t.team)), 1),
                          "fip": f(fip, 2), "whip": f((t.h + t.bb) / ip, 2) if ip > 0 else None,
                          "battersFaced": int(t.pa), "pitches": int(t.n_pitches),
                          "kPct": f(100 * t.k / t.pa, 1) if t.pa else None, "bbPct": f(100 * t.bb / t.pa, 1) if t.pa else None,
                          "kBbPct": f(100 * (t.k - t.bb) / t.pa, 1) if t.pa else None,
                          "cswPct": f(100 * t.csw / t.n_pitches, 1), "whiffPct": f(100 * t.whiff / t.swings, 1) if t.swings else None,
                          "nSwings": int(t.swings),
                          "rvPer100": f(100 * t.rv / t.n_pitches, 2), "velo": f(t.velo, 1)})
        out[key] = sorted(lines, key=lambda x: order.get(x["team"], 99))
    return out


# Pitch explorer: every pitch of a player-season in a compact column form, so the profile can filter
# location / count / outcome / batter hand and draw surfaces and run value client-side.
PITCH_OUTCOMES = ("ball", "called", "whiff", "foul", "out", "1B", "2B", "3B", "HR", "HBP", "other")
PITCH_MIN = 100  # pitches thrown / seen in the season


def _pitch_outcome(desc: pd.Series, ev: pd.Series) -> np.ndarray:
    o = np.full(len(desc), 10, dtype=np.int8)
    o[desc.isin(["ball", "blocked_ball", "pitchout", "intent_ball"]).to_numpy()] = 0
    o[(desc == "called_strike").to_numpy()] = 1
    o[desc.isin(["swinging_strike", "swinging_strike_blocked", "foul_tip", "missed_bunt"]).to_numpy()] = 2
    o[desc.isin(["foul", "foul_bunt", "bunt_foul_tip"]).to_numpy()] = 3
    bip = (desc == "hit_into_play").to_numpy()
    o[bip] = 4
    for code, e in ((5, "single"), (6, "double"), (7, "triple"), (8, "home_run")):
        o[bip & (ev == e).to_numpy()] = code
    o[(desc == "hit_by_pitch").to_numpy()] = 9
    return o


PITCH_FAMILY = {"FF": "Fastball", "SI": "Fastball", "CT": "Fastball", "SL": "Breaking", "SW": "Breaking",
                "CB": "Breaking", "CH": "Offspeed", "FS": "Offspeed"}
BUCKET_AXES = ("v", "iv", "hb")  # velocity mph, induced vertical break in, arm-side horizontal break in
BUCKET_MIN_TYPE = 2000  # league pitches of a type (pooled seasons) before it gets buckets
BUCKET_BOARD_MIN = 30   # a player's pitches in one bucket before he is on the bucket board


def bucket_edges(con, seasons: list[int], site_case: str) -> dict:
    """{type: {axis: [4 edges]}}: league quintiles per site type over the baked seasons, rounded to whole
    mph / inches so the buckets read ("95+ mph", "18+ in"), duplicates dropped. Fixed across seasons."""
    q = con.sql(f"""
        SELECT {site_case} AS site, count(*) AS n,
               quantile_cont(release_speed, [0.2, 0.4, 0.6, 0.8]) AS v,
               quantile_cont(pfx_z * 12, [0.2, 0.4, 0.6, 0.8]) AS iv,
               quantile_cont(CASE WHEN p_throws = 'R' THEN -pfx_x ELSE pfx_x END * 12, [0.2, 0.4, 0.6, 0.8]) AS hb
        FROM pitches_all
        WHERE game_type = 'R' AND season IN ({",".join(map(str, seasons))}) AND pitch_type IS NOT NULL
          AND release_speed IS NOT NULL AND pfx_x IS NOT NULL AND pfx_z IS NOT NULL
        GROUP BY 1""").df()
    return {r.site: {ax: sorted({int(round(e)) for e in getattr(r, ax)}) for ax in BUCKET_AXES}
            for r in q.itertuples() if r.n >= BUCKET_MIN_TYPE and r.site in PITCH_FAMILY}


def _bucket_stats(g) -> dict:
    """n, run value per 100 (pitcher side), whiff per swing, xwOBAcon for one group of pitch rows."""
    sw = g["o"].between(2, 8)
    return {"n": int(len(g)), "rv100": round(float(100 * g["rv"].mean()), 2),
            "whiff": round(float(100 * (g["o"] == 2).sum() / sw.sum()), 1) if sw.sum() else None,
            "xwcon": round(float(g["w"].mean() / 1000), 3) if g["w"].notna().any() else None}


def bake_pitches(con, out: Path, seasons: list[int], site_case: str, level: str = "mlb") -> int:
    """pitches/{P|H}{id}-{season}.json.gz. Columns (same length): t type index into `types`, x/z plate
    location in hundredths of a foot (catcher's view, as Statcast), h opponent hand (0 L, 1 R), c count
    (balls * 3 + strikes), o outcome index into `outcomes`, r run value in thousandths of a run from the
    file owner's side (pitcher: delta_pitcher_run_exp; hitter: its negative), e exit velo x10 and w xwOBA
    x1000 on balls in play (null otherwise), d day of season (0 = his first game), q in the zone
    (Statcast zone 1-9) or not, ba/sl xBA and xSLG x1000 on balls in play; v velo x10, iv IVB and hb
    arm-side HB in tenths of an inch; pe PA end (0 none, 1 K, 2 BB, 3 other) and wv its wOBA value x100
    (null when the PA does not count for wOBA); pitcher files at MLB also carry wp/pp, the pitch's Whiff+
    and Pitching+ x10 on their season scales (cache/pitch_models.parquet from pipeline/whiff_game.py), so
    any slice's grade is their mean; hitter files at MLB carry dv, the pitch's decision value x1000
    (cache/decision_pitches.parquet), and `dec` {mu, sd} so a slice's Decision+ = 100 + 10 (100 mean dv
    / 1000 - mu) / sd. `bins` {type: {axis: edges}} and `lg` {type: {axis: [bucket stats]}} carry the
    movement buckets and the league's line in each (pitcher side). Also writes buckets/{season}-{type}.json,
    the bucket board: per player and bucket (30+ pitches) n, share of his pitches of that type, RV/100,
    whiff, xwOBAcon, both sides."""
    n_files = 0
    pm_fp = ROOT / "cache" / "pitch_models.parquet"
    pm = pd.read_parquet(pm_fp) if level == "mlb" and pm_fp.exists() else None
    if pm is not None:  # a duplicated pitch key would duplicate rows in the merge: drop both copies
        pm = pm.drop_duplicates(["game_pk", "at_bat_number", "pitch_number"], keep=False)
    KEY = ["game_pk", "at_bat_number", "pitch_number"]
    dp_fp = ROOT / "cache" / "decision_pitches.parquet"
    dp = None
    if level == "mlb" and dp_fp.exists():
        dp = pd.read_parquet(dp_fp)
        dp = dp[KEY + ["drv"]].drop_duplicates(KEY, keep=False) if set(KEY) <= set(dp.columns) else None
    dec_f = ROOT / "pipeline" / "results" / "decisions_hitters.csv"
    dec = {}
    if dp is not None and dec_f.exists():
        dh = pd.read_csv(dec_f)
        dh = dh[dh["pa"] >= 100]
        dec = {int(k): {"mu": round(float(g.drv100.mean()), 4), "sd": round(float(g.drv100.std()), 4)} for k, g in dh.groupby("season")}
    edges = bucket_edges(con, seasons, site_case)
    (out / "buckets").mkdir(parents=True, exist_ok=True)
    for season in seasons:
        df = con.sql(f"""
            SELECT pitcher, batter, CAST(game_date AS DATE) AS gd, {site_case} AS site, plate_x, plate_z,
                   stand, p_throws, balls, strikes, description, events, delta_pitcher_run_exp AS rv,
                   launch_speed, estimated_woba_using_speedangle AS xw, estimated_ba_using_speedangle AS xba,
                   estimated_slg_using_speedangle AS xslg, bb_type, sz_top, sz_bot,
                   game_pk, at_bat_number, pitch_number, zone, release_speed, pfx_x, pfx_z, woba_value, woba_denom
            FROM pitches_all
            WHERE game_type = 'R' AND season = {season} AND pitch_type IS NOT NULL
              AND plate_x IS NOT NULL AND plate_z IS NOT NULL AND pitcher IS NOT NULL AND batter IS NOT NULL
            ORDER BY game_date, game_pk, at_bat_number, pitch_number""").df()
        if df.empty:
            continue
        if pm is not None:
            df = df.merge(pm, on=KEY, how="left")
        if dp is not None:
            df = df.merge(dp, on=KEY, how="left")
        o = _pitch_outcome(df["description"], df["events"])
        bip = df["bb_type"].notna().to_numpy()
        ev = df["events"]
        pe = np.where(ev.isin(["strikeout", "strikeout_double_play"]), 1,
                      np.where(ev.isin(["walk", "intent_walk"]), 2, np.where(ev.notna(), 3, 0)))
        hb = np.where(df["p_throws"] == "R", -df["pfx_x"], df["pfx_x"]) * 12
        cols = {"x": np.round(df["plate_x"].to_numpy() * 100).astype(int),
                "z": np.round(df["plate_z"].to_numpy() * 100).astype(int),
                "c": (df["balls"].clip(0, 3) * 3 + df["strikes"].clip(0, 2)).to_numpy().astype(int), "o": o,
                "e": np.where(bip & df["launch_speed"].notna(), np.round(df["launch_speed"].fillna(0) * 10), np.nan),
                "w": np.where(bip & df["xw"].notna(), np.round(df["xw"].fillna(0) * 1000), np.nan),
                "rv": df["rv"].fillna(0).to_numpy(),
                "q": df["zone"].between(1, 9).to_numpy().astype(int),
                "ba": np.where(bip & df["xba"].notna(), np.round(df["xba"].fillna(0) * 1000), np.nan),
                "sl": np.where(bip & df["xslg"].notna(), np.round(df["xslg"].fillna(0) * 1000), np.nan),
                "v": np.round(df["release_speed"].to_numpy(dtype=float) * 10),
                "iv": np.round(df["pfx_z"].to_numpy(dtype=float) * 120),
                "hb": np.round(hb.astype(float) * 10), "pe": pe.astype(int),
                "wv": np.where((pe > 0) & (df["woba_denom"] == 1).to_numpy(), np.round(df["woba_value"].fillna(0) * 100), np.nan)}
        if pm is not None:
            cols["wp"] = np.round(df["whiff_plus"].to_numpy(dtype=float) * 10)
            cols["pp"] = np.round(df["pitching_plus"].to_numpy(dtype=float) * 10)
        if dp is not None:
            cols["dv"] = np.round(df["drv"].to_numpy(dtype=float) * 1000)

        # movement buckets: index of each pitch's bin on each axis (-1 = type has no buckets / no tracking)
        sites = df["site"].to_numpy()
        raw = {"v": df["release_speed"].to_numpy(dtype=float), "iv": df["pfx_z"].to_numpy(dtype=float) * 12, "hb": hb.astype(float)}
        bk = {ax: np.full(len(df), -1, dtype=int) for ax in BUCKET_AXES}
        for t, e in edges.items():
            m = sites == t
            for ax in BUCKET_AXES:
                ok = m & ~np.isnan(raw[ax])
                bk[ax][ok] = np.searchsorted(e[ax], raw[ax][ok], side="right")
        b = pd.DataFrame({"site": sites, "o": o, "rv": cols["rv"], "w": cols["w"],
                          "pitcher": df["pitcher"].to_numpy(), "batter": df["batter"].to_numpy(), **bk})
        lg = {t: {ax: [_bucket_stats(g) for _, g in b[(b["site"] == t) & (b[ax] >= 0)].groupby(ax)]
                  for ax in BUCKET_AXES} for t in edges}
        b = b.assign(sw=b["o"].between(2, 8), wh=b["o"] == 2, wn=b["w"].notna())
        for t in edges:
            bt = b[b["site"] == t]
            rows = []
            for side, who, sign in ((0, "pitcher", 1), (1, "batter", -1)):
                tot = bt.groupby(who).size()
                for ax_i, ax in enumerate(BUCKET_AXES):
                    a = (bt[bt[ax] >= 0].groupby([who, ax])
                         .agg(n=("rv", "size"), rv=("rv", "sum"), sw=("sw", "sum"), wh=("wh", "sum"), ws=("w", "sum"), wn=("wn", "sum"))
                         .reset_index())
                    a = a[a["n"] >= BUCKET_BOARD_MIN]
                    for r in a.itertuples(index=False):
                        pid, k = getattr(r, who), getattr(r, ax)
                        rows.append([str(int(pid)), side, ax_i, int(k), int(r.n), round(100 * r.n / int(tot[pid]), 1),
                                     round(sign * 100 * r.rv / r.n, 2), round(100 * r.wh / r.sw, 1) if r.sw else None,
                                     round(r.ws / r.wn / 1000, 3) if r.wn else None])
            jwrite(out / "buckets" / f"{season}-{t}.json",
                   {"season": season, "type": t, "edges": edges[t], "lg": lg[t],
                    "cols": ["id", "side", "axis", "bin", "n", "share", "rv100", "whiff", "xwcon"],
                    "_comment": "side 0 = pitcher (rv100 pitcher-positive), 1 = hitter (rv100 hitter-positive); "
                                "axis 0 velo, 1 IVB, 2 arm-side HB; bin = index into edges (k = above edges[k-1])",
                    "rows": rows})

        for side, who, opp_hand, sign in (("P", "pitcher", "stand", 1), ("H", "batter", "p_throws", -1)):
            ids = df[who].to_numpy()
            hand = (df[opp_hand] == "R").to_numpy().astype(int)
            for pid, idx in pd.Series(np.arange(len(df))).groupby(ids):
                ix = idx.to_numpy()
                if len(ix) < PITCH_MIN:
                    continue
                psites = sites[ix]
                types = sorted(set(psites), key=lambda t: -int((psites == t).sum()))
                tix = {t: i for i, t in enumerate(types)}
                gd = df["gd"].to_numpy()[ix]
                day = ((gd - gd[0]) / np.timedelta64(1, "D")).astype(int)
                nul = lambda a: [None if np.isnan(v) else int(v) for v in a]  # noqa: E731
                doc = {"id": str(int(pid)), "side": side, "season": season, "types": types,
                       "outcomes": list(PITCH_OUTCOMES), "start": str(gd[0])[:10],
                       "zone": [round(float(np.nanmean(df["sz_bot"].to_numpy()[ix])), 2),
                                round(float(np.nanmean(df["sz_top"].to_numpy()[ix])), 2)],
                       "t": [tix[t] for t in psites], "x": cols["x"][ix].tolist(), "z": cols["z"][ix].tolist(),
                       "h": hand[ix].tolist(), "c": cols["c"][ix].tolist(), "o": cols["o"][ix].tolist(),
                       "r": np.round(sign * cols["rv"][ix] * 1000).astype(int).tolist(), "q": cols["q"][ix].tolist(),
                       "ba": nul(cols["ba"][ix]), "sl": nul(cols["sl"][ix]),
                       "e": nul(cols["e"][ix]), "w": nul(cols["w"][ix]), "d": day.tolist(),
                       "v": nul(cols["v"][ix]), "iv": nul(cols["iv"][ix]), "hb": nul(cols["hb"][ix]),
                       "pe": cols["pe"][ix].tolist(), "wv": nul(cols["wv"][ix]),
                       "bins": {t: edges[t] for t in types if t in edges}, "lg": {t: lg[t] for t in types if t in edges}}
                if side == "P" and "wp" in cols:
                    doc["wp"], doc["pp"] = nul(cols["wp"][ix]), nul(cols["pp"][ix])
                if side == "H" and "dv" in cols:
                    doc["dv"] = nul(cols["dv"][ix])
                    if season in dec:
                        doc["dec"] = dec[season]
                jwrite_gz(out / "pitches" / f"{side}{int(pid)}-{season}.json.gz", doc)
                n_files += 1
        del df, b
        print(f"pitches {season}: {n_files} files so far", flush=True)
    return n_files


def team_stints(con, role: str, season_list: str) -> tuple[dict, dict]:
    """Per player-season: his current team (the team of his most recent game) and, for players who
    changed teams, the stints in order: [{"team", "from", "to", "g"}], dates as YYYY-MM-DD.
    In the top half the home team fields and the away team bats (inning_topbot is 'Top' / 'Bot')."""
    top, other = ("home_team", "away_team") if role == "pitcher" else ("away_team", "home_team")
    df = con.sql(f"""
        SELECT {role} AS id, season, CASE WHEN inning_topbot = 'Top' THEN {top} ELSE {other} END AS team,
               MIN(game_date) AS first, MAX(game_date) AS last, COUNT(DISTINCT game_pk) AS g
        FROM pitches_all
        WHERE game_type = 'R' AND season IN ({season_list}) AND {role} IS NOT NULL
        GROUP BY 1, 2, 3""").df().sort_values(["id", "season", "last", "first"])
    current, stints = {}, {}
    for (pid, season), grp in df.groupby(["id", "season"], sort=False):
        key = (int(pid), int(season))
        current[key] = grp["team"].iloc[-1]
        if len(grp) > 1:
            stints[key] = [{"team": r.team, "from": str(r.first)[:10], "to": str(r.last)[:10], "g": int(r.g)}
                           for r in grp.sort_values(["first", "last"]).itertuples()]
    return current, stints


def season_age(pid, season) -> float | None:
    """Age on June 30 of the season (the Baseball-Reference convention; minors_export uses the same)."""
    b = births().get(int(pid))
    return None if b is None else round((pd.Timestamp(f"{int(season)}-06-30") - b).days / 365.25, 1)


def overlay_aaa_p7(grades: pd.DataFrame) -> pd.DataFrame:
    """Phase 2 (owner): Whiff+ on AAA — the frozen MLB model (s4_bb) scored on AAA
    pitches out of fold, same 100/10 scale. Whiff+ overall / by type (with the
    gyro label) / by class, plus K+ / K proj / Prevention+ (confirmed on AAA by
    frozen transfer, RESULTS-MLB §66). Control+ and Pitching+ are not shipped on
    AAA. The label on every surface that shows it is the model card's: "MLB model
    on AAA data"."""
    m = pd.DataFrame(json.loads(AAA_MODELS_FILE.read_text())["pitchers"])
    m["grade"] = m["whiff_plus"]
    m["stuff_by_type"] = [[{"type": t, "n": e["n"], "grade": e["grade"], "gyro": bool(e.get("sl_gyro"))}
                           for t, e in w.items()] for w in m["whiff_by_type"]]
    m["stuff_by_class"] = m["whiff_by_class"]
    m["pitching_by_class"] = [[] for _ in range(len(m))]
    aaa_p7 = [c for c in ("k_plus", "k_proj", "prevention_plus") if c in m.columns]
    keep = ["mlbam", "season", "grade", "stuff_by_type", "stuff_by_class", "pitching_by_class", *aaa_p7]
    # aaa_population ships None placeholders for these columns (Phase 1's empty
    # grades) — drop them or the merge suffixes every name into _x/_y.
    g = grades.drop(columns=[c for c in keep if c not in ("mlbam", "season")], errors="ignore")
    g = g.merge(m[keep], on=["mlbam", "season"], how="left")
    for c in ("stuff_by_type", "stuff_by_class", "pitching_by_class"):
        g[c] = [x if isinstance(x, list) else [] for x in g[c]]
    return g


def aaa_population(seasons: list[int], table: str = "pitches_aaa") -> pd.DataFrame:
    """The stand-in for the MLB grades artifact: every pitcher-season with 5+ pitches through the
    scoring gate, confidence by the same pitch bands, no v2 grades (overlay_p7 / overlay_aaa_p7 add the
    P7 family). AAA is named from the MiLB lines; MLB seasons the v2 artifact never graded (2020-22)
    from the Chadwick register, and reproduce the artifact's rows exactly where both exist (2024)."""
    con = mart.connect()
    df = con.sql(f"""
        SELECT pitcher AS mlbam, season, mode(p_throws) AS p_throws, COUNT(*) AS pitches_graded
        FROM {table}
        WHERE game_type = 'R' AND season IN ({",".join(str(x) for x in seasons)})
          AND pitch_type IN ('FF','SI','FC','SL','CU','KC','SW','SV','ST','CH','FS','FO','EP')
          AND release_speed BETWEEN 55 AND 105 AND release_extension > 3
          AND pfx_z IS NOT NULL AND pfx_x IS NOT NULL AND release_spin_rate IS NOT NULL
          AND p_throws IN ('L','R') AND stand IN ('L','R') AND pitcher IS NOT NULL
        GROUP BY 1, 2 HAVING COUNT(*) >= 5 ORDER BY 1, 2""").df()
    names = milb_names("pitchers") if table == "pitches_aaa" else dict(con.sql(
        "SELECT CAST(key_mlbam AS BIGINT), name_first || ' ' || name_last FROM register "
        "WHERE TRY_CAST(key_mlbam AS BIGINT) IS NOT NULL").fetchall())
    df["name"] = [names.get(int(m)) for m in df["mlbam"]]
    n = df["pitches_graded"]
    df["confidence"] = np.select([n >= 400, n >= 150, n >= 50], ["HIGH", "MODERATE", "LOW"], "MINIMAL")
    for c in ("grade", "stuff_plus_abs", "pitching_plus", *P7_FIELDS):
        df[c] = None
    for c in ("stuff_by_class", "stuff_by_type", "pitching_by_class"):
        df[c] = [[] for _ in range(len(df))]
    return df


# ---- visuals bake helpers (module level: the heavy per-player fits run in a
# worker pool; pure functions of their inputs, so results are byte-identical
# regardless of worker count — DuckDB's threads=1 determinism rule is about the
# database scans, not these in-memory fits).
VIS_GRID_N = 44
VIS_LOC_X = (-1.9, 1.9)
VIS_LOC_Z = (0.4, 4.6)


def _kde_curve(vals: list[float], lo: float, hi: float, bw_min: float = 0.4,
               samples: int = 240) -> tuple[list[float], list[float], dict]:
    """Usage-scaled 1D gaussian KDE on a shared grid. Silverman's window with
    the college's 0.4-mph floor: below it a curve would draw measurement noise
    as arsenal structure."""
    import numpy as _np
    x = _np.asarray(vals, dtype=float)
    n = len(x)
    sd = float(x.std())
    iqr = float(_np.subtract(*_np.percentile(x, [75, 25]))) if n > 3 else 0.0
    scale = min(sd, iqr / 1.34) if iqr > 0 else sd
    bw = max(bw_min, 0.9 * scale * n ** (-0.2))
    grid = _np.linspace(lo, hi, samples)
    z = (grid[:, None] - x[None, :]) / bw
    dens = _np.exp(-0.5 * z ** 2).sum(axis=1) / (n * bw * float(_np.sqrt(2 * _np.pi)))
    peak = int(dens.argmax())
    return ([float(v) for v in grid], [round(float(v), 5) for v in dens],
            {"peak_x": round(float(grid[peak]), 2), "peak_y": round(float(dens[peak]), 5)})


# Module-level alias: the visuals family shadows `_kde_curve` with a nested
# redefinition inside _bake_inner, which makes the module function unreachable
# from other families (Python binds the name for the whole function). Same
# pattern as the DETAIL_GATE hoist.
sw_kde_curve = _kde_curve


def _stride(points: list, cap: int) -> list:
    """Deterministic thinning for dot clouds: keep the order, cap the count."""
    if len(points) <= cap:
        return points
    return points[:: len(points) // cap + 1]


sw_stride = _stride


def _loc_grid(px: list, pz: list) -> dict | None:
    """Per-type density grid over the zone frame, max-normalised. Under 40
    pitches a density is a picture of the bandwidth — the panel falls back to
    the raw points instead."""
    if len(px) < 40:
        pts = _stride(list(zip(px, pz)), 120)
        return {"n": len(px), "pts": [[a, b] for a, b in pts]}
    try:
        from scipy.stats import gaussian_kde
        import numpy as _np
        vals = _np.vstack([_np.asarray(px[:800], dtype=float), _np.asarray(pz[:800], dtype=float)])
        kde = gaussian_kde(vals)
        gx = _np.linspace(*VIS_LOC_X, VIS_GRID_N)
        gz = _np.linspace(*VIS_LOC_Z, VIS_GRID_N)
        mesh_x, mesh_z = _np.meshgrid(gx, gz)
        dens = kde(_np.vstack([mesh_x.ravel(), mesh_z.ravel()])).reshape(VIS_GRID_N, VIS_GRID_N)
        top = float(dens.max())
        if top <= 0:
            return None
        return {"n": len(px), "max": round(top, 3),
                "cells": [[round(float(v) / top, 4) for v in row] for row in dens]}
    except Exception:
        return None


def _visuals_payload(task: tuple):
    """The expensive half of one pitcher-season's visuals file: velocity KDEs,
    spin dots, release cloud, location grids. Everything here is a pure
    function of `b` (the pitch bucket); the cheap aggregates (count lattice,
    handedness mix) are joined by the caller."""
    import numpy as _np
    pid, season, b, zone = task
    all_v = [v for col in b.values() for v in col["v"]]
    if len(all_v) < 50:
        return None
    lo = round(min(all_v) - 1.0, 1)
    hi = round(max(all_v) + 1.0, 1)
    total_tracked = len(all_v)
    series = []
    for site, col in sorted(b.items(), key=lambda kv: -len(kv[1]["v"])):
        vals = col["v"]
        if not vals:
            continue
        share = len(vals) / total_tracked
        if len(vals) >= 15:
            grid, dens, pk = _kde_curve(vals, lo, hi)
            series.append({"t": site, "n": len(vals), "share": round(share, 4),
                           "mean": round(float(_np.mean(vals)), 1),
                           "points": [[round(x, 2), y] for x, y in zip(grid, dens)], **pk})
        else:
            series.append({"t": site, "n": len(vals), "share": round(share, 4),
                           "mean": round(float(_np.mean(vals)), 1),
                           "points": [], "ticks": [round(v, 1) for v in sorted(vals)]})
    dots = []
    for site, col in b.items():
        for axis, rpm in zip(col["ax"], col["rpm"]):
            dots.append([site, round(axis / 5.0) * 5, round((rpm or 0) / 10.0) * 10])
    dots = _stride(sorted(dots, key=lambda d: (d[0], d[1], d[2])), 1200)
    rel_pts, rel_types = [], {}
    for site, col in b.items():
        n_rel = len(col["rx"])
        if n_rel < 5:
            continue
        rel_types[site] = {
            "n": n_rel,
            "rh": round(float(_np.mean(col["rz"])), 2), "rs": round(float(_np.mean(col["rx"])), 2),
            "sdh": round(float(_np.std(col["rz"])), 2), "sds": round(float(_np.std(col["rx"])), 2),
        }
        rel_pts.extend(_stride([[site, col["rz"][i], col["rx"][i]] for i in range(n_rel)], 400))
    loc = {}
    for site, col in b.items():
        g2 = _loc_grid(col["px"], col["pz"])
        if g2:
            loc[site] = g2
    return (pid, season, {
        "id": str(pid), "side": "P", "season": season, "zone": zone,
        "velo": {"domain": [lo, hi], "total": total_tracked, "series": series},
        "spin": {"dots": dots},
        "release": {"points": rel_pts, "types": rel_types},
        "loc": {"x": VIS_LOC_X, "z": VIS_LOC_Z, "n": VIS_GRID_N, "types": loc},
    })


def run_bake(out: Path, seasons: list[int], only: set[str] | None, player: int | None, level: str = "mlb") -> dict:
    """One full pass. `only` limits the families baked (None = all); `player`
    limits the per-player file loops. Returns a counts dict for the log.

    Guarded by a lock file in the output directory: two agents share this
    working tree, and overlapping bakes writing one export dir produced the
    intermittent --check diffs of 2026-10-28. A stale lock (dead pid) breaks."""
    with bake_lock(out):
        return _bake_inner(out, seasons, only, player, level)


@contextlib.contextmanager
def bake_lock(out: Path):
    """Hold <out>/BAKE_LOCK for the block; refuse while a live pid holds it, break a dead one."""
    lock_path = Path(out) / "BAKE_LOCK"
    if lock_path.exists():
        try:
            other = int(lock_path.read_text().strip() or 0)
            os.kill(other, 0)
            raise SystemExit(f"another bake holds {lock_path} (pid {other}); if it is dead, delete the lock file")
        except (ProcessLookupError, ValueError):
            pass
        except PermissionError:
            raise SystemExit(f"another bake holds {lock_path} (pid belongs to another user)")
    lock_path.parent.mkdir(parents=True, exist_ok=True)
    lock_path.write_text(str(os.getpid()))
    try:
        yield
    finally:
        lock_path.unlink(missing_ok=True)


def _bake_inner(out: Path, seasons: list[int], only: set[str] | None, player: int | None, level: str = "mlb") -> dict:
    t0 = time.time()
    pf = ROOT / "pipeline" / "results" / "park_factors.json"  # §70 (D-04): venue factors, any family's bake
    if level == "mlb" and pf.exists():
        out.mkdir(parents=True, exist_ok=True)
        jwrite(out / "parks.json", json.loads(pf.read_text()))
    fams = only if only else set(FAMILIES)
    wanted = set().union(*(FAM_NEEDS[fam] for fam in fams))
    season_csv = ",".join(str(s) for s in seasons)
    counts: dict = {}

    grades_doc = json.loads(GRADES_FILE.read_text())
    model_card = grades_doc["model_card"]
    if level == "aaa":
        grades = overlay_aaa_p7(aaa_population(seasons))
    else:
        grades = pd.DataFrame(grades_doc["grades"])
        grades = grades[grades["season"].isin(seasons)].copy()
        older = [x for x in seasons if x not in set(grades["season"])]  # 2020-22: v2 never graded them
        if older:
            grades = pd.concat([grades, aaa_population(older, "pitches_all")], ignore_index=True)
        grades = grades.sort_values(["mlbam", "season"])
        grades = overlay_p7(grades)
    class_key = model_card["class_key"]
    print(f"grades: {len(grades)} pitcher-seasons across {sorted(grades.season.unique())}; "
          f"families: {sorted(fams)}")

    con = mart.connect()
    # Determinism is a correctness requirement here, not a nicety: r2_sync
    # uploads on md5 change, and a parallel aggregation that combines partial
    # sums in scheduler order flips the last float bit run-to-run — a rounding
    # boundary (0.28 vs 0.27) then wobbles between bakes and re-uploads keys
    # forever. Single-threaded scans accumulate in file order, so the same
    # inputs bake byte-identical outputs (--check proves it).
    con.execute("SET threads TO 1")
    if level == "aaa":
        # every pitches_all query below reads AAA instead; the temp view shadows the mart's
        con.execute("CREATE OR REPLACE TEMP VIEW pitches_all AS SELECT * FROM pitches_aaa")
    season_list = ",".join(str(s) for s in seasons)

    scoring_cte = """WITH px AS (
          SELECT game_pk, inning_topbot, at_bat_number, pitcher, season, events, bb_type, description,
                 p_throws, release_speed, pfx_z, pfx_x, release_extension, delta_pitcher_run_exp,
                 zone, balls, strikes, type
          FROM pitches_all
          WHERE game_type = 'R' AND season IN (%(season_list)s)
            AND pitch_type IN ('FF','SI','FC','SL','CU','KC','SW','SV','ST','CH','FS','FO','EP')
            AND release_speed BETWEEN 55 AND 105 AND release_extension > 3
            AND pfx_z IS NOT NULL AND pfx_x IS NOT NULL AND release_spin_rate IS NOT NULL
            AND p_throws IN ('L','R') AND stand IN ('L','R') AND pitcher IS NOT NULL
        ),
        -- runs while he pitched: the batting side's score change on each of his pitches (every
        -- pitch, ungated, so wild-pitch / steal-of-home runs count). A runner inherited by the next
        -- pitcher scores on someone else's pitch and charges there (RE24-style), not to the pitcher
        -- who put him on. The site's ERA uses the official earned runs instead where the MLB Stats
        -- API line exists (official_er); this is the fallback and the RA9 behind it. (Until
        -- 2026-10-27 this read the FIELDING side's score, which inflated every ERA and FIP.)
        scored AS (
          SELECT pitcher, season, post_bat_score - bat_score AS runs_pa
          FROM pitches_all
          WHERE game_type = 'R' AND season IN (%(season_list)s) AND pitcher IS NOT NULL
        ),
        runs_by_p AS (SELECT pitcher, season, SUM(runs_pa) AS runs FROM scored GROUP BY 1, 2)
""".replace("%(season_list)s", season_list)

    # ---------------------------------------------------------------- totals
    # One pitcher-season per row, per the FEATURE_SQL pitch gates so the raw
    # rates describe the same pitches the grades do.
    totals = team_map = tot_n = tot_team = tot_indexed = None
    team_stints_p: dict = {}
    team_split_p: dict = {}
    gs_map: dict = {}
    hitter_pct_out = None
    pitcher_shrunk_out = None
    if "totals" in wanted:
        totals = con.sql(f"""
            {scoring_cte},
            agg AS (
            SELECT pitcher AS id, season,
                   COUNT(*) AS n_pitches,
                   COUNT(DISTINCT (game_pk, at_bat_number)) AS pa,
                   SUM(CASE WHEN description IN ('called_strike','swinging_strike','swinging_strike_blocked','foul_tip') THEN 1 ELSE 0 END) AS csw,
                   SUM(CASE WHEN description IN ('swinging_strike','swinging_strike_blocked','foul_tip') THEN 1 ELSE 0 END) AS whiff,
                   SUM(CASE WHEN description IN ('swinging_strike','swinging_strike_blocked','foul','foul_tip','foul_bunt','missed_bunt','bunt_foul_tip','hit_into_play') THEN 1 ELSE 0 END) AS swings,
                   SUM(CASE WHEN description IN {TAKEN} THEN 1 ELSE 0 END) AS taken,
                   SUM(CASE WHEN events IN ('strikeout','strikeout_double_play') THEN 1 ELSE 0 END) AS k,
                   SUM(CASE WHEN events IN ('walk','intent_walk') THEN 1 ELSE 0 END) AS bb,  -- all walks; ibb split out
                   SUM(CASE WHEN events = 'intent_walk' THEN 1 ELSE 0 END) AS ibb,
                   SUM(CASE WHEN events = 'hit_by_pitch' THEN 1 ELSE 0 END) AS hbp,
                   SUM(CASE WHEN events IN {BB_EVENTS} THEN 1 ELSE 0 END) AS h,
                   SUM(CASE WHEN events = 'home_run' THEN 1 ELSE 0 END) AS hr,
                   SUM(CASE WHEN events IN {OUT_EVENTS_1} THEN 1 ELSE 0 END
                        + CASE WHEN events IN {OUT_EVENTS_2} THEN 2 ELSE 0 END
                        + CASE WHEN events IN {OUT_EVENTS_3} THEN 3 ELSE 0 END) AS outs,
                   SUM(CASE WHEN bb_type = 'ground_ball' THEN 1 ELSE 0 END) AS gb,
                   SUM(CASE WHEN bb_type IS NOT NULL THEN 1 ELSE 0 END) AS bip,
                   -- plate-discipline denominators (P4, raw rates; the EB shrinkage
                   -- constants wait on the MLB re-measure)
                   SUM(CASE WHEN zone BETWEEN 1 AND 9 THEN 1 ELSE 0 END) AS n_zone,
                   SUM(CASE WHEN zone BETWEEN 10 AND 14 THEN 1 ELSE 0 END) AS n_ooz,
                   SUM(CASE WHEN zone BETWEEN 10 AND 14 AND description IN {SWING} THEN 1 ELSE 0 END) AS n_ooz_swing,
                   SUM(CASE WHEN zone BETWEEN 10 AND 14 AND description IN {WHIFF} THEN 1 ELSE 0 END) AS n_ooz_whiff,
                   SUM(CASE WHEN zone BETWEEN 1 AND 9 AND description IN {SWING} THEN 1 ELSE 0 END) AS n_zone_swing,
                   SUM(CASE WHEN zone BETWEEN 1 AND 9 AND description IN ('swinging_strike','swinging_strike_blocked','foul_tip') THEN 1 ELSE 0 END) AS n_zone_whiff,
                   SUM(CASE WHEN zone BETWEEN 1 AND 9 AND description IN {SWING} THEN 1 ELSE 0 END
                        - CASE WHEN zone BETWEEN 1 AND 9 AND description IN ('swinging_strike','swinging_strike_blocked','foul_tip') THEN 1 ELSE 0 END) AS n_zone_contact,
                   SUM(CASE WHEN balls = 0 AND strikes = 0 THEN 1 ELSE 0 END) AS n_first_pitch,
                   SUM(CASE WHEN balls = 0 AND strikes = 0 AND (type = 'S') THEN 1 ELSE 0 END) AS n_first_pitch_strike,
                   SUM(CASE WHEN strikes = 2 THEN 1 ELSE 0 END) AS n_two_strike,
                   SUM(CASE WHEN strikes = 2 AND description IN ('called_strike','swinging_strike','swinging_strike_blocked','foul_tip') THEN 1 ELSE 0 END) AS n_two_strike_csw,
                   -- measured run value, PITCHER-positive: Statcast attributes the run
                   -- expectancy change of every pitch to the pitcher on the mound.
                   SUM(delta_pitcher_run_exp) AS rv,
                   AVG(release_speed) AS velo,
                   AVG(pfx_z) * 12 AS ivb,
                   AVG(pfx_x) * 12 AS hb,
                   AVG(release_extension) AS ext,
                   mode(p_throws) AS throws
            FROM px GROUP BY pitcher, season
            )
            SELECT agg.*, COALESCE(r.runs, 0) AS runs
            FROM agg LEFT JOIN runs_by_p r ON r.pitcher = agg.id AND r.season = agg.season
        """).df()
        totals["id"] = totals["id"].astype(int)
        # Counting stats from every PA, ungated (the px gate drops automatic IBBs, untracked pitches and
        # knuckleballs, which undercounted K, BB, H, HR and PA); the pitch-quality rates stay on px.
        ev_c = con.sql(f"""
            SELECT pitcher AS id, season,
                   COUNT(DISTINCT (game_pk, at_bat_number)) FILTER (WHERE events IS NOT NULL AND events <> 'truncated_pa') AS pa,
                   COUNT(*) FILTER (WHERE events IN ('strikeout','strikeout_double_play')) AS k,
                   COUNT(*) FILTER (WHERE events IN ('walk','intent_walk')) AS bb,
                   COUNT(*) FILTER (WHERE events = 'intent_walk') AS ibb,
                   COUNT(*) FILTER (WHERE events = 'hit_by_pitch') AS hbp,
                   COUNT(*) FILTER (WHERE events IN {BB_EVENTS}) AS h,
                   COUNT(*) FILTER (WHERE events = 'home_run') AS hr
            FROM pitches_all WHERE game_type = 'R' AND season IN ({season_csv}) AND pitcher IS NOT NULL
            GROUP BY 1, 2""").df()
        ev_c["id"] = ev_c["id"].astype(int)
        totals = totals.drop(columns=[c for c in ev_c.columns if c not in ("id", "season")]).merge(
            ev_c, on=["id", "season"], how="left")
        # IP: official outs from the Stats API lines where they exist. Statcast events never carry outs on
        # the bases (caught stealing, pickoffs, runners thrown out), so event outs run short (Valdez 2024
        # 147.7 IP vs 176.1 official).
        oo = official_er(level)
        totals["outs"] = [oo[k][1] if k in oo and oo[k][1] > 0 else o
                          for k, o in zip(zip(totals["id"], totals["season"].astype(int)), totals["outs"])]
        totals = totals.sort_values(["id", "season"])
        team_map, team_stints_p = team_stints(con, "pitcher", season_list)
        # G/GS: official lines first; Statcast fallback = games pitched, and games where he threw his
        # side's first pitch (first PA of the 1st inning, his half).
        gs_sc = con.sql(f"""
            WITH st AS (SELECT game_pk, inning_topbot, arg_min(pitcher, at_bat_number) AS p
                        FROM pitches_all WHERE game_type = 'R' AND season IN ({season_list}) AND inning = 1
                        GROUP BY 1, 2)
            SELECT x.pitcher AS id, x.season, COUNT(DISTINCT x.game_pk) AS g,
                   COUNT(DISTINCT x.game_pk) FILTER (WHERE st.p = x.pitcher) AS gs
            FROM pitches_all x LEFT JOIN st USING (game_pk, inning_topbot)
            WHERE x.game_type = 'R' AND x.season IN ({season_list}) AND x.pitcher IS NOT NULL
            GROUP BY 1, 2""").df()
        og = official_gs(level)
        gs_map = {(int(r.id), int(r.season)): og.get((int(r.id), int(r.season))) or (int(r.g), int(r.gs))
                  for r in gs_sc.itertuples()}
        tot_n = {(int(row.id), int(row.season)): int(row.n_pitches) for row in totals.itertuples()}
        tot_team = dict(team_map)
        tot_indexed = totals.set_index(["id", "season"])

    # ------------------------------------------------- who is a real pitcher
    # Roster snapshots (40-man, position_abbrev) are primary evidence. A graded
    # id whose current roster position is not P is a position player who mopped
    # up an inning — Hedges, Yastrzemski & co. — excluded everywhere. Ids no
    # snapshot covers (retired/traded arms) are kept, except a season under
    # 2 IP, which is a mop-up appearance by whoever it was. Rules recorded in
    # meta.json; the grades artifact itself is untouched.
    pos_df = con.sql(f"""
        SELECT person_id, arg_max(position_abbrev, date) AS pos
        FROM read_parquet('{MART_DIR}/data/daily/rosters_*.parquet')
        GROUP BY 1
    """).df()
    non_pitchers = {int(row.person_id) for row in pos_df.itertuples() if row.pos not in ("P", "TWP")}
    covered = {int(row.person_id) for row in pos_df.itertuples()}
    uncovered = {int(x) for x in grades["mlbam"].unique()} - covered
    ip_uncovered = con.sql(f"""
        SELECT pitcher, season,
               SUM(CASE WHEN events IN ('field_out','force_out','fielders_choice_out','strikeout',
                    'strikeout_double_play','sac_fly','sac_bunt','grounded_into_double_play','double_play',
                    'triple_play','caught_stealing','pickoff_1b','pickoff_2b','pickoff_3b',
                    'caught_stealing_2b','caught_stealing_3b','other_out') THEN 1 ELSE 0 END
                 + CASE WHEN events IN ('double_play','strikeout_double_play','sac_fly_dp',
                    'grounded_into_double_play') THEN 1 ELSE 0 END) / 3.0 AS ip
        FROM pitches_all
        WHERE game_type = 'R' AND pitcher IN ({','.join(map(str, uncovered)) or '0'})
          AND pitch_type IN ('FF','SI','FC','SL','CU','KC','SW','SV','ST','CH','FS','FO','EP')
          AND release_speed BETWEEN 55 AND 105 AND release_extension > 3
          AND pfx_z IS NOT NULL AND pfx_x IS NOT NULL AND release_spin_rate IS NOT NULL
          AND p_throws IN ('L','R') AND stand IN ('L','R')
        GROUP BY 1, 2
    """).df()
    # Same pitch gates as the board: a position player's lobbed eephus never
    # reaches the graded rows, so it must not count toward his IP either.
    thin_uncovered = {(int(row.pitcher), int(row.season)) for row in ip_uncovered.itertuples() if row.ip < 2.0}
    print(f"excluded: {len(non_pitchers)} non-pitcher ids (roster evidence); "
          f"{len(thin_uncovered)} thin uncovered pitcher-seasons")

    def keep_row(pid: int, season: int) -> bool:
        """A graded pitcher-season the web surfaces may show."""
        return pid not in non_pitchers and (pid, season) not in thin_uncovered

    logos = fetch_logos(out, ({v for v in team_map.values() if v} if team_map else set()))

    # League FIP constant per season, from this same mart (self-consistent; not quoted).
    fip_c = None
    if "fip" in wanted:
        lg = con.sql(f"""
            {scoring_cte},
            agg AS (
            SELECT season,
                   SUM(CASE WHEN events IN {OUT_EVENTS_1} THEN 1 ELSE 0 END
                        + CASE WHEN events IN {OUT_EVENTS_2} THEN 2 ELSE 0 END
                        + CASE WHEN events IN {OUT_EVENTS_3} THEN 3 ELSE 0 END) AS outs,
                   SUM(CASE WHEN events = 'home_run' THEN 1 ELSE 0 END) AS hr,
                   SUM(CASE WHEN events IN ('walk','intent_walk') THEN 1 ELSE 0 END) AS bb,  -- all walks; ibb split out
                   SUM(CASE WHEN events = 'intent_walk' THEN 1 ELSE 0 END) AS ibb,
                   SUM(CASE WHEN events = 'hit_by_pitch' THEN 1 ELSE 0 END) AS hbp,
                   SUM(CASE WHEN events IN ('strikeout','strikeout_double_play') THEN 1 ELSE 0 END) AS k
            FROM pitches_all  -- every PA, ungated: automatic IBBs and untracked pitches have no pitch data
            WHERE game_type = 'R' AND season IN ({season_csv}) AND pitcher IS NOT NULL
            GROUP BY season
            )
            SELECT agg.*, COALESCE(r.runs, 0) AS runs
            FROM agg LEFT JOIN (SELECT season, SUM(runs) AS runs FROM runs_by_p GROUP BY 1) r USING (season)
        """).df()
        lg_oo: dict = {}  # official league outs, as for players
        for (_, lg_s), (_, lg_o) in official_er(level).items():
            lg_oo[lg_s] = lg_oo.get(lg_s, 0) + lg_o
        lg["outs"] = [lg_oo.get(s, o) for s, o in zip(lg["season"], lg["outs"])]
        lg["ra9"] = 9 * lg["runs"] / (lg["outs"] / 3)
        # FIP is scaled to ERA: the official league ERA per season where the lines exist
        oer = pd.DataFrame([(s, e, o) for (_, s), (e, o) in official_er(level).items()], columns=["season", "er", "o"])
        lg_era = (27 * oer.groupby("season")["er"].sum() / oer.groupby("season")["o"].sum()) if len(oer) else pd.Series(dtype=float)
        lg["ra9"] = [lg_era.get(s, rr) for s, rr in zip(lg["season"], lg["ra9"])]
        lg["fip_raw"] = (13 * lg["hr"] + 3 * (lg["bb"] + lg["hbp"]) - 2 * lg["k"]) / (lg["outs"] / 3)
        lg["c"] = lg["ra9"] - lg["fip_raw"]
        fip_c = dict(zip(lg["season"], lg["c"]))
        print("league FIP constant:", {int(k): round(v, 3) for k, v in fip_c.items()})
        team_split_p = pitcher_team_splits(con, season_list, team_stints_p, level, fip_c)

    # ------------------------------------------------------- per pitch type
    bytype = None
    if "bytype" in wanted:
        bytype = con.sql(f"""
            SELECT pitcher AS id, season, pitch_type,
                   COUNT(*) AS n,
                   SUM(CASE WHEN type = 'S' THEN 1 ELSE 0 END) AS strikes,
                   SUM(CASE WHEN description IN ('called_strike','swinging_strike','swinging_strike_blocked','foul_tip') THEN 1 ELSE 0 END) AS csw,
                   SUM(CASE WHEN description IN ('swinging_strike','swinging_strike_blocked','foul_tip') THEN 1 ELSE 0 END) AS whiff,
                   SUM(CASE WHEN description IN {SWING} THEN 1 ELSE 0 END) AS swings,
                   SUM(CASE WHEN description IN {TAKEN} THEN 1 ELSE 0 END) AS taken,
                   SUM(CASE WHEN zone BETWEEN 1 AND 9 THEN 1 ELSE 0 END) AS n_zone,
                   SUM(CASE WHEN zone BETWEEN 1 AND 3 THEN 1 ELSE 0 END) AS n_high,
                   SUM(CASE WHEN zone BETWEEN 7 AND 9 THEN 1 ELSE 0 END) AS n_low,
                   SUM(CASE WHEN zone BETWEEN 10 AND 14 AND description IN {WHIFF} THEN 1 ELSE 0 END) AS n_ooz_whiff,
                   SUM(CASE WHEN zone BETWEEN 10 AND 14 AND description IN {SWING} THEN 1 ELSE 0 END) AS n_ooz_swing,
                   SUM(CASE WHEN zone BETWEEN 10 AND 14 THEN 1 ELSE 0 END) AS n_ooz,
                   SUM(CASE WHEN zone BETWEEN 1 AND 9 AND description IN {SWING} THEN 1 ELSE 0 END) AS n_zone_swing,
                   SUM(CASE WHEN zone BETWEEN 1 AND 9 AND description IN ('swinging_strike','swinging_strike_blocked','foul_tip') THEN 1 ELSE 0 END) AS n_zone_whiff,
                   SUM(CASE WHEN zone BETWEEN 1 AND 9 AND description IN {SWING} THEN 1 ELSE 0 END
                        - CASE WHEN zone BETWEEN 1 AND 9 AND description IN ('swinging_strike','swinging_strike_blocked','foul_tip') THEN 1 ELSE 0 END) AS n_zone_contact,
                   SUM(CASE WHEN balls = 0 AND strikes = 0 THEN 1 ELSE 0 END) AS n_first_pitch,
                   SUM(CASE WHEN balls = 0 AND strikes = 0 AND (type = 'S') THEN 1 ELSE 0 END) AS n_first_pitch_strike,
                   SUM(CASE WHEN strikes = 2 THEN 1 ELSE 0 END) AS n_two_strike,
                   SUM(CASE WHEN strikes = 2 AND description IN ('called_strike','swinging_strike','swinging_strike_blocked','foul_tip') THEN 1 ELSE 0 END) AS n_two_strike_csw,
                   AVG(release_speed) AS velo,
                   AVG(pfx_z) * 12 AS ivb,
                   AVG(pfx_x) * 12 AS hb,
                   AVG(release_spin_rate) AS spin,
                   AVG(release_extension) AS ext,
                   AVG(release_pos_z) AS rel_h,
                   AVG(release_pos_x) AS rel_s,
                   AVG(CASE WHEN arm_angle IS NOT NULL THEN arm_angle END) AS arm_angle,
                   AVG(launch_speed) FILTER (WHERE bb_type IS NOT NULL AND des NOT ILIKE '%bunt%') AS ev,
                   AVG(launch_angle) FILTER (WHERE bb_type IS NOT NULL AND des NOT ILIKE '%bunt%') AS la,
                   SUM(CASE WHEN bb_type = 'ground_ball' THEN 1 ELSE 0 END) AS gb,
                   SUM(CASE WHEN bb_type = 'fly_ball' THEN 1 ELSE 0 END) AS fb,
                   SUM(CASE WHEN bb_type = 'line_drive' THEN 1 ELSE 0 END) AS ld,
                   SUM(CASE WHEN bb_type = 'popup' THEN 1 ELSE 0 END) AS pu,
                   SUM(CASE WHEN bb_type IS NOT NULL THEN 1 ELSE 0 END) AS n_bip,
                   SUM(CASE WHEN bb_type IS NOT NULL AND launch_speed >= 95 THEN 1 ELSE 0 END) AS n_hard,
                   -- measured per-type run value (pitcher-positive) + PA reach, for the
                   -- arsenal rows and the per-pitch run-value card
                   SUM(delta_pitcher_run_exp) AS rv,
                   COUNT(DISTINCT (game_pk, at_bat_number)) AS n_pa,
                   -- within-type movement scatter, for the arsenal mix metrics (PP11)
                   STDDEV(pfx_z) * 12 AS ivb_sd,
                   STDDEV(pfx_x) * 12 AS hb_sd,
                   -- VAA at the plate, the train_mlb construction (train season window irrelevant here)
                   AVG(CASE WHEN vy0 < 0 THEN
                         degrees(atan2(vz0 + az * ((50.0 - 1.417) / (-vy0)),
                                       -(vy0 + ay * ((50.0 - 1.417) / (-vy0))))) END) AS vaa
            FROM pitches_all
            WHERE game_type = 'R' AND season IN ({season_list})
              AND pitch_type IN ('FF','SI','FC','SL','CU','KC','SW','SV','ST','CH','FS','FO','EP')
              AND release_speed BETWEEN 55 AND 105
              AND release_extension > 3
              AND pfx_z IS NOT NULL AND pfx_x IS NOT NULL AND release_spin_rate IS NOT NULL
              AND p_throws IN ('L','R') AND stand IN ('L','R')
              AND pitcher IS NOT NULL
            GROUP BY pitcher, season, pitch_type
        """).df()
        bytype["id"] = bytype["id"].astype(int)
        bytype["site"] = bytype["pitch_type"].map(SC_TO_SITE)
        bytype = bytype.sort_values(["id", "season", "pitch_type"])

    # ------------------------------------------------------ class × VAA cells
    # cell = plate height third x arm/mid/glove, descriptive; feeds the profile
    # grid and the league breakpoint file.
    cells = league_cells = vaa_file = None
    if "cells" in wanted:
        cells = con.sql(f"""
            WITH px AS (
              SELECT pitcher AS id, season, pitch_type,
                     release_pos_x, p_throws,
                     CASE WHEN plate_x * (CASE WHEN p_throws = 'R' THEN 1 ELSE -1 END) > 0.28 THEN 'arm'
                          WHEN plate_x * (CASE WHEN p_throws = 'R' THEN 1 ELSE -1 END) < -0.28 THEN 'glove'
                          ELSE 'mid' END AS zx,
                     CASE WHEN plate_z > sz_bot + 0.67 * (sz_top - sz_bot) THEN 'high'
                          WHEN plate_z < sz_bot + 0.33 * (sz_top - sz_bot) THEN 'low'
                          ELSE 'mid' END AS zz,
                     CASE WHEN vy0 < 0 THEN degrees(atan2(vz0 + az * ((50.0 - 1.417) / (-vy0)),
                          -(vy0 + ay * ((50.0 - 1.417) / (-vy0))))) END AS vaa
              FROM pitches_all
              WHERE game_type = 'R' AND season IN ({season_list})
                AND pitch_type IN ('FF','SI','FC','SL','CU','KC','SW','SV','ST','CH','FS','FO','EP')
                AND release_speed BETWEEN 55 AND 105 AND release_extension > 3
                AND pfx_z IS NOT NULL AND pfx_x IS NOT NULL AND release_spin_rate IS NOT NULL
                AND p_throws IN ('L','R') AND stand IN ('L','R')
                AND plate_z IS NOT NULL AND sz_top > sz_bot AND vy0 < 0
            )
            SELECT id, season, pitch_type, zx, zz, COUNT(*) AS n, AVG(vaa) AS avg_vaa
            FROM px GROUP BY 1, 2, 3, 4, 5
        """).df()
        cells["site"] = cells["pitch_type"].map(SC_TO_SITE)
        cells = cells.sort_values(["id", "season", "pitch_type", "zx", "zz"])

        league_cells = (cells.groupby(["site", "zx", "zz"])
                        .agg(n=("id", "nunique"), q_src=("avg_vaa", lambda s: list(s)))
                        .reset_index()
                        .sort_values(["site", "zx", "zz"]))
        vaa_file = {
            "_comment": "League VAA breakpoints per pitch type x zone cell (site codes). "
                        "Direction omitted: descriptive on MLB (flatter-is-better not re-measured).",
            "season": season_csv,
            "floor": VAA_CELL_FLOOR,
            "direction": {},
            "cells": {},
        }
        for _, row in league_cells.iterrows():
            q = dense_q(row["q_src"])
            if q is not None and row["n"] >= LEAGUE_CELL_MIN_PITCHERS:
                vaa_file["cells"].setdefault(row["site"], {})[f"{row['zz']}-{row['zx']}"] = {"q": q, "n": int(row["n"])}

    # ------------------------------------------------- join grades -> rows
    g = grades.set_index(["mlbam", "season"])
    conf_floor = {"HIGH": 400, "MODERATE": 150, "LOW": 50}

    # Per-type grades (owner ship decision, RESULTS-MLB §38): the shrunk type
    # prediction replaces the shared class grade on every TYPE row; the class
    # grade stays only as the fallback when a type has no grade. The pitcher's
    # overall Stuff+ is untouched.
    type_grade = {}
    for _, gr in grades.iterrows():
        for entry in gr.get("stuff_by_type") or []:
            type_grade[(int(gr["mlbam"]), int(gr["season"]), entry["type"])] = (entry["grade"], entry["n"])

    # The P7 export's SL gyro flag (T2, §48): a display label only — same
    # pooled slider grade and scale. Rides on SL rows as `gyro`.
    type_gyro = {(int(gr["mlbam"]), int(gr["season"]), entry["type"])
                 for _, gr in grades.iterrows() for entry in (gr.get("stuff_by_type") or [])
                 if entry.get("gyro")}

    class_grade = {}
    for _, gr in grades.iterrows():
        for entry in gr["stuff_by_class"]:
            class_grade[(int(gr["mlbam"]), int(gr["season"]), entry["class"])] = (entry["grade"], entry["n"])
        for entry in gr.get("pitching_by_class", []):
            class_grade[(int(gr["mlbam"]), int(gr["season"]), "P:" + entry["class"])] = (entry["grade"], entry["n"])

    season_iter: list[tuple[int, int]] = []
    latest_ok = False
    if ("players" in fams or "slot" in fams) and tot_indexed is not None:
        # One file per graded (pid, season) — a leaderboard row must open the profile
        # of the season the reader clicked — plus the plain {pid}.json = latest season.
        season_iter = sorted({(int(a), int(b)) for a, b in g.index} & set(tot_indexed.index))
        season_iter = [(pid, s) for (pid, s) in season_iter if keep_row(pid, s)]
        if player is not None:
            season_iter = [(pid, s) for (pid, s) in season_iter if pid == player]
        # Prune guard for the per-player dirs: a run that omits the artifact's
        # latest season cannot judge the {pid}.json pointers (see the players block).
        latest_ok = max(seasons) >= max(int(s) for s in grades["season"].unique())

    # ------------------------------------------------------------- /pitchers
    board = None
    print(f"[{time.time() - t0:.0f}s] pitchers", flush=True)  # per-family timing
    if "pitchers" in fams:
        board_rows = []
        for _, t in totals.iterrows():
            key = (t["id"], int(t["season"]))
            if key not in g.index or not keep_row(t["id"], int(t["season"])):
                continue
            gr = g.loc[key]
            ip = t["outs"] / 3
            c = fip_c.get(int(t["season"]), 3.1)
            fip = (13 * t["hr"] + 3 * (t["bb"] + t["hbp"]) - 2 * t["k"]) / ip + c if ip > 0 else None
            row = {
                "id": str(t["id"]), "name": gr["name"], "team": tot_team.get(key), "teams": team_stints_p.get(key),
                "teamSplits": team_split_p.get(key),
                "throws": t["throws"], "season": int(t["season"]), "age": season_age(t["id"], t["season"]),
                "ip": f(ip, 1), "era": f(era_of(t["id"], t["season"], level, t["runs"], ip), 2),
                "fip": f(fip, 2), "whip": f((t["h"] + t["bb"]) / ip, 2) if ip > 0 else None,
                "battersFaced": int(t["pa"]), "pitches": int(t["n_pitches"]),
                "hits": int(t["h"]), "walks": int(t["bb"]),
                "kPct": f(100 * t["k"] / t["pa"], 1), "bbPct": f(100 * t["bb"] / t["pa"], 1),
                "kBbPct": f(100 * (t["k"] - t["bb"]) / t["pa"], 1),
                "g": (gs_map.get(key) or (None, None))[0], "gs": (gs_map.get(key) or (None, None))[1],
                "role": role_of(*(gs_map.get(key) or (None, None))),
                "cswPct": f(100 * t["csw"] / t["n_pitches"], 1),
                "rvPer100": f(100 * t["rv"] / t["n_pitches"], 2) if t["n_pitches"] else None,
                "whiffPct": f(100 * t["whiff"] / t["swings"], 1) if t["swings"] else None,
                "velo": f(t["velo"], 1), "ivb": f(t["ivb"], 1), "gbPct": f(100 * t["gb"] / t["bip"], 1) if t["bip"] else None,
                "stuffPlus": f(gr["grade"], 1),
                "pitchingPlus": f(gr["pitching_plus"], 1),
                **{k: f(gr[c], 3 if c == "k_proj" else 1) for c, k in P7_FIELDS.items()},
                "confidence": gr["confidence"],
                "nPitches": int(gr["pitches_graded"]), "nStuffPitches": int(gr["pitches_graded"]),
            }
            discipline_fields(row, t, season=int(t["season"]), totals=totals)
            row.update(p_depth(level, tuple(seasons), con)[0].get((int(t["id"]), int(t["season"])), {}))
            row.update(proj_band_fields(row.get("kProj"), row.get("preventionPlus"), int(t["pa"])))
            board_rows.append(row)
        board = pd.DataFrame(board_rows)
        print(f"board rows: {len(board)}")
        counts["board_rows"] = int(len(board))

        # ------------------------------------------------------------ percentiles
        # One population per SEASON — a 2023 profile ranks against 2023 arms, not a
        # four-year soup — plus a pooled section for anything undated. Percentile
        # colors/ranks read the season section on every surface.
        SEASON_METRICS = ["velo", "ivb", "kPct", "bbPct", "kBbPct", "cswPct", "whiffPct",
                          "era", "fip", "gbPct", "rvPer100", "stuffPlus", "pitchingPlus",
                          "kPlus", "preventionPlus", "controlPlus", "kProj", "pitchingRunsPer100",
                          "zonePct", "chasePct", "zSwingPct", "zWhiffPct", "oWhiffPct", "zContactPct",
                          "oContactPct", "swStrPct", "calledStrikePct", "firstPitchStrikePct",
                          "putawayPct", "swingPct",
                          "xwobaAg", "xbaAg", "xslgAg", "xwobaconAg", "wobaAg", "evAg", "hardHitPctAg",
                          "barrelPctAg", "sweetSpotPctAg", "pullAirPctAg", "batSpeedAg", "squaredUpPctAg",
                          "blastPctAg", "rvPer100Fb", "rvPer100Br", "rvPer100Os", "rvProj", "xrvPer100", "rvLuck"]

        # per-pitch-type rows joined to their season's grades — the per_type population
        type_grades = bytype[(bytype["n"] >= SABR_FLOORS["type"])].copy()
        type_grades = type_grades[[keep_row(int(row.id), int(row.season)) for row in type_grades.itertuples()]]
        tg = type_grades.merge(
            grades[["mlbam", "season", "grade", "stuff_plus_abs", "pitching_plus"]]
            .rename(columns={"mlbam": "id"}),
            on=["id", "season"], how="inner")
        # the type's own grade where the artifact carries one (owner ship decision);
        # rows without it drop from the type-grade pools, not from ABStuff+/Pitch+
        tg["type_grade"] = [
            (type_grade.get((int(row.id), int(row.season), row.site), (None,))[0]) for row in tg.itertuples()]
        tg = tg[tg["type_grade"].notna()] if "type_grade" in tg else tg

        def season_population(season: int | None):
            """(board rows, per-type rows, graded rows) for one season, or pooled."""
            b = board if season is None else board[board["season"] == season]
            tgx = tg if season is None else tg[tg["season"] == season]
            gx = b[b["nPitches"] >= SABR_FLOORS["grade"]]
            return b, tgx, gx

        def build_sections(season: int | None):
            b, tgx, gx = season_population(season)
            pcts = {}
            for metric in SEASON_METRICS:
                p = pct5(b[metric]) if metric in b.columns else None  # MLB-only fields (xRV) are absent at AAA
                if p:
                    pcts[metric] = p
            per_type = {}
            for site, sub in tgx.groupby("site"):
                block = {}
                for metric, col in [("velo", "velo"), ("ivb", "ivb"), ("hb", "hb"), ("spin", "spin"),
                                    ("stuffPlus", "type_grade"),
                                    ("rv100", None),
                                    ("whiffPct", None), ("cswPct", None), ("zonePct", None)]:
                    if metric == "whiffPct":
                        vals = 100 * sub["whiff"] / sub["swings"].clip(lower=1)
                    elif metric == "cswPct":
                        vals = 100 * sub["csw"] / sub["n"].clip(lower=1)
                    elif metric == "zonePct":
                        vals = 100 * sub["n_zone"] / sub["n"]
                    elif metric == "rv100":
                        vals = 100 * sub["rv"] / sub["n"]
                    else:
                        vals = sub[col]
                    p = pct5(vals)
                    if p:
                        block[metric] = p
                per_type[site] = block
            dense = {"pitchers": {}, "per_type": {}}
            for metric in ["stuffPlus", "pitchingPlus", "kPlus", "preventionPlus", "controlPlus",
                           "kProj", "pitchingRunsPer100"]:
                q = dense_q(gx[metric])
                if q:
                    dense["pitchers"][metric] = {"q": q, "n": int(len(gx))}
            for site, sub in tgx.groupby("site"):
                block = {}
                for metric, col in [("stuffPlus", "type_grade"), ("pitchingPlus", "pitching_plus")]:
                    q = dense_q(sub[col])
                    if q is not None:
                        block[metric] = {"q": q, "n": int(len(sub))}
                q = dense_q(100 * sub["rv"] / sub["n"])
                if q is not None:
                    block["rv100"] = {"q": q, "n": int(len(sub))}
                if block:
                    dense["per_type"][site] = block
            return {"pitchers": pcts, "pitchers_per_type": per_type}, dense

        by_season, by_season_dense = {}, {}
        for s in seasons:
            by_season[str(s)], by_season_dense[str(s)] = build_sections(s)
        pooled_pcts, pooled_dense = build_sections(None)

        # shrunk populations (P4 completion): pct5 of each *Shrunk twin across
        # the season's board — the profile panels rank the twin against its own
        # kind while printing the raw rate
        shrunk_by_season = {}
        for s in seasons:
            sub = board[board["season"] == s]
            pcts = {}
            for key in DISC_SHRINK:
                col = f"{key}Shrunk"
                p5 = pct5(sub[col]) if col in sub.columns else None
                if p5:
                    pcts[key] = p5
            shrunk_by_season[str(s)] = pcts
        pitcher_shrunk_out = {"shrunk_by_season": shrunk_by_season}

        stuff_pcts = {
            "season": season_csv,
            "population": {"rule": f"per-season dense grade breakpoints ({season_csv}); {SABR_FLOORS['grade']}+ graded pitches",
                           "n": int(len(board[board["nPitches"] >= SABR_FLOORS["grade"]]))},
            **pooled_dense,
            "by_season": by_season_dense,
            "pooled": pooled_dense,
        }

    # ------------------------------------------------------ arsenal board rows
    arsenal_rows = {}
    print(f"[{time.time() - t0:.0f}s] arsenal", flush=True)  # per-family timing
    if "arsenal" in fams:
        card_pool = {}
        for _, t in bytype.iterrows():
            site = t["site"]
            if site not in SITE_TYPES or t["n"] < SABR_FLOORS["row"]:
                continue
            key = (t["id"], int(t["season"]))
            if key not in g.index or not keep_row(t["id"], int(t["season"])):
                continue
            gr = g.loc[key]
            sg, sn = type_grade.get((*key, t["site"]), class_grade.get((*key, class_key.get(t["pitch_type"])), (None, 0)))
            pg, pn = class_grade.get((*key, "P:" + class_key.get(t["pitch_type"])), (None, 0))
            usage = 100 * t["n"] / tot_n[key]
            row = {
                "id": str(t["id"]), "name": gr["name"], "team": tot_team.get(key),
                "season": int(t["season"]),
                "n_pitches": int(t["n"]), "usage": f(usage, 1),
                "velo": f(t["velo"], 1), "ivb": f(t["ivb"], 1), "hb": f(t["hb"], 1),
                "spin": r(t["spin"]), "vaa": f(t["vaa"], 1), "ext": f(t["ext"], 1),
                "zonePct": f(100 * t["n_zone"] / t["n"], 1),
                "whiffPct": f(100 * t["whiff"] / t["swings"], 1) if t["swings"] else None,
                "nSwings": int(t["swings"]), "nWhiffs": int(t["whiff"]),
                "cswPct": f(100 * t["csw"] / t["n"], 1),
                "rv100": f(100 * t["rv"] / t["n"], 2),
                "stuffPlus": f(sg, 1) if sg is not None else None,
                "nStuffPitches": int(sn), "stuffGradeFrom": None,
                "pitchingPlus": f(pg, 1) if pg is not None else None,
                "confidence": gr["confidence"],
            }
            arsenal_rows.setdefault(site, []).append(row)
            if t["n"] >= SABR_FLOORS["card"] and sg is not None:
                card_pool.setdefault(site, []).append({**row, "_grade": sg})

        # stuffGradeFrom: the host type of the class = the highest-n type in that class for that pitcher
        host = {}
        for (pid, season), sub in bytype.groupby(["id", "season"]):
            for cls in ("FB", "BB", "CH"):
                members = sub[sub["pitch_type"].map(class_key) == cls]
                members = members[members["n"] >= SABR_FLOORS["row"]]
                if len(members) >= 2:
                    ranked = members.sort_values("n", ascending=False)
                    host_type = ranked.iloc[0]["site"]
                    for site_code in ranked.iloc[1:]["site"]:
                        host[(int(pid), int(season), site_code)] = host_type
        for site, rows in arsenal_rows.items():
            for row in rows:
                has_type = (int(row["id"]), row["season"], site) in type_grade
                h = host.get((int(row["id"]), row["season"], site))
                if h is not None and row["stuffPlus"] is not None and not has_type:
                    row["stuffGradeFrom"] = h
                if site == "SL" and (int(row["id"]), row["season"], "SL") in type_gyro:
                    row["gyro"] = True

        cards_season = max(seasons)
        arsenal_cards = []
        for site in SITE_TYPES:
            rows = [row for row in card_pool.get(site, []) if row["season"] == cards_season]
            if not rows:
                continue
            top = sorted(rows, key=lambda x: (-x["_grade"], int(x["id"])))[:10]
            arsenal_cards.append({
                "pitchType": site,
                "season": cards_season,
                "avgVelo": f(np.mean([x["velo"] for x in rows]), 1),
                "avgWhiff": f(np.mean([x["whiffPct"] for x in rows if x["whiffPct"] is not None]), 1),
                "avgIvb": f(np.mean([x["ivb"] for x in rows]), 1),
                "topPitchers": [{"id": x["id"], "name": x["name"], "team": x["team"],
                                 "primaryMetric": x["stuffPlus"],
                                 "gyro": site == "SL" and (int(x["id"]), int(x["season"]), "SL") in type_gyro}
                                for x in top],
            })
        counts["arsenal_rows"] = {site: len(rows) for site, rows in sorted(arsenal_rows.items())}

    # ---------------------------------------------- arsenal mix metrics (A2/PP11)
    # Description, not a grade: usage entropy (effTypes), centroid separation in
    # (velo mph, IVB in, HB in), usage-weighted within-type movement scatter and
    # velo range — the bake_arsenal.py formulas. The study's own gates: types
    # under 3% usage drop out, under 50 kept pitches -> no row; percentiles rank
    # against same-season pitchers with 100+ pitches (repeatSd: HIGHER = more
    # scatter). These components predicted nothing beyond Pitching+ and the
    # prior season, so nothing here is coloured.
    MIX_KEYS = ["nTypes", "effTypes", "separation", "repeatSd", "veloSpread"]
    mix_by_key = {}
    mix_ref = {}
    if ("players" in fams or "arsenal" in fams) and bytype is not None:
        from itertools import combinations
        names_by_id = dict(zip(grades["mlbam"].astype(int), grades["name"]))
        bt_kept = bytype[[keep_row(int(row.id), int(row.season)) for row in bytype.itertuples()]]
        for (pid, season), sub0 in bt_kept.groupby(["id", "season"]):
            # EP (eephus) has no site code and folds away; an all-EP season has no mix.
            sub = fold_site_rows(sub0[(sub0["n"] > 0) & sub0["site"].notna()])
            if sub.empty:
                continue
            use_all = dict(zip(sub["site"], (sub["n"] / sub["n"].sum()).values))
            sub = sub[sub["site"].isin([t for t, s0 in use_all.items() if s0 >= 0.03])]
            n = int(sub["n"].sum())
            if n < 50 or sub.empty:
                continue
            u = pd.Series(sub["n"].values / sub["n"].sum(), index=sub["site"].values)
            cent = sub.set_index("site")[["velo", "ivb", "hb"]]
            sd_ok = sub[(sub["n"] > 2) & sub["ivb_sd"].notna() & sub["hb_sd"].notna()]
            pairs = [float(np.linalg.norm(cent.loc[a].values - cent.loc[b].values))
                     for a, b in combinations(cent.index, 2)]
            usd = u.reindex(sd_ok["site"].values)
            mix_by_key[(int(pid), int(season))] = {
                "name": names_by_id.get(int(pid)),
                "team": tot_team.get((int(pid), int(season))),
                "n": n,
                "nTypes": int(len(u)),
                "effTypes": f(math.exp(-(u * np.log(u)).sum()), 2),
                "separation": f(np.mean(pairs), 2) if pairs else None,
                "repeatSd": f(float((usd.values * np.sqrt(sd_ok["ivb_sd"].values ** 2 + sd_ok["hb_sd"].values ** 2)).sum() / usd.sum()), 2) if len(sd_ok) else None,
                "veloSpread": f(float(cent["velo"].max() - cent["velo"].min()), 2),
                "types": [t for t, _ in sorted(u.items(), key=lambda kv: -kv[1])],
            }
        for s in seasons:
            ref = {k: v for k, v in mix_by_key.items() if k[1] == s and v["n"] >= 100}
            mix_ref[s] = ref
            for k, v in mix_by_key.items():
                if k[1] != s:
                    continue
                v["pct"] = {}
                for mk in MIX_KEYS:
                    if v[mk] is None or len(ref) < 10:
                        v["pct"][mk] = None
                    else:
                        vals = [x[mk] for x in ref.values() if x[mk] is not None]
                        v["pct"][mk] = int(round(100 * sum(1 for x in vals if x < v[mk]) / len(vals))) if vals else None

    def site_case_sql(col: str = "pitch_type") -> str:
        """Statcast type -> site code, as a SQL CASE (league aggregates key on site codes)."""
        whens = " ".join(f"WHEN '{k}' THEN '{v}'" for k, v in SC_TO_SITE.items() if k != v)
        return f"CASE {col} {whens} ELSE {col} END"

    # ----------------------------------------------------------- slot board
    slot_pitchers = {}
    print(f"[{time.time() - t0:.0f}s] slot", flush=True)  # per-family timing
    if "slot" in fams:
        latest = grades.sort_values("season").groupby("mlbam").tail(1).set_index("mlbam")
        for pid, sub in bytype.groupby("id"):
            season = int(latest.loc[pid, "season"]) if pid in latest.index else None
            if season is None or not keep_row(int(pid), season):
                continue
            sub = sub[(sub["season"] == season) & sub["arm_angle"].notna()]
            if sub.empty:
                continue
            fb = sub[sub["pitch_type"].isin(["FF", "SI", "FC"])].sort_values("n", ascending=False)
            if fb.empty:
                continue
            fbrow = fb.iloc[0]
            sub_all = bytype[(bytype["id"] == pid) & (bytype["season"] == season)]
            slot_pitchers[str(pid)] = {
                "th": tot_indexed.loc[(pid, season), "throws"],
                "ws": [int(sub_all["whiff"].sum()), int(sub_all["swings"].sum()), int(sub_all["n"].sum())],
                "arm": f(fbrow["arm_angle"], 1),
                "armType": "",  # filled by the UI's SLOT_BANDS
                "relH": f(fbrow["rel_h"], 2), "relS": f(fbrow["rel_s"], 2), "ext": f(fbrow["ext"], 2),
                "fb": fbrow["site"], "fbVelo": f(fbrow["velo"], 1),
                "fbIvb": f(fbrow["ivb"], 1), "fbHb": f(fbrow["hb"], 1),
            }

    # -------------------------------------------------------- player files
    print(f"[{time.time() - t0:.0f}s] players", flush=True)  # per-family timing
    if "players" in fams:
        # movement cloud: a deterministic 1-in-8 pitch subsample per player-season
        # (hash of game_pk+pitch_number, so re-bakes pick the same pitches), for the
        # profile's shaded per-pitch backdrop under the type means.
        cloud = con.sql(f"""
            SELECT pitcher AS id, season, pitch_type,
                   ROUND(pfx_x * 12, 1) AS hb, ROUND(pfx_z * 12, 1) AS ivb
            FROM pitches_all
            WHERE game_type = 'R' AND season IN ({season_list})
              AND hash(CAST(game_pk AS VARCHAR) || '-' || CAST(pitch_number AS VARCHAR)) % 8 = 0
              {GATES}
            ORDER BY id, season, pitch_type, hb, ivb
        """).df()
        cloud["site"] = cloud["pitch_type"].map(SC_TO_SITE)
        cloud_by_player = {}
        for cr in cloud.itertuples():
            if keep_row(int(cr.id), int(cr.season)):
                cloud_by_player.setdefault((int(cr.id), int(cr.season)), []).append((cr.site, float(cr.hb), float(cr.ivb)))
        print(f"movement cloud points: {len(cloud)} across {len(cloud_by_player)} player-seasons")

        # release means/SD for every pitcher-season in ONE grouped pass (was a
        # per-player query inside the loop — same gates, one scan instead of ~3k).
        rel_stats = con.sql(f"""
            SELECT pitcher, season,
                   AVG(release_pos_z) AS rel_h, AVG(release_pos_x) AS rel_s,
                   STDDEV(release_pos_z) AS rel_h_sd, STDDEV(release_pos_x) AS rel_s_sd,
                   AVG(release_extension) AS ext
            FROM pitches_all
            WHERE game_type = 'R' AND season IN ({season_list})
              AND pitch_type IN ('FF','SI','FC','SL','CU','KC','SW','SV','ST','CH','FS','FO','EP')
              AND release_speed BETWEEN 55 AND 105 AND release_extension > 3
            GROUP BY 1, 2
        """).df().set_index(["pitcher", "season"])

        bytype_g = bytype.set_index(["id", "season"])
        cells_g = cells.set_index(["id", "season"])

        # D-10 shape twins: the nearest league pitch by shape within the same
        # type, excluding the pitcher himself — a reference point a coach can
        # picture ("his slider is Zebby Matthews' slider"), not a claim. The
        # pool is every qualified player-season-type mean; distance is
        # standardized per dimension so velo can't swamp break.
        import numpy as _np
        _pool_rows = []
        for (_pid2, _s2), _r2 in bytype_g.iterrows():
            if _r2["n"] >= SABR_FLOORS["row"] and not (pd.isna(_r2["velo"]) or pd.isna(_r2["ivb"]) or pd.isna(_r2["hb"])):
                _pool_rows.append((int(_pid2), int(_s2), _r2["site"],
                                   float(_r2["velo"]), float(_r2["ivb"]), float(_r2["hb"])))
        _names_by_id = {int(gr2.mlbam): gr2.name for gr2 in grades[["mlbam", "name"]].drop_duplicates("mlbam").itertuples() if gr2.name}
        _pool_by_site: dict = {}
        for _i, _p in enumerate(_pool_rows):
            _pool_by_site.setdefault(_p[2], [[], [], []])
            _pool_by_site[_p[2]][0].append(_i)
            _pool_by_site[_p[2]][1].append([_p[3], _p[4], _p[5]])
            _pool_by_site[_p[2]][2].append(_p[0])
        # (indices, shape vectors, pitcher ids) — pids as an array so the
        # self-exclusion mask is one vectorized compare per query
        _pool_arr = {site: (_np.array(ix), _np.array(vs), _np.array(pids))
                     for site, (ix, vs, pids) in _pool_by_site.items()}
        _pool_sd = {site: _pool_arr[site][1].std(axis=0) for site in _pool_arr}
        _pool_sd = {site: _np.where(sd == 0, 1.0, sd) for site, sd in _pool_sd.items()}

        def twin_of(pid: int, site: str, velo, ivb, hb):
            if not _pool_arr or velo is None or pd.isna(velo) or pd.isna(ivb) or pd.isna(hb):
                return None
            entry = _pool_arr.get(site)
            if entry is None or len(entry[0]) < 5:
                return None
            ix, vs, pids = entry
            mask = pids != pid
            if not mask.any():
                return None
            d = _np.sqrt((((vs[mask] - [velo, ivb, hb]) / _pool_sd[site]) ** 2).sum(axis=1))
            j = int(d.argmin())
            src = _pool_rows[ix[mask][j]]
            return {"id": str(src[0]), "n": _names_by_id.get(src[0]), "s": src[1],
                    "d": round(float(d[j]), 2),
                    "dv": [round(velo - src[3], 1), round(ivb - src[4], 1), round(hb - src[5], 1)]}
        # D-07 (§73, descriptive): Whiff+ per type vs each batter hand, shrunk + CI, and usage by hand
        platoon = {}
        plf = ROOT / "pipeline" / "results" / "platoon_splits.csv"
        if level == "mlb" and plf.exists():
            for pl in pd.read_csv(plf).itertuples():
                h = "LHH" if pl.stand == "L" else "RHH"
                platoon.setdefault((int(pl.pitcher), int(pl.season), pl.site), {}).update({
                    f"stuffVs{h}": f(pl.grade, 1), f"stuffVs{h}Shrunk": f(pl.grade_shrunk, 1),
                    f"stuffVs{h}Lo": f(pl.lo, 1), f"stuffVs{h}Hi": f(pl.hi, 1),
                    f"usageVs{h}": f(pl.usage, 1), f"nVs{h}": int(pl.n)})
        player_index = {}
        written_pairs: set[tuple[int, int]] = set()
        written_latest: set[int] = set()
        n_players = 0
        latest_season = {pid: max(s for (p2, s) in season_iter if p2 == pid) for pid, _ in season_iter}
        for pid, season in season_iter:
            gr_row = g.loc[(pid, season)]
            key = (pid, season)
            if key not in tot_indexed.index:
                continue
            t = tot_indexed.loc[key]
            ip = t["outs"] / 3
            c = fip_c.get(season, 3.1)
            sub = bytype_g.loc[[key]] if key in bytype_g.index else bytype_g.iloc[0:0]
            sub = sub[sub["n"] >= SABR_FLOORS["row"]].copy()
            pitch_rows = []
            # class host map for this pitcher
            p_host = {}
            for cls in ("FB", "BB", "CH"):
                members = sub[sub["pitch_type"].map(class_key) == cls]
                if len(members) >= 2:
                    ranked = members.sort_values("n", ascending=False)
                    for site_code in ranked.iloc[1:]["site"]:
                        p_host[site_code] = ranked.iloc[0]["site"]
            for _, b in sub.sort_values(["n", "pitch_type"], ascending=[False, True]).iterrows():
                sg, sn = type_grade.get((pid, season, b["site"]), class_grade.get((pid, season, class_key.get(b["pitch_type"])), (None, 0)))
                pg, _ = class_grade.get((pid, season, "P:" + class_key.get(b["pitch_type"])), (None, 0))
                site = b["site"]
                pitch_rows.append({
                    "pitchType": site, "n_pitches": int(b["n"]),
                    "usage": f(100 * b["n"] / t["n_pitches"], 1),
                    "velo": f(b["velo"], 1), "ivb": f(b["ivb"], 1), "hb": f(b["hb"], 1),
                    "spin": r(b["spin"]), "strikePct": f(100 * b["strikes"] / b["n"], 1),
                    "vaa": f(b["vaa"], 1), "ext": f(b["ext"], 1),
                    "relHeight": f(b["rel_h"], 2), "relSide": f(b["rel_s"], 2),
                    "highLocPct": f(100 * b["n_high"] / b["n"], 1), "lowLocPct": f(100 * b["n_low"] / b["n"], 1),
                    "whiffPct": f(100 * b["whiff"] / b["swings"], 1) if b["swings"] else None,
                    "cswPct": f(100 * b["csw"] / b["n"], 1),
                    "zonePct": f(100 * b["n_zone"] / b["n"], 1),
                    "chasePct": f(100 * b["n_ooz_swing"] / b["n_ooz"], 1) if b["n_ooz"] else None,
                    "zSwingPct": f(100 * b["n_zone_swing"] / b["n_zone"], 1) if b["n_zone"] else None,
                    "zWhiffPct": f(100 * b["n_zone_whiff"] / b["n_zone_swing"], 1) if b["n_zone_swing"] else None,
                    "oWhiffPct": f(100 * b["n_ooz_whiff"] / b["n_ooz_swing"], 1) if b["n_ooz_swing"] else None,
                    "zContactPct": f(100 * b["n_zone_contact"] / b["n_zone_swing"], 1) if b["n_zone_swing"] else None,
                    "nSwings": int(b["swings"]), "nZonePitches": int(b["n_zone"]), "nOozPitches": int(b["n_ooz"]),
                    "nZoneSwings": int(b["n_zone_swing"]), "nFirstPitch": int(b["n_first_pitch"]),
                    "nTwoStrike": int(b["n_two_strike"]),
                    "rv100": f(100 * b["rv"] / b["n"], 2), "nPa": int(b["n_pa"]),
                    "calledStrikePct": f(100 * (b["csw"] - b["whiff"]) / b["taken"], 1),
                    "firstPitchStrikePct": f(100 * b["n_first_pitch_strike"] / b["n_first_pitch"], 1) if b["n_first_pitch"] else None,
                    "putawayPct": f(100 * b["n_two_strike_csw"] / b["n_two_strike"], 1) if b["n_two_strike"] else None,
                    "stuffPlus": f(sg, 1) if sg is not None else None,
                    "nStuffPitches": int(sn),
                    "stuffGradeFrom": None if (pid, season, site) in type_grade else p_host.get(site),
                    "gyro": site == "SL" and (pid, season, "SL") in type_gyro or None,
                    "twin": twin_of(pid, site, b["velo"], b["ivb"], b["hb"]),
                    "pitchingPlus": f(pg, 1) if pg is not None else None,
                    # no per-type ABStuff+: train_mlb grades it per pitcher only (abs_grade)
                    **platoon.get((pid, season, site), {}),
                })
            bb_rows = []
            for _, b in sub[sub["n_bip"] > 0].iterrows():
                bb_rows.append({
                    "pitchType": b["site"], "n_bip": int(b["n_bip"]),
                    "gbPct": f(100 * b["gb"] / b["n_bip"], 1), "fbPct": f(100 * b["fb"] / b["n_bip"], 1),
                    "ldPct": f(100 * b["ld"] / b["n_bip"], 1), "puPct": f(100 * b["pu"] / b["n_bip"], 1),
                    "avgEv": f(b["ev"], 1), "avgLa": f(b["la"], 1),
                    "hardHitPct": f(100 * b["n_hard"] / b["n_bip"], 1),
                })
            mv = [{"pitchType": b["site"], "ivb": f(b["ivb"], 1), "hb": f(b["hb"], 1)}
                  for _, b in sub.sort_values(["n", "pitch_type"], ascending=[False, True]).iterrows()]
            psub = cells_g.loc[[key]] if key in cells_g.index else cells_g.iloc[0:0]
            vaa_zone, vaa_pitch = [], []
            for _, cell in psub.iterrows():
                site = cell["site"]
                entry = {"pitchType": site, "zone_x": cell["zx"], "zone_z": cell["zz"],
                         "avg_vaa": f(cell["avg_vaa"], 2), "n": int(cell["n"])}
                vaa_zone.append(entry)
                vaa_pitch.append(entry)
            if season == latest_season[pid]:
                player_index[str(pid)] = {"n": gr_row["name"], "t": "P", "tm": team_map.get(key),
                                          "bf": int(t["pa"]), "season": season}
            doc = {
                "id": str(pid), "name": gr_row["name"], "team": team_map.get(key), "teams": team_stints_p.get(key), "teamSplits": team_split_p.get(key),
                "position": "P",
                "throws": t["throws"], "season": season, "age": season_age(pid, season),
                "ip": f(ip, 1), "era": f(era_of(pid, season, level, t["runs"], ip), 2),
                "fip": f((13 * t["hr"] + 3 * (t["bb"] + t["hbp"]) - 2 * t["k"]) / ip + c, 2) if ip > 0 else None,
                "whip": f((t["h"] + t["bb"]) / ip, 2) if ip > 0 else None,
                "battersFaced": int(t["pa"]), "pitches": int(t["n_pitches"]),
                "hits": int(t["h"]), "walks": int(t["bb"]),
                "kPct": f(100 * t["k"] / t["pa"], 1), "bbPct": f(100 * t["bb"] / t["pa"], 1),
                "kBbPct": f(100 * (t["k"] - t["bb"]) / t["pa"], 1),
                "g": (gs_map.get(key) or (None, None))[0], "gs": (gs_map.get(key) or (None, None))[1],
                "role": role_of(*(gs_map.get(key) or (None, None))),
                "cswPct": f(100 * t["csw"] / t["n_pitches"], 1),
                "rvPer100": f(100 * t["rv"] / t["n_pitches"], 2) if t["n_pitches"] else None,
                "whiffPct": f(100 * t["whiff"] / t["swings"], 1) if t["swings"] else None,
                "gbPct": f(100 * t["gb"] / t["bip"], 1) if t["bip"] else None,
                "velo": f(t["velo"], 1), "ivb": f(t["ivb"], 1),
                "stuffPlus": f(gr_row["grade"], 1),
                "pitchingPlus": f(gr_row["pitching_plus"], 1),
                **{k: f(gr_row[c], 3 if c == "k_proj" else 1) for c, k in P7_FIELDS.items()},
                "confidence": gr_row["confidence"],
                "pitches": pitch_rows, "battedBall": bb_rows, "movementProfile": mv,
                "movementCloud": [
                    {"t": c0, "x": c1, "y": c2}
                    for (c0, c1, c2) in cloud_by_player.get((pid, season), [])
                ],
                "vaaByZone": vaa_zone or None, "vaaByPitch": vaa_pitch,
                "release": [],  # filled below from the pitch-level release stats
                "mix": mix_by_key.get((pid, season)),
                "percentiles": {},
            }
            discipline_fields(doc, t, season=season, totals=totals)
            p_dep, p_tr = p_depth(level, tuple(seasons), con)
            doc.update(p_dep.get((pid, season), {}))
            doc["tunnelPairs"] = tunnel_pairs().get((pid, season)) if level == "mlb" else None
            doc["trend"] = p_tr.get((pid, season))
            doc.update(proj_band_fields(doc.get("kProj"), doc.get("preventionPlus"), int(t["pa"])))
            rel_row = rel_stats.loc[(pid, season)] if (pid, season) in rel_stats.index else None
            if rel_row is not None:
                doc["release"] = [{
                    "relHeight": f(rel_row["rel_h"], 2), "relSide": f(rel_row["rel_s"], 2),
                    "extension": f(rel_row["ext"], 2),
                    "relHeightSD": f(rel_row["rel_h_sd"], 3), "relSideSD": f(rel_row["rel_s_sd"], 3),
                }]
            if season == latest_season[pid]:
                jwrite(out / "players" / f"{pid}.json", doc, sort_keys=True)
                written_latest.add(pid)
            jwrite(out / "players" / f"{pid}-{season}.json", doc, sort_keys=True)
            written_pairs.add((pid, season))
            n_players += 1
            if n_players % 200 == 0:
                print(f"  players: {n_players}")
        if player is None:
            jwrite(out / "player_index.json", player_index, sort_keys=True)
        # Prune stale per-player files: the exclusion rules evolve, and a file the
        # board would no longer show must not keep serving by direct URL. Exact
        # for full-season runs; a run that omits the artifact's latest season
        # leaves the {pid}.json pointers alone (it cannot judge them).
        pruned = 0
        if player is None:
            for p in (out / "players").glob("*.json"):
                stem = p.stem
                if "-" in stem:
                    pid_s, s = stem.rsplit("-", 1)
                    if s.isdigit() and int(s) in seasons and (int(pid_s), int(s)) not in written_pairs:
                        p.unlink()
                        pruned += 1
                elif latest_ok and int(stem) not in written_latest:
                    p.unlink()
                    pruned += 1
        counts["player_files"] = n_players
        counts["player_files_pruned"] = pruned
        print(f"players: {n_players} season files; pruned {pruned} stale")

        # --------------------------------------------- per-pitch RV card (PP9)
        # The measured half only: RV/100 per pitch type with an 80% normal range
        # built from the league's per-pitch run-value spread at that type. These
        # are results, not grades — the card renders them plain, never coloured,
        # and the xRV/loc/wOBA columns of the college card are NEEDS-MODEL and
        # stripped. Latest season only (slot/{id}.json precedent).
        lg_rv = con.sql(f"""
            SELECT {site_case_sql()} AS site, COUNT(*) AS n,
                   AVG(delta_pitcher_run_exp) * 100 AS mu100,
                   STDDEV(delta_pitcher_run_exp) AS sd
            FROM pitches_all
            WHERE game_type = 'R' AND season = {max(seasons)}
              AND pitch_type IN ('FF','SI','FC','SL','CU','KC','SW','SV','ST','CH','FS','FO','EP')
              AND release_speed BETWEEN 55 AND 105 AND release_extension > 3
              AND pfx_z IS NOT NULL AND pfx_x IS NOT NULL AND release_spin_rate IS NOT NULL
              AND p_throws IN ('L','R') AND stand IN ('L','R')
            GROUP BY 1
        """).df().set_index("site")
        RV_HIDE = 50  # matches the type-grade floor: under this the cell hides
        rv_written: set[int] = set()
        xrv_type: dict = {}  # §71 (D-03): xRV/100 per site code, descriptive, MLB only
        xtf = ROOT / "pipeline" / "results" / "xrv_v2_pitch_types.csv"
        if level == "mlb" and xtf.exists():
            xt = pd.read_csv(xtf).assign(site=lambda d: d["pitch_type"].map(lambda t: SC_TO_SITE.get(t, t)))
            xt["w"] = xt["xrv100"] * xt["n"]
            for (m, s_, site), g_ in xt.groupby(["mlbam", "season", "site"]):
                xrv_type[(int(m), int(s_), site)] = float(g_["w"].sum() / g_["n"].sum())
        bt_latest = bytype[(bytype["season"] == max(seasons))]
        for (pid, season), sub0 in bt_latest.groupby(["id", "season"]):
            if not keep_row(int(pid), int(season)) or season != latest_season.get(pid):
                continue
            sub = fold_site_rows(sub0[(sub0["n"] > 0) & sub0["site"].notna()])
            rows_rv = []
            for b in sub.itertuples():
                if b.n < RV_HIDE or b.site not in lg_rv.index:
                    continue
                lg_row = lg_rv.loc[b.site]
                half = 1.282 * float(lg_row["sd"]) * 10.0 / math.sqrt(b.n)  # SE of RV/100
                rv100 = 100.0 * float(b.rv) / b.n
                rows_rv.append({
                    "type": b.site, "n": int(b.n), "nPa": int(b.n_pa),
                    "rv100": f(rv100, 2), "lo": f(rv100 - half, 2), "hi": f(rv100 + half, 2),
                    "xrv100": f(xrv_type.get((int(pid), int(season), b.site)), 2),
                })
            if not rows_rv:
                continue
            jwrite(out / "pitch_rv" / f"{pid}.json", {
                "v": 2, "season": season,
                "floors": {"rv": {"hide": RV_HIDE}},
                "league": {site: {"mu": f(row["mu100"], 2), "sdPitch": f(row["sd"], 3)}
                           for site, row in lg_rv.iterrows()},
                "rows": rows_rv,
            }, sort_keys=True)
            rv_written.add(pid)
        counts["pitch_rv_files"] = len(rv_written)
        print(f"pitch_rv files: {len(rv_written)}")
        if player is None and latest_ok:
            pruned = 0
            for p in (out / "pitch_rv").glob("*.json"):
                if int(p.stem) not in rv_written:
                    p.unlink()
                    pruned += 1
            print(f"pruned stale pitch_rv files: {pruned}")

        # --------------------------------------------- location mix (PP20)
        # League price per (zone, family) cell from EVERY gated located pitch;
        # a pitcher's mix = his cell shares priced at those cells, centred on the
        # league mean. The decomposition is arithmetic: zone prices where he
        # throws, the family detail adds shapeMix, and the two sum to mix.
        # Gates are the study's own (200+ located pitches, 90% in priced cells,
        # 500+ pitches behind a league cell). Year-to-year reliability on MLB is
        # NOT yet measured — the panel ranks descriptively and says so.
        ZONES = ["heart", "shadow", "chase", "waste"]
        FAMILIES6 = ["FB", "SI", "CT", "SL", "CB", "CH"]
        SITE_TO_FAM = {"FF": "FB", "SI": "SI", "CT": "CT", "SL": "SL", "SW": "SL",
                       "CB": "CB", "CH": "CH", "FS": "CH"}
        ZONE_SQL = """CASE WHEN abs(plate_x) <= 0.558 AND plate_z BETWEEN 1.833 AND 3.500 THEN 'heart'
                     WHEN abs(plate_x) <= 1.108 AND plate_z BETWEEN 1.166 AND 4.000 THEN 'shadow'
                     WHEN abs(plate_x) <= 1.666 AND plate_z BETWEEN 0.500 AND 4.500 THEN 'chase'
                     ELSE 'waste' END"""
        zone_counts = {}
        for s in seasons:
            zdf = con.sql(f"""
                SELECT pitcher, {ZONE_SQL} AS zone,
                       {site_case_sql()} AS fam, delta_pitcher_run_exp AS rv
                FROM pitches_all
                WHERE game_type = 'R' AND season = {s}
                  AND pitch_type IN ('FF','SI','FC','SL','CU','KC','SW','SV','ST','CH','FS','FO','EP')
                  AND release_speed BETWEEN 55 AND 105 AND release_extension > 3
                  AND pfx_z IS NOT NULL AND pfx_x IS NOT NULL AND release_spin_rate IS NOT NULL
                  AND p_throws IN ('L','R') AND stand IN ('L','R')
                  AND plate_x IS NOT NULL AND plate_z IS NOT NULL AND sz_top > sz_bot
                  AND balls BETWEEN 0 AND 3 AND strikes BETWEEN 0 AND 2
            """).df()
            zdf["fam"] = zdf["fam"].map(SITE_TO_FAM)
            pool = zdf.groupby(["zone", "fam"])["rv"].agg(["mean", "count"])
            league = {f"{z}|{fm}": float(row["mean"]) for (z, fm), row in pool.iterrows()
                      if row["count"] >= 500 and fm in FAMILIES6}
            zpool = zdf.groupby("zone")["rv"].mean()
            league_zone = {z: float(v) for z, v in zpool.items()}
            grand = float(zdf["rv"].mean())
            # league zone shares WITHIN each pitch family (priced cells), so a pitcher's
            # location is judged against the same pitch, not against the whole league mix
            pcnt = {(z, fm): int(row["count"]) for (z, fm), row in pool.iterrows() if f"{z}|{fm}" in league}
            fam_tot = {fm: sum(v for (z, f2), v in pcnt.items() if f2 == fm) for fm in FAMILIES6}
            lg_share = {(z, fm): v / fam_tot[fm] for (z, fm), v in pcnt.items()}
            lg_fam = {fm: v / sum(fam_tot.values()) for fm, v in fam_tot.items()}
            # priced-pool mean minus the grand mean (unpriced cells): the identity's constant
            off = sum(v * (league[f"{z}|{fm}"] - grand) for (z, fm), v in pcnt.items()) / sum(pcnt.values())
            cells_z = zdf.groupby(["pitcher", "zone", "fam"]).size()
            pitchers_z = {}
            for pid, sub in cells_z.groupby(level=0):
                n = int(sub.sum())
                if n < 200 or not keep_row(int(pid), s):
                    continue
                priced = {(z, fm): int(v) for (p2, z, fm), v in sub.items() if f"{z}|{fm}" in league}
                denom = sum(priced.values())
                if denom / n < 0.90:
                    continue
                exp = sum(v * league[f"{z}|{fm}"] for (z, fm), v in priced.items()) / denom
                exp_zone = sum(v * league_zone[z] for (z, fm), v in priced.items()) / denom
                all_counts = {(z, fm): int(v) for (p2, z, fm), v in sub.items()}
                zones_n = {z: sum(v for (z2, _fm), v in all_counts.items() if z2 == z) for z in ZONES}
                mix = 100 * (exp - grand)
                zone_mix_v = 100 * (exp_zone - grand)
                # runs this season by pitch x zone: his share of that pitch in the zone minus the
                # league's share for the same pitch, times the zone's price; the rest is pitch mix
                by_pitch, loc_runs, mix_term = [], 0.0, 0.0
                for fm in FAMILIES6:
                    nf = sum(v for (z, f2), v in priced.items() if f2 == fm)
                    gap = {z: lg_share.get((z, fm), 0.0) for z in ZONES}
                    price = {z: league[f"{z}|{fm}"] - grand if f"{z}|{fm}" in league else 0.0 for z in ZONES}
                    mix_term += (nf - denom * lg_fam.get(fm, 0.0)) * sum(gap[z] * price[z] for z in ZONES)
                    if not nf:
                        continue
                    dz = {z: (priced.get((z, fm), 0) - nf * gap[z]) * price[z] for z in ZONES}
                    loc_runs += sum(dz.values())
                    by_pitch.append({"fam": fm, "n": nf, "runs": f(sum(dz.values()), 2),
                                     "zones": [[f(100 * priced.get((z, fm), 0) / nf, 1), f(100 * gap[z], 1), f(dz[z], 2)]
                                               for z in ZONES]})
                by_pitch.sort(key=lambda r: -r["n"])
                total_runs = denom * (exp - grand)
                assert abs(total_runs - loc_runs - mix_term - denom * off) < 0.01, (pid, total_runs, loc_runs, mix_term)
                pitchers_z[str(int(pid))] = {
                    "runs": f(total_runs, 2), "locRuns": f(loc_runs, 2), "mixRuns": f(total_runs - loc_runs, 2),
                    "byPitch": by_pitch,
                    "mix": f(mix, 3), "zoneMix": f(zone_mix_v, 3), "shapeMix": f(mix - zone_mix_v, 3),
                    "n": n, "coverage": f(denom / n, 4),
                    "zoneShare": {z: f(zones_n.get(z, 0) / n, 4) for z in ZONES},
                    "cells": [all_counts.get((z, fm), 0) for z in ZONES for fm in FAMILIES6],
                }
            order = sorted(pitchers_z, key=lambda p: pitchers_z[p]["mix"])
            for i, p2 in enumerate(order):
                pitchers_z[p2]["pct"] = round(100 * i / max(1, len(order) - 1), 1)
            orderz = sorted(pitchers_z, key=lambda p: pitchers_z[p]["zoneMix"])
            for i, p2 in enumerate(orderz):
                pitchers_z[p2]["zonePct"] = round(100 * i / max(1, len(orderz) - 1), 1)
            orders = sorted(pitchers_z, key=lambda p: pitchers_z[p]["shapeMix"])
            for i, p2 in enumerate(orders):
                pitchers_z[p2]["shapePct"] = round(100 * i / max(1, len(orders) - 1), 1)
            # self-checks: the decomposition must add up and stay inside the
            # league price range, or the panel prints parts that do not make the whole
            lo9 = 100 * (min(league.values()) - grand) if league else None
            hi9 = 100 * (max(league.values()) - grand) if league else None
            for p2, v in pitchers_z.items():
                assert sum(v["cells"]) == v["n"], (p2, v["n"])
                assert abs(sum(x for x in v["zoneShare"].values()) - 1.0) < 1e-3, p2
                assert abs(v["zoneMix"] + v["shapeMix"] - v["mix"]) < 0.005, p2
                assert lo9 - 1e-6 <= v["mix"] <= hi9 + 1e-6, p2
            jwrite(out / "zone_mix" / f"{s}.json", {
                "meta": {
                    "season": s, "units": "RV/100, pitcher-positive, centred on the league mean",
                    "grandRv100": f(100 * grand, 4),
                    "gates": {"minPitches": 200, "minCoverage": 0.90, "minLeagueCell": 500},
                    "nPitchers": len(pitchers_z),
                    "reliability": {
                        "status": "pending",
                        "note": "the college location-mix r = +0.501 does not carry; MLB "
                                "year-to-year reliability is not yet measured — ranks are descriptive",
                    },
                },
                "cellOrder": [f"{z}|{fm}" for z in ZONES for fm in FAMILIES6],
                "zones": ZONES, "families": FAMILIES6,
                "league": {k: f(100 * v, 3) for k, v in league.items()},
                "leagueZone": {z: f(100 * v, 3) for z, v in league_zone.items()},
                "pitchers": pitchers_z,
            }, sort_keys=True)
            zone_counts[s] = len(pitchers_z)
            print(f"zone_mix {s}: {len(pitchers_z)} pitchers")
        counts["zone_mix"] = zone_counts

    # ---------------------------------- slot-conditional movement (A3 carry)
    # What pitchers from HIS slot throw for each type: pitch-weighted league
    # means per (type x arm band), arm-side-normalized HB (LHP mirrored), plus
    # the season-mean deltas of every kept pitcher in that cell for the ranks.
    # Descriptive — the college expected-shapes study found the distance adds
    # nothing beyond Stuff+ — so the UI ranks it, never verdict-colours it.
    print(f"[{time.time() - t0:.0f}s] slot", flush=True)  # per-family timing
    if "slot" in fams:
        BAND_SQL = """CASE WHEN arm_angle >= 60 THEN 'ott' WHEN arm_angle >= 45 THEN 'high34'
                   WHEN arm_angle >= 30 THEN '34' WHEN arm_angle >= 15 THEN 'low34'
                   WHEN arm_angle >= 0 THEN 'side' ELSE 'sub' END"""
        slot_league = con.sql(f"""
            SELECT pitch_type, {BAND_SQL} AS band,
                   AVG(pfx_z) * 12 AS exp_ivb,
                   AVG(pfx_x * 12 * CASE WHEN p_throws = 'L' THEN -1 ELSE 1 END) AS exp_hb_arm,
                   COUNT(DISTINCT pitcher) AS n_pitchers
            FROM pitches_all
            WHERE game_type = 'R' AND season IN ({season_list}) AND arm_angle IS NOT NULL
              {GATES}
            GROUP BY 1, 2
        """).df().set_index(["pitch_type", "band"])
        # season-mean movement per pitcher x type (his own arm-side-normalized HB)
        pm = con.sql(f"""
            SELECT pitcher AS id, season, pitch_type,
                   AVG(pfx_z) * 12 AS my_ivb,
                   AVG(pfx_x * 12 * CASE WHEN p_throws = 'L' THEN -1 ELSE 1 END) AS my_hb_arm,
                   AVG(arm_angle) AS arm
            FROM pitches_all
            WHERE game_type = 'R' AND season IN ({season_list})
              {GATES} AND arm_angle IS NOT NULL
              AND pitcher IN (SELECT pitcher FROM pitches_all WHERE game_type = 'R' AND season IN ({season_list})
                              GROUP BY 1)
            GROUP BY 1, 2, 3
        """).df().sort_values(["id", "season", "pitch_type"])
        pm = pm[[keep_row(int(row.id), int(row.season)) for row in pm.itertuples()]]
        # his band = primary fastball's arm angle that season
        fb_counts = bytype[(bytype["pitch_type"].isin(("FF", "SI", "FC"))) & (bytype["season"].isin(seasons))]
        pid_band = {}
        for (pid, season), sub in fb_counts.groupby(["id", "season"]):
            sub = sub[sub["arm_angle"].notna()]
            if sub.empty:
                continue
            row = sub.sort_values(["n", "pitch_type"], ascending=[False, True]).iloc[0]
            aa = float(row["arm_angle"])
            band = ("ott" if aa >= 60 else "high34" if aa >= 45 else "34" if aa >= 30 else
                    "low34" if aa >= 15 else "side" if aa >= 0 else "sub")
            pid_band[(int(pid), int(season))] = band
        pm["band"] = [pid_band.get((int(row.id), int(row.season))) for row in pm.itertuples()]
        pm["d_ivb"] = [row.my_ivb - slot_league.loc[(row.pitch_type, row.band)]["exp_ivb"]
                       if row.band is not None and (row.pitch_type, row.band) in slot_league.index else None
                       for row in pm.itertuples()]
        pm["d_hb"] = [row.my_hb_arm - slot_league.loc[(row.pitch_type, row.band)]["exp_hb_arm"]
                      if row.band is not None and (row.pitch_type, row.band) in slot_league.index else None
                      for row in pm.itertuples()]
        # delta populations per (type, band) -> rank helper
        delta_pool = {}
        for row in pm.itertuples():
            if row.band is None or row.d_ivb is None:
                continue
            delta_pool.setdefault((row.pitch_type, row.band), []).append(
                (float(row.d_ivb), float(row.d_hb)))

        def delta_rank(pool: list, v: float) -> int | None:
            vals = sorted(x for x in pool if x is not None)
            if len(vals) < 10:
                return None
            below = sum(1 for x in vals if x < v)
            eq = sum(1 for x in vals if x == v)
            return int(round(100 * (below + eq / 2) / len(vals)))

        def cell_sd(pool: list, idx: int) -> float | None:
            vals = [x[idx] for x in pool if x[idx] is not None]
            if len(vals) < 10:
                return None
            m = sum(vals) / len(vals)
            return (sum((x - m) ** 2 for x in vals) / len(vals)) ** 0.5

        def arm_rank(pool: list, v: float) -> int | None:
            vals = sorted(x for x in pool if x is not None)
            if len(vals) < 10:
                return None
            below = sum(1 for x in vals if x < v)
            return int(round(100 * below / len(vals)))

        # arm-angle league distribution per type
        arm_pool = con.sql(f"""
            SELECT pitch_type, arm_angle FROM pitches_all
            WHERE game_type = 'R' AND season IN ({season_list}) AND arm_angle IS NOT NULL {GATES}
            ORDER BY pitch_type, arm_angle
        """).df()
        arm_by_type = {k: list(v) for k, v in arm_pool.groupby("pitch_type")["arm_angle"]}
        print(f"slot league cells: {len(slot_league)}; delta cells: {len(delta_pool)}")

        # slot/{id}.json — the arm-slot file, latest season, with the slot deltas (PP13)
        slot_mean_g = pm.set_index(["id", "season", "pitch_type"])
        n_slot_files = 0
        slot_written: set[int] = set()
        slot_pairs: set[tuple[int, int]] = set()
        for pid, season in season_iter:
            if (pid, season) not in pid_band:
                continue
            band = pid_band[(pid, season)]
            rows_out = []
            throws_sign = -1 if tot_indexed.loc[(pid, season)]["throws"] == "L" else 1
            types = bytype[(bytype["id"] == pid) & (bytype["season"] == season) & (bytype["n"] >= 10)]
            for tr in types.itertuples():
                key3 = (pid, season, tr.pitch_type)
                if key3 not in slot_mean_g.index:
                    continue
                mine = slot_mean_g.loc[key3]
                cell = slot_league.loc[(tr.pitch_type, band)] if (tr.pitch_type, band) in slot_league.index else None
                pool = delta_pool.get((tr.pitch_type, band))
                d_ivb = float(mine["my_ivb"] - cell["exp_ivb"]) if cell is not None else None
                d_hb_arm = float(mine["my_hb_arm"] - cell["exp_hb_arm"]) if cell is not None else None
                rows_out.append({
                    "type": tr.site, "n": int(tr.n),
                    "swings": int(tr.swings), "whiffs": int(tr.whiff),
                    "arm": f(mine["arm"], 1),
                    "armPct": arm_rank(arm_by_type.get(tr.pitch_type, []), float(mine["arm"])),
                    "relH": f(tr.rel_h, 2), "relS": f(tr.rel_s, 2), "ext": f(tr.ext, 2),
                    "velo": f(tr.velo, 1), "ivb": f(tr.ivb, 1), "hb": f(tr.hb, 1), "spin": r(tr.spin),
                    "expIvb": f(cell["exp_ivb"], 1) if cell is not None else None,
                    "expHb": f(cell["exp_hb_arm"] * throws_sign, 1) if cell is not None else None,
                    "dIvb": f(d_ivb, 1), "dHb": f(d_hb_arm * throws_sign, 1),
                    "dIvbPct": delta_rank([x[0] for x in pool], d_ivb) if pool and d_ivb is not None else None,
                    "dHbPct": delta_rank([x[1] for x in pool], d_hb_arm) if pool and d_hb_arm is not None else None,
                    # uncertainty of the slot expectation: the spread of that cell's
                    # pitcher-season shapes around its mean (arm-side-normalized HB,
                    # un-mirrored here for the row's hand)
                    "sdIvb": f(cell_sd(pool, 0), 1) if pool else None,
                    "sdHb": f(cell_sd(pool, 1), 1) if pool else None,
                })
            if not rows_out:
                continue
            slot_doc = {
                "season": season, "throws": tot_indexed.loc[(pid, season)]["throws"], "band": band,
                "minPitches": 10, "types": rows_out,
            }
            # {pid}-{season}.json per season; bare {pid}.json = latest (season_iter is sorted)
            jwrite(out / "slot" / f"{pid}-{season}.json", slot_doc, sort_keys=True)
            jwrite(out / "slot" / f"{pid}.json", slot_doc, sort_keys=True)
            slot_written.add(pid)
            slot_pairs.add((pid, season))
            n_slot_files += 1
        counts["slot_files"] = n_slot_files
        print(f"slot files: {n_slot_files}")
        if player is None and latest_ok:
            pruned = 0
            for p in (out / "slot").glob("*.json"):
                pid_s, _, s_ = p.stem.partition("-")
                stale = (((int(pid_s), int(s_)) not in slot_pairs and int(s_) in seasons) if s_
                         else int(pid_s) not in slot_written)
                if stale:
                    p.unlink()
                    pruned += 1
            print(f"pruned stale slot files: {pruned}")

    # ------------------------------------------------- run value in context (PP19)
    # The situations a pitcher was handed, priced from the data itself. The
    # league's base-out run expectancy comes from every PA in the season (runs
    # scored in the rest of the half-inning from that state); leverage index =
    # state RE / overall RE. Descriptive season totals — situations are handed
    # to a pitcher, not earned, so nothing here is graded, and a neutral-value
    # model (stripping the situation out of run value) is NOT in scope.
    if "detail" in fams and tot_indexed is not None:
        # the same population the game logs publish: graded, kept pitcher-seasons
        pitcher_pop = {(pid, s) for (pid, s) in g.index
                       if keep_row(int(pid), int(s)) and (pid, s) in tot_indexed.index}
        for s in seasons:
            re_df = con.sql(f"""
                WITH pa AS (
                  SELECT game_pk, inning, inning_topbot, at_bat_number,
                         CASE WHEN on_1b IS NULL THEN 0 ELSE 1 END
                           + CASE WHEN on_2b IS NULL THEN 0 ELSE 2 END
                           + CASE WHEN on_3b IS NULL THEN 0 ELSE 4 END AS bases,
                         outs_when_up,
                         -- the BATTING team's score: pre-pitch state, half-inning end is POST
                         CASE WHEN inning_topbot = 'Top' THEN away_score ELSE home_score END AS bat_score_pre,
                         CASE WHEN inning_topbot = 'Top' THEN post_away_score ELSE post_home_score END AS bat_score_post
                  FROM pitches_all
                  WHERE game_type = 'R' AND season = {s} AND events IS NOT NULL
                ),
                ends AS (
                  SELECT game_pk, inning, inning_topbot, at_bat_number, bases, outs_when_up, bat_score_pre,
                         MAX(bat_score_post) OVER (PARTITION BY game_pk, inning, inning_topbot) AS inning_end
                  FROM pa
                )
                SELECT bases, outs_when_up, COUNT(*) AS n,
                       AVG(inning_end - bat_score_pre) AS re
                FROM ends
                WHERE outs_when_up BETWEEN 0 AND 2
                GROUP BY 1, 2
            """).df()
            if re_df.empty:
                continue
            re_map = {(int(rr.bases), int(rr.outs_when_up)): float(rr.re) for rr in re_df.itertuples()}
            overall = float((re_df["re"] * re_df["n"]).sum() / re_df["n"].sum())
            li = {k2: (v / overall if overall else None) for k2, v in re_map.items()}
            states = sorted((v for v in li.values() if v is not None), reverse=True)
            hi_cut, lo_cut = states[len(states) // 3], states[2 * len(states) // 3]
            case_li = " ".join(f"WHEN bases + 8 * outs_when_up = {b + 8 * o} THEN {round(v, 4)}"
                               for (b, o), v in sorted(li.items()) if v is not None)
            lev = con.sql(f"""
                WITH pp AS (
                  SELECT pitcher,
                         CASE WHEN on_1b IS NULL THEN 0 ELSE 1 END
                           + CASE WHEN on_2b IS NULL THEN 0 ELSE 2 END
                           + CASE WHEN on_3b IS NULL THEN 0 ELSE 4 END AS bases,
                         outs_when_up, delta_pitcher_run_exp
                  FROM pitches_all
                  WHERE game_type = 'R' AND season = {s} AND pitcher IS NOT NULL
                    {GATES}
                ),
                priced AS (
                  SELECT pitcher, delta_pitcher_run_exp,
                         CASE {case_li} ELSE NULL END AS li
                  FROM pp
                )
                SELECT pitcher AS id, COUNT(*) AS n, AVG(li) AS mean_li,
                       SUM(delta_pitcher_run_exp) AS rv_all,
                       SUM(CASE WHEN li >= {hi_cut} THEN delta_pitcher_run_exp ELSE 0 END) AS rv_hi,
                       SUM(CASE WHEN li >= {lo_cut} AND li < {hi_cut} THEN delta_pitcher_run_exp ELSE 0 END) AS rv_mid,
                       SUM(CASE WHEN li < {lo_cut} THEN delta_pitcher_run_exp ELSE 0 END) AS rv_lo,
                       SUM(CASE WHEN li >= {hi_cut} THEN 1 ELSE 0 END) AS n_hi,
                       SUM(CASE WHEN li >= {lo_cut} AND li < {hi_cut} THEN 1 ELSE 0 END) AS n_mid,
                       SUM(CASE WHEN li < {lo_cut} THEN 1 ELSE 0 END) AS n_lo
                FROM priced GROUP BY 1
            """).df()
            pub = lev[lev["n"] >= 200]
            order = sorted(pub["mean_li"].dropna().tolist())
            lev_pct = {int(lr.id): (round(100 * sum(1 for x in order if x < lr.mean_li) / len(order))
                                   if order and lr.mean_li is not None else None)
                       for lr in lev.itertuples()}
            n_pub = 0
            for lr in lev.itertuples():
                if lr.n < 200 or (int(lr.id), s) not in pitcher_pop:
                    continue
                sit_doc = {
                    "id": str(lr.id), "season": s, "pitches": int(lr.n),
                    "leverageFaced": f(lr.mean_li, 2) if lr.mean_li is not None else None,
                    "leveragePct": lev_pct.get(int(lr.id)),
                    "rvPer100": f(100 * lr.rv_all / lr.n, 2),
                    "highLeverage": {"n": int(lr.n_hi),
                                     "rvPer100": f(100 * lr.rv_hi / lr.n_hi, 2) if lr.n_hi >= 50 else None},
                    "midLeverage": {"n": int(lr.n_mid),
                                    "rvPer100": f(100 * lr.rv_mid / lr.n_mid, 2) if lr.n_mid >= 50 else None},
                    "lowLeverage": {"n": int(lr.n_lo),
                                    "rvPer100": f(100 * lr.rv_lo / lr.n_lo, 2) if lr.n_lo >= 50 else None},
                    "meta": {"hiCut": f(hi_cut, 2), "loCut": f(lo_cut, 2),
                             "note": ("leverage = the base-out state's run expectancy over the league average, "
                                      "measured this season; situations are handed to a pitcher — never graded")},
                }
                # {id}-{season}.json per season; bare {id}.json = latest (seasons ascend)
                jwrite(out / "situational" / f"{lr.id}-{s}.json", sit_doc, sort_keys=True)
                jwrite(out / "situational" / f"{lr.id}.json", sit_doc, sort_keys=True)
                n_pub += 1
            counts[f"situational_{s}"] = n_pub
            print(f"situational {s}: {n_pub} pitchers published (states {len(li)}, cuts {hi_cut:.2f}/{lo_cut:.2f})")

    # ------------------------------------------------------ Savant reference
    savant_meta = []
    print(f"[{time.time() - t0:.0f}s] savant", flush=True)  # per-family timing
    if "savant" in fams:
        def savant_rows(table: str, cols: dict, sort_desc: str | None) -> list[dict]:
            names = ", ".join(f'"{src}" AS {dst}' for src, dst in cols.items())
            id_dst = next((dst for dst in cols.values() if dst == "id"), None)
            if sort_desc:
                order = f' ORDER BY "{sort_desc}" DESC NULLS LAST'
                if id_dst and id_dst != sort_desc:
                    order += f', "{id_dst}"'
            elif id_dst:
                order = f' ORDER BY "{id_dst}"'
            else:
                order = ""
            try:
                df = con.sql(f'SELECT {names} FROM {table}{order}').df()
            except Exception as e:  # noqa: BLE001 — a missing family-year is legitimate
                print(f"  ! {table}: {e}")
                return []
            return json.loads(df.to_json(orient="records"))

        SAVANT_BOARDS = {
            "bat_tracking": {
                "title": "Bat tracking", "csv": "bat-tracking",
                "source": "Baseball Savant — bat tracking leaderboard", "sort": "avg_bat_speed",
                "cols": {"id": "id", "name": "player", "avg_bat_speed": "avg_bat_speed",
                         "hard_swing_rate": "hard_swing_rate", "squared_up_per_swing": "squared_up_per_swing",
                         "blast_per_swing": "blast_per_swing", "swing_length": "swing_length",
                         "whiff_per_swing": "whiff_per_swing", "batter_run_value": "batter_run_value"},
            },
            "swing_take": {
                "title": "Swing & take", "csv": "swing-take",
                "source": "Baseball Savant — swing/take leaderboard", "sort": None,
                "cols": {"player_id": "id", "last_name, first_name": "player", "team_id": "team",
                         "pa": "pa", "pitches": "pitches", "runs_all": "runs_all",
                         "runs_heart": "runs_heart", "runs_shadow": "runs_shadow",
                         "runs_chase": "runs_chase", "runs_waste": "runs_waste"},
            },
            "expected_statistics_batter": {
                "title": "Expected stats — hitters", "csv": "expected-statistics-batter",
                "source": "Baseball Savant — expected statistics (batters)", "sort": "est_woba",
                "cols": {"player_id": "id", "last_name, first_name": "player", "pa": "pa",
                         "ba": "ba", "est_ba": "est_ba", "slg": "slg", "est_slg": "est_slg",
                         "woba": "woba", "est_woba": "est_woba"},
            },
            "expected_statistics_pitcher": {
                "title": "Expected stats — pitchers", "csv": "expected-statistics-pitcher",
                "source": "Baseball Savant — expected statistics (pitchers)", "sort": "est_woba",
                "cols": {"player_id": "id", "last_name, first_name": "player", "pa": "pa",
                         "est_ba": "est_ba", "est_slg": "est_slg", "woba": "woba", "est_woba": "est_woba",
                         "era": "era", "xera": "xera"},
            },
            "oaa": {
                "title": "Outs Above Average", "csv": "outs_above_average",
                "source": "Baseball Savant — outs above average", "sort": None,
                "cols": {},
            },
            "frv": {
                "title": "Fielding Run Value", "csv": "fielding-run-value",
                "source": "Baseball Savant — fielding run value", "sort": None,
                "cols": {},
            },
            "sprint_speed": {
                "title": "Sprint speed", "csv": "sprint_speed",
                "source": "Baseball Savant — sprint speed (27 ft/s population)", "sort": None,
                "cols": {},
            },
            "baserunning_rv": {
                "title": "Baserunning run value", "csv": "baserunning_run_value",
                "source": "Baseball Savant — baserunning run value (runner)",
                "sort": "runner_runs_tot",
                "cols": {"player_id": "id", "entity_name": "player", "team_name": "team",
                         "runner_runs_tot": "runs", "runner_runs_XB": "xb_runs",
                         "runner_runs_SBX": "steal_runs", "N_runner_moved": "times_moved",
                         "N_runner_moved_XB": "xb_attempts", "runner_runs_XB_swipe": "xb_swipe",
                         "runner_runs_XB_snipe": "xb_snipe", "runner_runs_XB_freeze": "xb_freeze"},
            },
            "basestealing_rv": {
                "title": "Basestealing run value", "csv": "basestealing_run_value",
                "source": "Baseball Savant — basestealing run value (leads + steals)",
                "sort": "runs_stolen_on_running_act",
                "cols": {"player_id": "id", "player_name": "player", "team_name": "team",
                         "runs_stolen_on_running_act": "runs", "n_sb": "sb", "n_cs": "cs",
                         "rate_sbx": "sb_rate", "r_primary_lead": "primary_lead_runs",
                         "r_secondary_lead": "secondary_lead_runs",
                         "net_act_plus": "net_act_plus", "net_act_minus": "net_act_minus"},
            },
            "abs_challenges": {
                "title": "ABS challenges", "csv": "abs-challenges",
                "source": "Baseball Savant — ABS challenges (2026 challenge era)",
                "sort": "runs_above_average",
                "cols": {"entity_name": "player", "team_abbr": "team", "level": "level",
                         "n_challenges": "challenges", "n_overturns": "overturns",
                         "n_confirms": "confirms", "rate_overturns": "win_rate",
                         "runs_gained": "runs_gained", "runs_cost": "runs_cost",
                         "runs_above_average": "runs", "runs_gained_vs_exp": "gained_vs_exp",
                         "runs_cost_vs_exp": "cost_vs_exp", "runs_taken_percent": "runs_taken_pct",
                         "poss_runs": "possible_runs"},
            },
            "xb_taken": {
                "title": "Extra bases taken", "csv": "baserunning",
                "source": "Baseball Savant — extra bases taken (runner view)",
                "sort": "runner_runs",
                "cols": {"entity_id": "id", "entity_name": "player", "team_name": "team",
                         "runner_runs": "runs", "n_opp_xb": "opportunities", "n_att_xb": "attempts",
                         "rate_att_xb": "attempt_rate", "est_rate_att_generic_runner": "lg_attempt_rate",
                         "n_out": "outs_made", "n_safe": "safe", "rate_safe": "safe_rate"},
            },
            "catcher_framing": {
                "title": "Catcher framing", "csv": "catcher-framing",
                "source": "Baseball Savant — catcher framing (validation reference, not our Framing+)",
                "sort": "rv_tot", "cols": {"id": "id", "name": "player", "pitches": "pitches",
                                           "rv_tot": "run_value", "pct_tot": "pct_rank"},
            },
            "catcher_blocking": {
                "title": "Catcher blocking", "csv": "catcher-blocking",
                "source": "Baseball Savant — catcher blocking", "sort": "catcher_blocking_runs",
                "cols": {"player_id": "id", "player_name": "player", "team_name": "team",
                         "pitches": "pitches", "catcher_blocking_runs": "run_value",
                         "blocks_above_average": "blocks_above_average"},
            },
            "catcher_throwing": {
                "title": "Catcher throwing", "csv": "catcher-throwing",
                "source": "Baseball Savant — catcher throwing", "sort": "catcher_stealing_runs",
                "cols": {"player_id": "id", "player_name": "player", "team_name": "team",
                         "sb_attempts": "sb_attempts", "catcher_stealing_runs": "run_value",
                         "caught_stealing_above_average": "cs_above_average", "pop_time": "pop_time",
                         "arm_strength": "arm_strength"},
            },
        }
        for family, spec in SAVANT_BOARDS.items():
            seasons_out, all_rows = [], []
            for year in seasons:
                table = f"lb_{spec['csv'].replace('-', '_')}_{year}"
                cols = spec["cols"]
                if not cols:  # inspect once, keep the file's own shape with renamed identity cols
                    try:
                        src_cols = con.sql(f"SELECT * FROM {table} LIMIT 0").columns
                    except Exception:  # noqa: BLE001
                        continue
                    cols = {}
                    for sc in src_cols:
                        dst = {"id": "id", "name": "player", "player_id": "id",
                               "last_name, first_name": "player", "first_name": None}.get(sc, sc)
                        if dst:
                            cols[sc] = dst
                rows = savant_rows(table, cols, spec["sort"])
                for row in rows:
                    row["season"] = year
                if rows:
                    seasons_out.append(year)
                    all_rows.extend(rows)
            if not all_rows:
                continue
            columns = [{"key": "player", "label": "Player", "align": "left"},
                       {"key": "season", "label": "Season", "align": "right"}]
            seen = set()
            for row in all_rows[:5]:
                for k in row:
                    if k not in ("player", "id", "season") and k not in seen:
                        seen.add(k)
                        columns.append({"key": k, "label": k.replace("_", " "),
                                        "align": "left" if k in ("player_id", "team_name", "team") else "right"})
            board_out = {
                "family": family, "title": spec["title"], "source": spec["source"],
                "source_url": "https://baseballsavant.mlb.com/leaderboard/",
                "label": "Descriptive attributed Savant data — not a GOAT-Pro model, not a forecast",
                # Rows open a goat-pro profile when the side exists: pitcher boards
                # and, since wave 2b, the two batter boards. Catcher ids have no
                # player file and render plain.
                "link_players": family in ("expected_statistics_pitcher", "expected_statistics_batter", "bat_tracking"),
                "seasons": seasons_out, "columns": columns, "rows": all_rows,
            }
            jwrite(out / "savant" / f"{family}.json", board_out)
            savant_meta.append({"family": family, "rows": len(all_rows), "seasons": seasons_out})
            print(f"savant/{family}: {len(all_rows)} rows {seasons_out}")
        counts["savant_boards"] = {m["family"]: m["rows"] for m in savant_meta}

    # ------------------------------------------------------------- hitters (H1/H3/H4, PH2)
    # The hitter side, DERIVABLE-NOW only: slash + derived wOBA, batted-ball
    # quality, plate discipline, and splits vs hand and pitch family. The model
    # columns (xwOBA, decision grades, catcher grades, park factors) are
    # NEEDS-MODEL and stay stripped. Hitters face every pitch, so only the
    # gross data-error gates apply here (speed sanity band, hands known) — the
    # pitcher-side movement gates must not thin a hitter's plate-discipline
    # denominators.
    print(f"[{time.time() - t0:.0f}s] hitters", flush=True)  # per-family timing
    if "hitters" in fams:
        from pathlib import Path as _P
        ROSTERS = f"{MART_DIR}/data/daily/rosters_*.parquet"
        names_df = con.sql(f"""
            SELECT person_id, arg_max(full_name, date) AS name
            FROM read_parquet('{ROSTERS}') GROUP BY 1
        """).df()
        h_names = {int(row.person_id): row.name for row in names_df.itertuples()}
        if level == "aaa":
            h_names = {**h_names, **milb_names("hitters")}
        # a hitter off every current snapshot (traded, released, retired mid-season)
        # still needs a name: fall back to the Savant batter boards already in the mart.
        for s in seasons:
            for table in (f"lb_expected_statistics_batter_{s}", f"lb_bat_tracking_{s}"):
                try:
                    alt = con.sql(f'SELECT CAST(id AS BIGINT) AS pid, player AS name FROM {table}').df()
                except Exception:  # noqa: BLE001 — a missing family-year is fine
                    continue
                for row in alt.itertuples():
                    h_names.setdefault(int(row.pid), row.name)
        # last resort: the Chadwick register in the mart (269 of 849 indexed hitters had no name before it)
        for row in con.sql("SELECT CAST(key_mlbam AS BIGINT) AS pid, name_first || ' ' || name_last AS name "
                           "FROM register WHERE key_mlbam IS NOT NULL AND name_last IS NOT NULL").df().itertuples():
            h_names.setdefault(int(row.pid), row.name)

        # launch_speed is NULL on every taken/offswing pitch — NEVER gate on it or
        # the discipline denominators silently shrink to balls in play.
        HITTER_GATE = "AND stand IN ('L','R') AND p_throws IN ('L','R')"

        # -- wOBA weights, derived from this mart per season (the FIP-constant
        # precedent: self-consistent, not quoted). rv_e = mean run-expectancy
        # change of PAs ending in the event (delta_run_exp is batter-positive);
        # the weight is the value vs an out; the scale centres the league
        # average at the conventional .310.
        woba = {}
        for s in seasons:
            ev = con.sql(f"""
                SELECT events, AVG(delta_run_exp) AS rv, COUNT(*) AS n
                FROM pitches_all
                WHERE game_type = 'R' AND season = {s} AND batter IS NOT NULL
                  AND events IS NOT NULL AND delta_run_exp IS NOT NULL
                GROUP BY 1
            """).df().set_index("events")
            outs = ("field_out", "force_out", "fielders_choice_out", "grounded_into_double_play",
                    "strikeout", "strikeout_double_play", "double_play", "sac_fly", "sac_bunt",
                    "sac_fly_double_play")
            rv_out = float(sum(ev.loc[e, "rv"] * ev.loc[e, "n"] for e in outs if e in ev.index)
                           / sum(ev.loc[e, "n"] for e in outs if e in ev.index))
            wts = {}
            for e in ("walk", "intent_walk", "hit_by_pitch", "single", "double", "triple", "home_run"):
                if e in ev.index:
                    wts[e] = float(ev.loc[e, "rv"]) - rv_out
            woba[s] = wts
        print("wOBA weights (vs out):", {s: {k: round(v, 3) for k, v in w.items()} for s, w in woba.items()})

        BARREL_SQL = "(launch_speed_angle = 6)::INT"  # Savant's own barrel flag (the old table stopped widening at 113 mph)

        hag_sql = f"""
            SELECT batter AS id, season, {{team}}
                   COUNT(DISTINCT CASE WHEN events IS NOT NULL AND events <> 'truncated_pa' THEN (game_pk, at_bat_number) END) AS pa,
                   COUNT(*) AS pitches_seen,
                   SUM(CASE WHEN events = 'single' THEN 1 ELSE 0 END) AS s1,
                   SUM(CASE WHEN events = 'double' THEN 1 ELSE 0 END) AS s2,
                   SUM(CASE WHEN events = 'triple' THEN 1 ELSE 0 END) AS s3,
                   SUM(CASE WHEN events = 'home_run' THEN 1 ELSE 0 END) AS hr,
                   SUM(CASE WHEN events IN ('walk','intent_walk') THEN 1 ELSE 0 END) AS bb,  -- all walks; ibb split out
                   SUM(CASE WHEN events = 'intent_walk' THEN 1 ELSE 0 END) AS ibb,
                   SUM(CASE WHEN events = 'hit_by_pitch' THEN 1 ELSE 0 END) AS hbp,
                   SUM(CASE WHEN events IN ('sac_fly','sac_fly_double_play') THEN 1 ELSE 0 END) AS sf,
                   SUM(CASE WHEN events = 'sac_bunt' THEN 1 ELSE 0 END) AS sh,
                   SUM(CASE WHEN events = 'catcher_interf' THEN 1 ELSE 0 END) AS ci,
                   SUM(CASE WHEN events IN ('strikeout','strikeout_double_play') THEN 1 ELSE 0 END) AS k,
                   SUM(CASE WHEN description IN ('swinging_strike','swinging_strike_blocked','foul_tip') THEN 1 ELSE 0 END) AS whiffs,
                   SUM(CASE WHEN description IN {SWING} THEN 1 ELSE 0 END) AS swings,
                   SUM(CASE WHEN description IN ('called_strike') THEN 1 ELSE 0 END) AS called,
                   SUM(CASE WHEN zone BETWEEN 1 AND 9 THEN 1 ELSE 0 END) AS n_zone,
                   SUM(CASE WHEN zone BETWEEN 1 AND 9 AND description IN {SWING} THEN 1 ELSE 0 END) AS n_zone_swing,
                   SUM(CASE WHEN zone BETWEEN 10 AND 14 THEN 1 ELSE 0 END) AS n_ooz,
                   SUM(CASE WHEN zone BETWEEN 10 AND 14 AND description IN {SWING} THEN 1 ELSE 0 END) AS n_ooz_swing,
                   SUM(CASE WHEN balls = 0 AND strikes = 0 AND description IN {SWING} THEN 1 ELSE 0 END) AS n_fpswing,
                   SUM(CASE WHEN balls = 0 AND strikes = 0 THEN 1 ELSE 0 END) AS n_firstpitch,
                   SUM(CASE WHEN strikes = 2 AND zone BETWEEN 10 AND 14 AND description IN {SWING} THEN 1 ELSE 0 END) AS n_2k_ooz_swing,
                   SUM(CASE WHEN strikes = 2 AND zone BETWEEN 10 AND 14 THEN 1 ELSE 0 END) AS n_2k_ooz,
                   SUM(CASE WHEN bb_type IS NOT NULL THEN 1 ELSE 0 END) AS bip,
                   SUM(CASE WHEN bb_type = 'ground_ball' THEN 1 ELSE 0 END) AS gb,
                   SUM(CASE WHEN bb_type = 'fly_ball' THEN 1 ELSE 0 END) AS fb,
                   SUM(CASE WHEN bb_type = 'line_drive' THEN 1 ELSE 0 END) AS ld,
                   SUM(CASE WHEN bb_type = 'popup' THEN 1 ELSE 0 END) AS pu,
                   SUM(CASE WHEN bb_type IS NOT NULL AND launch_speed >= 95 THEN 1 ELSE 0 END) AS n_hard,
                   SUM({BARREL_SQL}) AS n_barrel,
                   AVG(launch_speed) FILTER (WHERE bb_type IS NOT NULL AND des NOT ILIKE '%bunt%') AS avg_ev,
                   AVG(launch_angle) FILTER (WHERE bb_type IS NOT NULL AND des NOT ILIKE '%bunt%') AS avg_la,
                   QUANTILE_CONT(launch_speed, 0.9) FILTER (WHERE bb_type IS NOT NULL) AS ev90,
                   MAX(launch_speed) FILTER (WHERE bb_type IS NOT NULL) AS maxev
            FROM pitches_all
            WHERE game_type = 'R' AND season IN ({season_list}) AND batter IS NOT NULL
              AND description IS NOT NULL {HITTER_GATE}
            GROUP BY ALL
        """
        hag = con.sql(hag_sql.format(team="")).df()
        hag["id"] = hag["id"].astype(int)
        hag = hag.sort_values(["id", "season"])

        hteam_map, team_stints_h = team_stints(con, "batter", season_list)
        # per-club lines for hitters who changed teams (raw stats; the season row keeps the models)
        hag_team = con.sql(hag_sql.format(
            team="CASE WHEN inning_topbot = 'Top' THEN away_team ELSE home_team END AS team, COUNT(DISTINCT game_pk) AS g,")).df()
        hag_team = hag_team[[(int(a), int(b)) in team_stints_h for a, b in zip(hag_team["id"], hag_team["season"])]]

        # zone whiffs must be exact: re-pull just that column rather than approximate.
        zw = con.sql(f"""
            SELECT batter AS id, season,
                   SUM(CASE WHEN zone BETWEEN 1 AND 9 AND description IN ('swinging_strike','swinging_strike_blocked','foul_tip') THEN 1 ELSE 0 END) AS n_zone_whiff
            FROM pitches_all
            WHERE game_type = 'R' AND season IN ({season_list}) AND batter IS NOT NULL
              AND description IS NOT NULL {HITTER_GATE}
            GROUP BY 1, 2
        """).df()
        zw_map = {(int(row.id), int(row.season)): int(row.n_zone_whiff) for row in zw.itertuples()}
        hag["n_zone_whiff"] = [zw_map.get((int(rr.id), int(rr.season)), 0) for rr in hag.itertuples()]

        # the scale: league average reads .310, everything moves proportionally
        league_rows = hag[hag["pa"] >= 100]
        hfactor = {}
        for s in seasons:
            sub = league_rows[league_rows["season"] == s]
            if not len(sub):
                continue
            num = 0.0
            den_all = 0.0
            for t in sub.itertuples():
                ab = t.pa - t.bb - t.hbp - t.sf - t.sh - t.ci
                d = ab + (t.bb - t.ibb) + t.hbp + t.sf
                if d <= 0:
                    continue
                raw = (woba[s]["walk"] * (t.bb - t.ibb) + woba[s]["hit_by_pitch"] * t.hbp
                       + woba[s]["single"] * t.s1 + woba[s]["double"] * t.s2
                       + woba[s]["triple"] * t.s3 + woba[s]["home_run"] * t.hr)
                num += raw
                den_all += d
            lg_raw = num / den_all if den_all else 0.28
            hfactor[s] = 0.310 / lg_raw if lg_raw else 1.0
        print("wOBA scale factors:", {s: round(v, 4) for s, v in hfactor.items()})

        def woba_of(t, s):
            wt = woba.get(s)
            if not wt:
                return None
            ab = t.pa - t.bb - t.hbp - t.sf - t.sh - t.ci
            den = ab + (t.bb - t.ibb) + t.hbp + t.sf
            if not den:
                return None
            raw = (wt["walk"] * (t.bb - t.ibb) + wt["hit_by_pitch"] * t.hbp
                   + wt["single"] * t.s1 + wt["double"] * t.s2
                   + wt["triple"] * t.s3 + wt["home_run"] * t.hr)
            return raw / den * hfactor.get(s, 1.0)

        HITTER_PA_FLOOR = 50
        # D-34 depth (pipeline/hitter_depth.py): Savant expected stats, batted-ball
        # direction, bat tracking (>= 50 tracked swings), sprint speed, batting RV/100.
        from hitter_depth import hitter_depth, trends
        HD = {"xwoba": ("xwoba", 3), "xba": ("xba", 3), "xslg": ("xslg", 3), "xwobacon": ("xwobacon", 3),
              "xwoba_gap": ("wobaMinusXwoba", 3), "rv100": ("batRvPer100", 2), "sweet_spot": ("sweetSpotPct", 1),
              "woba": ("wobaSavant", 3), "rv100_fb": ("batRvPer100Fb", 2), "rv100_br": ("batRvPer100Br", 2),
              "rv100_os": ("batRvPer100Os", 2),
              "pull": ("pullPct", 1), "oppo": ("oppoPct", 1), "pull_air": ("pullAirPct", 1), "la_sd": ("laSd", 1),
              "bat_speed": ("batSpeed", 1), "fast_swing": ("fastSwingPct", 1), "swing_length": ("swingLength", 2),
              "attack_angle": ("attackAngle", 1), "ideal_aa": ("idealAaPct", 1),
              "squared_up": ("squaredUpPct", 1), "blast": ("blastPct", 1), "sprint_speed": ("sprintSpeed", 1)}
        hd = hitter_depth(con, tuple(seasons), level=level)
        h_trend = trends(con, tuple(seasons), who="batter", level=level)
        from hitter_proj import projections  # §67 Marcel + measured ranges (D-36)
        h_proj = projections(level, con)
        # §69 (D-02) swing decisions: descriptive, not a forecast (failed the gate, reliable); MLB only
        dec_f = ROOT / "pipeline" / "results" / "decisions_hitters.csv"
        h_dec = {}
        if level == "mlb" and dec_f.exists():
            for decr in pd.read_csv(dec_f).itertuples():
                h_dec[(int(decr.mlbam), int(decr.season))] = {
                    "drvPer100": f(decr.drv100, 2), "izaPer100": f(decr.iza, 2), "ozaPer100": f(decr.oza, 2),
                    "decisionPlus": f(decr.decision_plus, 0) if pd.notna(decr.decision_plus) else None}
        from savant_fielding import fielding  # D-16: Savant baserunning / fielding / catcher runs, descriptive
        h_fld = fielding(con, seasons) if level == "mlb" else {}
        h_depth = {(int(rr["id"]), int(rr["season"])): {k: f(rr[c], nd) for c, (k, nd) in HD.items() if c in rr}
                   for rr in hd.to_dict("records")}
        def h_line(t) -> dict:
            """One club's slash line for a hitter who changed teams."""
            ab = t.pa - t.bb - t.hbp - t.sf - t.sh - t.ci
            hits = t.s1 + t.s2 + t.s3 + t.hr
            obp_den = ab + t.bb + t.hbp + t.sf
            avg = f(hits / ab, 3) if ab else None
            obp = f((hits + t.bb + t.hbp) / obp_den, 3) if obp_den else None
            slg = f((t.s1 + 2 * t.s2 + 3 * t.s3 + 4 * t.hr) / ab, 3) if ab else None
            wv = woba_of(t, t.season)
            return {"team": t.team, "g": int(t.g), "pa": int(t.pa), "avg": avg, "obp": obp, "slg": slg,
                    "ops": f(obp + slg, 3) if obp is not None and slg is not None else None,
                    "iso": f(slg - avg, 3) if slg is not None and avg is not None else None, "nBip": int(t.bip),
                    "woba": f(wv, 3) if wv is not None else None, "hr": int(t.hr),
                    "kPct": f(100 * t.k / t.pa, 1) if t.pa else None, "bbPct": f(100 * t.bb / t.pa, 1) if t.pa else None,
                    "hardHitPct": f(100 * t.n_hard / t.bip, 1) if t.bip else None,
                    "barrelPct": f(100 * t.n_barrel / t.bip, 1) if t.bip else None,
                    "whiffPct": f(100 * t.whiffs / t.swings, 1) if t.swings else None,
                    "oSwingPct": f(100 * t.n_ooz_swing / t.n_ooz, 1) if t.n_ooz else None}

        h_team_lines: dict = {}
        for t in hag_team.itertuples():
            h_team_lines.setdefault((int(t.id), int(t.season)), []).append(h_line(t))
        for key, lines in h_team_lines.items():
            order = {st["team"]: i for i, st in enumerate(team_stints_h[key])}
            lines.sort(key=lambda x: order.get(x["team"], 99))

        hboard = []
        for t in hag.itertuples():
            key = (int(t.id), int(t.season))
            if t.pa < HITTER_PA_FLOOR:
                continue
            woba_v = woba_of(t, t.season)
            rates = {c: getattr(t, c) for c in ("pa", "pitches_seen", "s1", "s2", "s3", "hr", "bb", "ibb",
                                                "hbp", "sf", "sh", "ci", "k", "whiffs", "swings", "called",
                                                "n_zone", "n_zone_swing", "n_zone_whiff", "n_ooz", "n_ooz_swing",
                                                "n_fpswing", "n_firstpitch", "n_2k_ooz_swing", "n_2k_ooz",
                                                "bip", "gb", "fb", "ld", "pu", "n_hard", "n_barrel",
                                                "avg_ev", "avg_la", "ev90", "maxev")}
            row = {
                "id": str(t.id), "name": h_names.get(int(t.id)), "team": hteam_map.get(key), "teams": team_stints_h.get(key),
                "bats": None, "season": int(t.season), "pa": int(t.pa), "age": season_age(t.id, t.season),
                "woba": f(woba_v, 3) if woba_v is not None else None,
            }
            ab = rates["pa"] - rates["bb"] - rates["hbp"] - rates["sf"] - rates["sh"] - rates["ci"]
            tb = rates["s1"] + 2 * rates["s2"] + 3 * rates["s3"] + 4 * rates["hr"]
            row["avg"] = f((rates["s1"] + rates["s2"] + rates["s3"] + rates["hr"]) / ab, 3) if ab else None
            obp_den = ab + rates["bb"] + rates["hbp"] + rates["sf"]  # official OBP: catcher's interference is in neither term
            row["obp"] = f((rates["s1"] + rates["s2"] + rates["s3"] + rates["hr"] + rates["bb"] + rates["hbp"]) / obp_den, 3) if obp_den else None
            row["slg"] = f(tb / ab, 3) if ab else None
            row["ops"] = f((row["obp"] or 0) + (row["slg"] or 0), 3) if (row["obp"] is not None and row["slg"] is not None) else None
            row["iso"] = f((row["slg"] or 0) - (row["avg"] or 0), 3) if (row["slg"] is not None and row["avg"] is not None) else None
            row["kPct"] = f(100 * rates["k"] / rates["pa"], 1) if rates["pa"] else None
            row["bbPct"] = f(100 * rates["bb"] / rates["pa"], 1) if rates["pa"] else None
            row["ev90"] = f(rates["ev90"], 1)
            row["maxEv"] = f(rates["maxev"], 1)
            row["hardHitPct"] = f(100 * rates["n_hard"] / rates["bip"], 1) if rates["bip"] else None
            row["barrelPct"] = f(100 * rates["n_barrel"] / rates["bip"], 1) if rates["bip"] else None
            row["whiffPct"] = f(100 * rates["whiffs"] / rates["swings"], 1) if rates["swings"] else None
            row["contactPct"] = f(100 * (rates["swings"] - rates["whiffs"]) / rates["swings"], 1) if rates["swings"] else None
            row["swingPct"] = f(100 * rates["swings"] / rates["pitches_seen"], 1) if rates["pitches_seen"] else None
            row["oSwingPct"] = f(100 * rates["n_ooz_swing"] / rates["n_ooz"], 1) if rates["n_ooz"] else None
            row["nBip"] = int(rates["bip"])
            row.update(h_depth.get(key, {}))
            row.update(h_proj.get(key, {}))
            row.update(h_dec.get(key, {}))
            row.update(h_fld.get(key, {}))
            row["teamSplits"] = h_team_lines.get(key)
            hboard.append(row)
        hj = con.sql(f"""
            SELECT batter AS id, season, mode(stand) AS bats
            FROM pitches_all WHERE game_type = 'R' AND season IN ({season_list}) AND batter IS NOT NULL
            GROUP BY 1, 2
        """).df()
        bats_map = {(int(rr.id), int(rr.season)): rr.bats for rr in hj.itertuples()}
        for row in hboard:
            row["bats"] = bats_map.get((int(row["id"]), row["season"]))

        # discipline shrinkage (H4): the twin = (num + k*lgRate) / (den + k),
        # target = the season's league rate over 50+ PA hitters. Keys match the
        # hitters board + profile panel; a metric without a measured k stays raw.
        H_DISC_SHRINK = {
            "whiffPct": ("whiffs", "swings"),
            "contactPct": ("swings - whiffs", "swings"),
            "oSwingPct": ("n_ooz_swing", "n_ooz"),
            "zSwingPct": ("n_zone_swing", "n_zone"),
            "swingPct": ("swings", "pitches_seen"),
            "swStrPct": ("whiffs", "pitches_seen"),
            "firstPitchSwingPct": ("n_fpswing", "n_firstpitch"),
            "twoKChasePct": ("n_2k_ooz_swing", "n_2k_ooz"),
        }
        h_lg = {}
        for s in seasons:
            agg = hag[(hag["season"] == s) & (hag["pa"] >= 50)]
            rates = {}
            for key, (num, den) in H_DISC_SHRINK.items():
                num_sum = float(eval(num, {"__builtins__": {}}, {c: agg[c].sum() for c in agg.columns})) if len(agg) else 0.0
                den_sum = float(eval(den, {"__builtins__": {}}, {c: agg[c].sum() for c in agg.columns})) if len(agg) else 0.0
                rates[key] = 100 * num_sum / den_sum if den_sum else None
            h_lg[s] = rates

        def h_shrunk(t, season: int) -> dict:
            out = {}
            lg = h_lg.get(season, {})
            for key, (num, den) in H_DISC_SHRINK.items():
                k = DISC_HALF_HITTER.get(key)
                den_v = float(eval(den, {"__builtins__": {}}, {c: getattr(t, c) for c in
                              ("whiffs", "swings", "n_ooz_swing", "n_ooz", "n_zone_swing", "n_zone",
                               "pitches_seen", "called", "n_fpswing", "n_firstpitch",
                               "n_2k_ooz_swing", "n_2k_ooz")})) if k else 0.0
                if not k or not den_v:
                    out[f"{key}Shrunk"] = None
                    continue
                num_v = den_v * (float(eval(num, {"__builtins__": {}}, {c: getattr(t, c) for c in
                                 ("whiffs", "swings", "n_ooz_swing", "n_ooz", "n_zone_swing", "n_zone",
                                  "pitches_seen", "called", "n_fpswing", "n_firstpitch",
                                  "n_2k_ooz_swing", "n_2k_ooz")})) / den_v)
                out[f"{key}Shrunk"] = f(100 * (num_v + k * (lg.get(key) or 0) / 100) / (den_v + k), 1)
            return out

        # apply twins onto the board rows (hitters.json ships them)
        hag_idx = hag.set_index(["id", "season"])
        for row in hboard:
            k2 = (int(row["id"]), row["season"])
            if k2 in hag_idx.index:
                row.update(h_shrunk(hag_idx.loc[k2], row["season"]))
        hboard_df = pd.DataFrame(hboard).sort_values(["id", "season"])
        counts_board = len(hboard_df)
        print(f"hitter board rows: {counts_board}")

        # hitter percentiles (per season): pct5 + dense wOBA for the chips
        H_METRICS = ["woba", "obp", "slg", "avg", "ops", "iso", "kPct", "bbPct", "ev90", "maxEv",
                     "hardHitPct", "barrelPct", "whiffPct", "contactPct", "swingPct",
                     "oSwingPct", "nBip", *dict.fromkeys(k for k, _ in HD.values()),
                     "wobaProj", "kPctProj", "bbPctProj", "drvPer100", "izaPer100", "ozaPer100", "decisionPlus",
                     "bsrRuns", "xbRuns", "sbRuns", "frvRuns", "oaa", "framingRuns", "blockingRuns", "throwingRuns",
                     "popTime", "catcherArm"]
        h_pcts = {}
        h_dense = {}
        for s in seasons:
            sub = hboard_df[hboard_df["season"] == s]
            pcts = {}
            for m in H_METRICS:
                p5 = pct5(sub[m]) if m in sub.columns else None
                if p5:
                    pcts[m] = p5
            h_pcts[str(s)] = pcts
            q = dense_q(sub["woba"])
            if q:
                h_dense[str(s)] = {"woba": {"q": q, "n": int(len(sub))}}

        # splits: vs hand, vs pitch family (PH2) — same rate set, per PA floor
        FAM_SQL = """CASE pitch_type WHEN 'FF' THEN 'FB' WHEN 'SI' THEN 'FB' WHEN 'FC' THEN 'CT'
                   WHEN 'SL' THEN 'BR' WHEN 'SW' THEN 'BR' WHEN 'ST' THEN 'BR' WHEN 'SV' THEN 'BR'
                   WHEN 'CU' THEN 'BR' WHEN 'KC' THEN 'BR' WHEN 'CH' THEN 'OS' WHEN 'FS' THEN 'OS'
                   WHEN 'FO' THEN 'OS' WHEN 'EP' THEN 'OS' ELSE 'OS' END"""
        def split_rows(group_sql: str, label_fn):
            q = con.sql(f"""
                SELECT batter AS id, season, {group_sql} AS grp,
                       COUNT(DISTINCT CASE WHEN events IS NOT NULL AND events <> 'truncated_pa' THEN (game_pk, at_bat_number) END) AS pa,
                       SUM(CASE WHEN events = 'single' THEN 1 ELSE 0 END) AS s1,
                       SUM(CASE WHEN events = 'double' THEN 1 ELSE 0 END) AS s2,
                       SUM(CASE WHEN events = 'triple' THEN 1 ELSE 0 END) AS s3,
                       SUM(CASE WHEN events = 'home_run' THEN 1 ELSE 0 END) AS hr,
                       SUM(CASE WHEN events IN ('walk','intent_walk') THEN 1 ELSE 0 END) AS bb,  -- all walks; ibb split out
                       SUM(CASE WHEN events = 'intent_walk' THEN 1 ELSE 0 END) AS ibb,
                       SUM(CASE WHEN events = 'hit_by_pitch' THEN 1 ELSE 0 END) AS hbp,
                       SUM(CASE WHEN events IN ('sac_fly','sac_fly_double_play') THEN 1 ELSE 0 END) AS sf,
                       SUM(CASE WHEN events = 'sac_bunt' THEN 1 ELSE 0 END) AS sh,
                       SUM(CASE WHEN events = 'catcher_interf' THEN 1 ELSE 0 END) AS ci,
                       SUM(CASE WHEN events IN ('strikeout','strikeout_double_play') THEN 1 ELSE 0 END) AS k,
                       SUM(CASE WHEN description IN ('swinging_strike','swinging_strike_blocked','foul_tip') THEN 1 ELSE 0 END) AS whiffs,
                       SUM(CASE WHEN description IN {SWING} THEN 1 ELSE 0 END) AS swings,
                       AVG(launch_speed) FILTER (WHERE bb_type IS NOT NULL AND des NOT ILIKE '%bunt%') AS avg_ev
                FROM pitches_all
                WHERE game_type = 'R' AND season IN ({season_list}) AND batter IS NOT NULL
                  AND description IS NOT NULL {HITTER_GATE}
                GROUP BY 1, 2, 3
            """).df()
            out = {}
            for r in q.itertuples():
                if r.pa < 25:
                    continue
                key = (int(r.id), int(r.season))
                ab = r.pa - r.bb - r.hbp - r.sf - r.sh - r.ci
                den = ab + (r.bb - r.ibb) + r.hbp + r.sf
                raw = (woba[r.season]["walk"] * (r.bb - r.ibb) + woba[r.season]["hit_by_pitch"] * r.hbp
                       + woba[r.season]["single"] * r.s1 + woba[r.season]["double"] * r.s2
                       + woba[r.season]["triple"] * r.s3 + woba[r.season]["home_run"] * r.hr) if r.season in woba else 0.0
                tb = r.s1 + 2 * r.s2 + 3 * r.s3 + 4 * r.hr
                out.setdefault(key, []).append({
                    "v": label_fn(r.grp),
                    "pa": int(r.pa),
                    "avg": f((r.s1 + r.s2 + r.s3 + r.hr) / ab, 3) if ab else None,
                    "obp": f((r.s1 + r.s2 + r.s3 + r.hr + r.bb + r.hbp) / (ab + r.bb + r.hbp + r.sf), 3) if (ab + r.bb + r.hbp + r.sf) else None,
                    "slg": f(tb / ab, 3) if ab else None,
                    "woba": f(raw / den * hfactor.get(r.season, 1.0), 3) if den and r.season in woba else None,
                    "kPct": f(100 * r.k / r.pa, 1) if r.pa else None,
                    "bbPct": f(100 * r.bb / r.pa, 1) if r.pa else None,
                    "avgEv": f(r.avg_ev, 1),
                })
            return out
        vs_hand = split_rows("p_throws", lambda g: g)
        vs_fam = split_rows(FAM_SQL, lambda g: g)

        # Split benchmarks (H11): the league's line per split cell over the same
        # 50+ PA population, so a Splits table can carry a benchmark row — his
        # .268 vs RHP means nothing until ".268" has a league context.
        def league_splits(group_sql: str):
            q = con.sql(f"""
                SELECT season, {group_sql} AS grp,
                       COUNT(DISTINCT CASE WHEN events IS NOT NULL AND events <> 'truncated_pa' THEN (game_pk, at_bat_number) END) AS pa,
                       SUM(CASE WHEN events = 'single' THEN 1 ELSE 0 END) AS s1,
                       SUM(CASE WHEN events = 'double' THEN 1 ELSE 0 END) AS s2,
                       SUM(CASE WHEN events = 'triple' THEN 1 ELSE 0 END) AS s3,
                       SUM(CASE WHEN events = 'home_run' THEN 1 ELSE 0 END) AS hr,
                       SUM(CASE WHEN events IN ('walk','intent_walk') THEN 1 ELSE 0 END) AS bb,  -- all walks; ibb split out
                       SUM(CASE WHEN events = 'intent_walk' THEN 1 ELSE 0 END) AS ibb,
                       SUM(CASE WHEN events = 'hit_by_pitch' THEN 1 ELSE 0 END) AS hbp,
                       SUM(CASE WHEN events IN ('sac_fly','sac_fly_double_play') THEN 1 ELSE 0 END) AS sf,
                       SUM(CASE WHEN events = 'sac_bunt' THEN 1 ELSE 0 END) AS sh,
                       SUM(CASE WHEN events = 'catcher_interf' THEN 1 ELSE 0 END) AS ci,
                       SUM(CASE WHEN events IN ('strikeout','strikeout_double_play') THEN 1 ELSE 0 END) AS k,
                       AVG(launch_speed) FILTER (WHERE bb_type IS NOT NULL AND des NOT ILIKE '%bunt%') AS avg_ev
                FROM pitches_all
                WHERE game_type = 'R' AND season IN ({season_list}) AND batter IS NOT NULL
                  AND description IS NOT NULL {HITTER_GATE}
                GROUP BY 1, 2
            """).df()
            out = {}
            for r in q.itertuples():
                if r.grp is None or (isinstance(r.grp, float) and r.grp != r.grp):
                    continue  # unmapped group (null pitch_type) — not a cell
                ab = r.pa - r.bb - r.hbp - r.sf - r.sh - r.ci
                den = ab + (r.bb - r.ibb) + r.hbp + r.sf
                raw = (woba[r.season]["walk"] * (r.bb - r.ibb) + woba[r.season]["hit_by_pitch"] * r.hbp
                       + woba[r.season]["single"] * r.s1 + woba[r.season]["double"] * r.s2
                       + woba[r.season]["triple"] * r.s3 + woba[r.season]["home_run"] * r.hr) if r.season in woba else 0.0
                tb = r.s1 + 2 * r.s2 + 3 * r.s3 + 4 * r.hr
                out[str(int(r.season))] = out.get(str(int(r.season)), {})
                out[str(int(r.season))][label_of(r.grp)] = {
                    "pa": int(r.pa),
                    "avg": f((r.s1 + r.s2 + r.s3 + r.hr) / ab, 3) if ab else None,
                    "obp": f((r.s1 + r.s2 + r.s3 + r.hr + r.bb + r.hbp) / (ab + r.bb + r.hbp + r.sf), 3) if (ab + r.bb + r.hbp + r.sf) else None,
                    "slg": f(tb / ab, 3) if ab else None,
                    "woba": f(raw / den * hfactor.get(r.season, 1.0), 3) if den and r.season in woba else None,
                    "kPct": f(100 * r.k / r.pa, 1) if r.pa else None,
                    "bbPct": f(100 * r.bb / r.pa, 1) if r.pa else None,
                    "avgEv": f(r.avg_ev, 1),
                }
            return out

        def label_of(grp):
            return grp

        bm_hand = league_splits("p_throws")
        bm_fam = league_splits(FAM_SQL.replace("CASE pitch_type", "CASE pitch_type", 1))

        # per-type league rates for the faced table (same measures, league-wide)
        bm_type_q = con.sql(f"""
            SELECT season, {site_case_sql()} AS site,
                   COUNT(DISTINCT CASE WHEN events IS NOT NULL AND events <> 'truncated_pa' THEN (game_pk, at_bat_number) END) AS pa,
                   COUNT(*) AS n,
                   SUM(CASE WHEN description IN {SWING} THEN 1 ELSE 0 END) AS swings,
                   SUM(CASE WHEN description IN ('swinging_strike','swinging_strike_blocked','foul_tip') THEN 1 ELSE 0 END) AS whiffs,
                   SUM(CASE WHEN bb_type IS NOT NULL THEN 1 ELSE 0 END) AS bip,
                   SUM(CASE WHEN bb_type IS NOT NULL AND launch_speed >= 95 THEN 1 ELSE 0 END) AS hard,
                   AVG(launch_speed) FILTER (WHERE bb_type IS NOT NULL AND des NOT ILIKE '%bunt%') AS avg_ev
            FROM pitches_all
            WHERE game_type = 'R' AND season IN ({season_list}) AND batter IS NOT NULL
              AND description IS NOT NULL {HITTER_GATE}
            GROUP BY 1, 2
        """).df()
        bm_types: dict = {}
        for t in bm_type_q.itertuples():
            if t.site is None or (isinstance(t.site, float) and t.site != t.site):
                continue
            ssn = str(int(t.season))
            bm_types.setdefault(ssn, {})[t.site] = {
                "n": int(t.n), "pa": int(t.pa),
                "swingPct": f(100 * t.swings / t.n, 1) if t.n else None,
                "whiffPct": f(100 * t.whiffs / t.swings, 1) if t.swings else None,
                "hardPct": f(100 * t.hard / t.bip, 1) if t.bip else None,
                "avgEv": f(t.avg_ev, 1),
            }
        jwrite(out / "benchmarks" / "hitter_splits.json",
               {"_comment": "league per-split-cell lines over the 50+ PA population; join the Splits tab",
                "hand": bm_hand, "family": bm_fam, "type": bm_types}, sort_keys=True)
        counts["hitter_split_benchmarks"] = 1

        # The hitter's own "arsenal faced": one row per Statcast type he saw,
        # the finer cut under the FB/CT/BR/OS family splits. Powers the
        # profile's pitches-faced table (both levels).
        faced_q = con.sql(f"""
            SELECT batter AS id, season, {site_case_sql()} AS site,
                   COUNT(DISTINCT (game_pk, at_bat_number)) AS pa,
                   COUNT(*) AS n,
                   SUM(CASE WHEN description IN {SWING} THEN 1 ELSE 0 END) AS swings,
                   SUM(CASE WHEN description IN ('swinging_strike','swinging_strike_blocked','foul_tip') THEN 1 ELSE 0 END) AS whiffs,
                   SUM(CASE WHEN bb_type IS NOT NULL THEN 1 ELSE 0 END) AS bip,
                   SUM(CASE WHEN bb_type IS NOT NULL AND launch_speed >= 95 THEN 1 ELSE 0 END) AS hard,
                   AVG(launch_speed) FILTER (WHERE bb_type IS NOT NULL AND des NOT ILIKE '%bunt%') AS avg_ev
            FROM pitches_all
            WHERE game_type = 'R' AND season IN ({season_list}) AND batter IS NOT NULL
              AND stand IN ('L','R') AND p_throws IN ('L','R')
              AND description IS NOT NULL
            GROUP BY 1, 2, 3
        """).df()
        faced_by = {}
        for t in faced_q.itertuples():
            faced_by.setdefault((int(t.id), int(t.season)), []).append({
                "t": t.site, "n": int(t.n), "pa": int(t.pa),
                "swingPct": f(100 * t.swings / t.n, 1) if t.n else None,
                "whiffPct": f(100 * t.whiffs / t.swings, 1) if t.swings else None,
                "hardPct": f(100 * t.hard / t.bip, 1) if t.bip else None,
                "avgEv": f(t.avg_ev, 1),
            })

        # per-season docs + index
        hag_i = hag.set_index(["id", "season"])
        h_written_pairs = set()
        h_written_latest = set()
        h_latest = {}
        pairs = sorted({(int(rr.id), int(rr.season)) for rr in hboard_df.itertuples()})
        for pid in {p for p, _ in pairs}:
            h_latest[pid] = max(s for p2, s in pairs if p2 == pid)
        for pid, season in pairs:
            if player is not None and pid != player:
                continue
            t = hag_i.loc[(pid, season)]
            wt = woba.get(season, {})
            ab = t.pa - t.bb - t.hbp - t.sf - t.sh - t.ci
            tb = t.s1 + 2 * t.s2 + 3 * t.s3 + 4 * t.hr
            den = ab + (t.bb - t.ibb) + t.hbp + t.sf
            raw = (wt["walk"] * (t.bb - t.ibb) + wt["hit_by_pitch"] * t.hbp
                   + wt["single"] * t.s1 + wt["double"] * t.s2
                   + wt["triple"] * t.s3 + wt["home_run"] * t.hr) if wt else None
            obp_den = ab + t.bb + t.hbp + t.sf
            doc = {
                "id": str(pid), "name": h_names.get(pid), "position": "H", "age": season_age(pid, season),
                "team": hteam_map.get((pid, season)), "teams": team_stints_h.get((pid, season)),
                "teamSplits": h_team_lines.get((pid, season)),
                "bats": bats_map.get((pid, season)),
                "season": season,
                "pa": int(t.pa), "pitchesSeen": int(t.pitches_seen),
                "avg": f((t.s1 + t.s2 + t.s3 + t.hr) / ab, 3) if ab else None,
                "obp": f((t.s1 + t.s2 + t.s3 + t.hr + t.bb + t.hbp) / obp_den, 3) if obp_den else None,
                "slg": f(tb / ab, 3) if ab else None,
                "woba": f(raw / den * hfactor.get(season, 1.0), 3) if raw is not None and den else None,
                "kPct": f(100 * t.k / t.pa, 1) if t.pa else None,
                "bbPct": f(100 * t.bb / t.pa, 1) if t.pa else None,
                "swingPct": f(100 * t.swings / t.pitches_seen, 1) if t.pitches_seen else None,
                "zSwingPct": f(100 * t.n_zone_swing / t.n_zone, 1) if t.n_zone else None,
                "oSwingPct": f(100 * t.n_ooz_swing / t.n_ooz, 1) if t.n_ooz else None,
                "contactPct": f(100 * (t.swings - t.whiffs) / t.swings, 1) if t.swings else None,
                "zContactPct": f(100 * (t.n_zone_swing - t.n_zone_whiff) / t.n_zone_swing, 1) if t.n_zone_swing else None,
                "oContactPct": f(100 * (t.n_ooz_swing - (t.whiffs - t.n_zone_whiff)) / t.n_ooz_swing, 1) if t.n_ooz_swing else None,
                "whiffPct": f(100 * t.whiffs / t.swings, 1) if t.swings else None,
                "swStrPct": f(100 * t.whiffs / t.pitches_seen, 1) if t.pitches_seen else None,
                "firstPitchSwingPct": f(100 * t.n_fpswing / t.n_firstpitch, 1) if t.n_firstpitch else None,
                "twoKChasePct": f(100 * t.n_2k_ooz_swing / t.n_2k_ooz, 1) if t.n_2k_ooz else None,
                "zonePctSeen": f(100 * t.n_zone / t.pitches_seen, 1) if t.pitches_seen else None,
                "avgEv": f(t.avg_ev, 1), "avgLa": f(t.avg_la, 1),
                "ev90": f(t.ev90, 1), "maxEv": f(t.maxev, 1),
                "hardHitPct": f(100 * t.n_hard / t.bip, 1) if t.bip else None,
                "barrelPct": f(100 * t.n_barrel / t.bip, 1) if t.bip else None,
                "nBip": int(t.bip),
                "gbPct": f(100 * t.gb / t.bip, 1) if t.bip else None,
                "fbPct": f(100 * t.fb / t.bip, 1) if t.bip else None,
                "ldPct": f(100 * t.ld / t.bip, 1) if t.bip else None,
                "puPct": f(100 * t.pu / t.bip, 1) if t.bip else None,
                "vsHand": vs_hand.get((pid, season)),
                "vsFamily": vs_fam.get((pid, season)),
                "faced": sorted(faced_by.get((pid, season), []), key=lambda x: -x["n"]),
                **h_depth.get((pid, season), {}),
                "trend": h_trend.get((pid, season)),
                **h_proj.get((pid, season), {}),
                **h_dec.get((pid, season), {}),
                **h_fld.get((pid, season), {}),
                "percentiles": {},
                **h_shrunk(t, season),
            }
            if season == h_latest[pid]:
                jwrite(out / "hitters" / f"{pid}.json", doc, sort_keys=True)
                h_written_latest.add(pid)
            jwrite(out / "hitters" / f"{pid}-{season}.json", doc, sort_keys=True)
            h_written_pairs.add((pid, season))
        # index + prune
        if player is None:
            h_index = {str(pid): {"n": h_names.get(pid), "t": "H", "tm": hteam_map.get((pid, h_latest[pid])),
                                  "pa": next((int(rr.pa) for rr in hboard_df.itertuples()
                                              if int(rr.id) == pid and rr.season == h_latest[pid]), None),
                                  "season": h_latest[pid]}
                       for pid in h_latest}
            # merge into player_index if it exists in this run; otherwise leave a sidecar merge to the pitchers family
            pi_path = out / "player_index.json"
            pi = json.loads(pi_path.read_text()) if pi_path.exists() else {}
            pi.update(h_index)
            jwrite(pi_path, pi, sort_keys=True)
            pruned = 0
            for p2 in (out / "hitters").glob("*.json"):
                stem = p2.stem
                if "-" in stem:
                    pid_s, s0 = stem.rsplit("-", 1)
                    if s0.isdigit() and int(s0) in seasons and (int(pid_s), int(s0)) not in h_written_pairs:
                        p2.unlink()
                        pruned += 1
                elif int(stem) not in h_written_latest:
                    p2.unlink()
                    pruned += 1
            print(f"hitters: {len(pairs)} season files; pruned {pruned} stale; index now {len(pi)} players")
        counts["hitter_rows"] = counts_board
        counts["hitter_files"] = len(pairs)

        # shrunk populations for the profile panels: pct5 of each twin across the
        # season's 50+ PA hitters — a shrunk value ranks against its own kind
        h_shrunk_pcts = {}
        for s in seasons:
            sub = hboard_df[hboard_df["season"] == s]
            pcts = {}
            for key in H_DISC_SHRINK:
                p5 = pct5(sub[f"{key}Shrunk"]) if f"{key}Shrunk" in sub.columns else None
                if p5:
                    pcts[key] = p5
            h_shrunk_pcts[str(s)] = pcts

        # Staged, not written: the pitchers family rewrites percentiles.json in the
        # final write-rest block, which would clobber the hitters section. The merge
        # happens at the very end of the bake (hitter_pct_out).
        hitter_pct_out = {"hitters": {"by_season": h_pcts, "pooled": {}}, "hitters_dense": h_dense,
                          "shrunk_by_season": h_shrunk_pcts}
        if player is None:
            jwrite(out / "hitters.json", hboard_df.to_dict(orient="records"))

    # ------------------------------------------------ per-player detail (2c)
    # Game logs (both sides) and the hitter spray chart: per-player files,
    # gzipped, descriptive. The populations mirror the boards: pitchers = the
    # graded, kept pitcher-seasons; hitters = the 50+ PA seasons.
    if "detail" in fams and tot_indexed is not None:
        # ---- pitchers: per-game lines; runs while he pitched (batting side's score
        # change on each of his pitches), RE24-style, as the board's fallback.
        pg = con.sql(f"""
            WITH pp AS (
              SELECT game_pk, game_date, season, inning_topbot, at_bat_number, pitcher, events, description,
                     home_team, away_team, post_bat_score - bat_score AS runs_p
              FROM pitches_all
              WHERE game_type = 'R' AND season IN ({season_list}) AND pitcher IS NOT NULL
                {DETAIL_GATE}
            ),
            scored AS (
              SELECT game_pk, inning_topbot, at_bat_number, pitcher, season, runs_p AS runs_pa
              FROM pp
            ),
            g AS (
              SELECT pitcher AS id, season, game_pk, MAX(game_date) AS game_date,
                     COUNT(*) AS pitches,
                     COUNT(DISTINCT at_bat_number) AS pa,
                     SUM(CASE WHEN description IN {TAKEN} THEN 1 ELSE 0 END) AS taken,
                     SUM(CASE WHEN events IN ('strikeout','strikeout_double_play') THEN 1 ELSE 0 END) AS k,
                     SUM(CASE WHEN events IN ('walk','intent_walk') THEN 1 ELSE 0 END) AS bb,
                     SUM(CASE WHEN events IN {BB_EVENTS} THEN 1 ELSE 0 END) AS h,
                     SUM(CASE WHEN events = 'home_run' THEN 1 ELSE 0 END) AS hr,
                     SUM(CASE WHEN events IN {OUT_EVENTS_1} THEN 1 ELSE 0 END
                          + CASE WHEN events IN {OUT_EVENTS_2} THEN 2 ELSE 0 END
                          + CASE WHEN events IN {OUT_EVENTS_3} THEN 3 ELSE 0 END) AS outs,
                     mode(CASE WHEN inning_topbot = 'Top' THEN home_team ELSE away_team END) AS team,
                     mode(CASE WHEN inning_topbot = 'Top' THEN away_team ELSE home_team END) AS opp
              FROM pp GROUP BY 1, 2, 3
            )
            SELECT g.*, COALESCE(r.runs, 0) AS runs
            FROM g LEFT JOIN (SELECT game_pk, pitcher, season, SUM(runs_pa) AS runs
                              FROM scored GROUP BY 1, 2, 3) r
                   ON r.game_pk = g.game_pk AND r.pitcher = g.id AND r.season = g.season
            ORDER BY g.id, g.season, g.game_date, g.game_pk
        """).df()
        pitcher_pop = {(pid, s) for (pid, s) in g.index if keep_row(int(pid), int(s)) and (pid, s) in tot_indexed.index}
        gl_by_player = {}
        for row in pg.itertuples():
            key = (int(row.id), int(row.season))
            if key not in pitcher_pop:
                continue
            ip = row.outs / 3
            gl_by_player.setdefault(key, []).append({
                "d": str(row.game_date), "o": row.opp, "ip": f(ip, 1),
                "h": int(row.h), "r": int(row.runs), "bb": int(row.bb), "k": int(row.k),
                "hr": int(row.hr), "bf": int(row.pa), "pc": int(row.pitches),
                "g": int(row.game_pk),  # joins the pa_log file
            })
        n_gl = 0
        for (pid, season), games in gl_by_player.items():
            jwrite_gz(out / "gamelog" / f"{pid}-{season}.json.gz", {
                "id": str(pid), "side": "P", "season": season,
                "games": sorted(games, key=lambda x: (x["d"],)),
            }, sort_keys=True)
            n_gl += 1
        counts["pitcher_gamelog_files"] = n_gl
        print(f"pitcher gamelog files: {n_gl}")

        # ---- hitters: per-game lines for the 50+ PA seasons
        hpop = con.sql(f"""
            SELECT batter AS id, season
            FROM pitches_all
            WHERE game_type = 'R' AND season IN ({season_list}) AND batter IS NOT NULL
              AND stand IN ('L','R') AND p_throws IN ('L','R')
            GROUP BY 1, 2
            HAVING COUNT(DISTINCT (game_pk, at_bat_number)) >= 50
        """).df()
        h_pop = {(int(rr.id), int(rr.season)) for rr in hpop.itertuples()}
        hg = con.sql(f"""
            SELECT batter AS id, season, game_pk, MAX(game_date) AS game_date,
                   COUNT(DISTINCT (game_pk, at_bat_number)) AS pa,
                   SUM(CASE WHEN description IN {SWING} THEN 1 ELSE 0 END) AS swings,
                   SUM(CASE WHEN description IN ('swinging_strike','swinging_strike_blocked','foul_tip') THEN 1 ELSE 0 END) AS whiffs,
                   SUM(CASE WHEN events IN ('single','double','triple','home_run') THEN 1 ELSE 0 END) AS h,
                   SUM(CASE WHEN events = 'home_run' THEN 1 ELSE 0 END) AS hr,
                   SUM(CASE WHEN events IN ('walk','intent_walk') THEN 1 ELSE 0 END) AS bb,
                   SUM(CASE WHEN events IN ('strikeout','strikeout_double_play') THEN 1 ELSE 0 END) AS k,
                   SUM(CASE WHEN bb_type IS NOT NULL THEN 1 ELSE 0 END) AS bip,
                   SUM(CASE WHEN bb_type IS NOT NULL AND launch_speed >= 95 THEN 1 ELSE 0 END) AS n_hard,
                   AVG(launch_speed) FILTER (WHERE bb_type IS NOT NULL AND des NOT ILIKE '%bunt%') AS avg_ev,
                   MAX(launch_speed) FILTER (WHERE bb_type IS NOT NULL) AS max_ev,
                   mode(CASE WHEN inning_topbot = 'Top' THEN away_team ELSE home_team END) AS team,
                   mode(CASE WHEN inning_topbot = 'Top' THEN home_team ELSE away_team END) AS opp
            FROM pitches_all
            WHERE game_type = 'R' AND season IN ({season_list}) AND batter IS NOT NULL
              AND stand IN ('L','R') AND p_throws IN ('L','R')
            GROUP BY 1, 2, 3
            ORDER BY id, season, game_date, game_pk
        """).df()
        hgl = {}
        for row in hg.itertuples():
            key = (int(row.id), int(row.season))
            if key not in h_pop:
                continue
            hgl.setdefault(key, []).append({
                "d": str(row.game_date), "o": row.opp, "pa": int(row.pa),
                "h": int(row.h), "hr": int(row.hr), "bb": int(row.bb), "k": int(row.k),
                "ev": f(row.avg_ev, 1), "hh": int(row.n_hard),
                "g": int(row.game_pk),  # joins the pa_log file
            })
        n_hgl = 0
        for (pid, season), games in hgl.items():
            jwrite_gz(out / "gamelog" / f"{pid}-{season}.json.gz", {
                "id": str(pid), "side": "H", "season": season,
                "games": sorted(games, key=lambda x: (x["d"],)),
            }, sort_keys=True)
            n_hgl += 1
        counts["hitter_gamelog_files"] = n_hgl
        print(f"hitter gamelog files: {n_hgl}")

        # ---- ticker (R6): the league's latest day, its best lines, and the
        # season's biggest Whiff+ movers. Measured lines; the movers are a
        # descriptive model change, labelled as one.
        latest_date = str(pg["game_date"].max())[:10] if len(pg) else None
        p_names = {int(rr.mlbam): rr.name for rr in grades[["mlbam", "name"]].drop_duplicates("mlbam").itertuples()
                   if rr.name}
        starts = []
        if latest_date:
            day = pg[pg["game_date"].astype(str).str.startswith(latest_date)]
            for t in day.itertuples():
                if (int(t.id), int(t.season)) not in pitcher_pop:
                    continue
                starts.append({"id": str(int(t.id)), "n": p_names.get(int(t.id)), "season": int(t.season),
                               "d": str(t.game_date)[:10], "ip": f(t.outs / 3, 1), "k": int(t.k),
                               "h": int(t.h), "r": int(t.runs), "bf": int(t.pa)})
            starts.sort(key=lambda x: (-x["k"], -float(x["ip"])))
        hday = []
        h_names = {int(r["id"]): r.get("name") for r in hboard}
        if latest_date:
            day = hg[hg["game_date"].astype(str).str.startswith(latest_date)]
            for t in day.itertuples():
                if (int(t.id), int(t.season)) not in h_pop:
                    continue
                hday.append({"id": str(int(t.id)), "n": h_names.get(int(t.id)), "season": int(t.season), "d": str(t.game_date)[:10],
                             "pa": int(t.pa), "h": int(t.h), "hr": int(t.hr), "bb": int(t.bb), "k": int(t.k)})
            hday.sort(key=lambda x: (-x["hr"], -x["h"], x["k"]))
        # movers: Whiff+ season over season, 300+ graded pitches both seasons
        movers = []
        if not grades.empty and grades["season"].nunique() > 1:
            latest_season = int(grades["season"].max())
            prev = grades[grades["season"] == latest_season - 1]
            cur = grades[grades["season"] == latest_season]
            pm = {int(rr.mlbam): (float(rr.grade), int(rr.pitches_graded or 0), getattr(rr, "name", None)) for rr in prev.itertuples()}
            for t in cur.itertuples():
                p = pm.get(int(t.mlbam))
                if not p or (p[1] < 300) or int(t.pitches_graded or 0) < 300:
                    continue
                movers.append({"id": str(int(t.mlbam)), "n": getattr(t, "name", None) or p[2],
                               "from": round(p[0], 1), "to": round(float(t.grade), 1),
                               "delta": round(float(t.grade) - p[0], 1)})
            movers.sort(key=lambda x: -abs(x["delta"]))
        jwrite(out / "ticker.json", {
            "date": latest_date,
            "starts": starts[:8], "hitting": hday[:8],
            "moversUp": [m for m in movers if m["delta"] > 0][:6],
            "moversDown": [m for m in movers if m["delta"] < 0][:6],
        }, sort_keys=True)
        counts["ticker"] = 1

        # ---- per-PA pitch sequences (both sides, one pass): the ordered pitch
        # list under every plate appearance, keyed by game_pk so the game-log
        # rows (their `g` field) can expand into what actually happened.
        # Deliberately UNGATED: this is a recollection surface, so a game shows
        # every recorded pitch and no PA silently vanishes between the game
        # line and the table (the quality gates would drop whole PAs — 20 of
        # Judge's 704 in 2024). Raw sequence only — type, velocity and a
        # one-letter result (coded in SQL below); no location values.
        PA_EVENT_CODE = {
            "strikeout": "K", "strikeout_double_play": "KD",
            "walk": "BB", "intentional_walk": "IBB", "intent_walk": "IBB",
            "hit_by_pitch": "HBP",
            "single": "1B", "double": "2B", "triple": "3B", "home_run": "HR",
            "field_out": "FO", "force_out": "FO", "other_out": "FO",
            "grounded_into_double_play": "GDP", "double_play": "DP",
            "grounded_into_triple_play": "GTP", "triple_play": "TP",
            "fielders_choice": "FC", "fielders_choice_out": "FC",
            "field_error": "E",
            "sac_fly": "SF", "sac_fly_double_play": "SF",
            "sac_bunt": "SH", "sac_bunt_double_play": "SH",
            "catcher_interf": "CI", "batter_interference": "CI", "defensive_interf": "CI",
            "fan_interference": "FI", "obstruction": "OB",
            "passed_ball": "PB", "wild_pitch": "WP",
        }
        for k in ("caught_stealing_2b", "caught_stealing_3b", "caught_stealing_home"):
            PA_EVENT_CODE[k] = "CS"
        for k in ("pickoff_1b", "pickoff_2b", "pickoff_3b"):
            PA_EVENT_CODE[k] = "PK"
        for k in ("pickoff_caught_stealing_1b", "pickoff_caught_stealing_2b", "pickoff_caught_stealing_3b"):
            PA_EVENT_CODE[k] = "PCS"

        pl = con.sql(f"""
            SELECT game_pk, season, MAX(game_date) AS game_date,
                   arg_min(inning, pitch_number) AS inn,
                   arg_min(inning_topbot, pitch_number) AS tb,
                   arg_min(outs_when_up, pitch_number) AS outs,
                   arg_min(on_1b, pitch_number) AS on_1b,
                   arg_min(on_2b, pitch_number) AS on_2b,
                   arg_min(on_3b, pitch_number) AS on_3b,
                   arg_max(post_home_score, pitch_number) AS sc_h,
                   arg_max(post_away_score, pitch_number) AS sc_a,
                   MAX(home_team) AS home, MAX(away_team) AS away,
                   arg_max(events, pitch_number) AS ev,
                   MAX(pitcher) AS pitcher, MAX(batter) AS batter,
                   list(struct_pack(t := pitch_type, v := ROUND(release_speed, 1),
                                    c := CASE description
                                        WHEN 'ball' THEN 'B' WHEN 'intent_ball' THEN 'B' WHEN 'automatic_ball' THEN 'B'
                                        WHEN 'pitchout' THEN 'B' WHEN 'blocked_ball' THEN 'B'
                                        WHEN 'called_strike' THEN 'C'
                                        WHEN 'swinging_strike' THEN 'S' WHEN 'swinging_strike_blocked' THEN 'S'
                                        WHEN 'swinging_pitchout' THEN 'S'
                                        WHEN 'foul_tip' THEN 'T' WHEN 'bunt_foul_tip' THEN 'T'
                                        WHEN 'foul' THEN 'F' WHEN 'foul_bunt' THEN 'F'
                                        WHEN 'missed_bunt' THEN 'M'
                                        WHEN 'hit_by_pitch' THEN 'P'
                                        WHEN 'hit_into_play' THEN 'X'
                                        ELSE '?' END) ORDER BY pitch_number) AS pitches
            FROM pitches_all
            WHERE game_type = 'R' AND season IN ({season_list}) AND pitcher IS NOT NULL AND batter IS NOT NULL
            GROUP BY game_pk, season, at_bat_number
            ORDER BY game_pk, at_bat_number
        """).df()
        # The first pitch's pre-state (arg_min over pitch_number) is the
        # situation the PA started in; the last pitch's event ends it. The same
        # PA object serves both the pitcher's file and the batter's — the opp
        # differs by side (who he was facing).
        pal_p: dict = {}
        pal_h: dict = {}
        games_pas: dict = {}
        for t in pl.itertuples():
            pa = {
                "i": int(t.inn), "h": "t" if t.tb == "Top" else "b", "o": int(t.outs),
                "b": ((0 if pd.isna(t.on_1b) else 1) + (0 if pd.isna(t.on_2b) else 2)
                      + (0 if pd.isna(t.on_3b) else 4)),
                "s": [int(t.sc_h), int(t.sc_a)],
                "r": PA_EVENT_CODE.get(t.ev, "?") if t.ev else "?",
                "p": [[e["t"], e["v"], e["c"]] for e in t.pitches],
            }
            season, pitcher, batter = int(t.season), int(t.pitcher), int(t.batter)
            gp_games = games_pas.setdefault(int(t.game_pk), {"d": str(t.game_date), "home": t.home, "away": t.away, "pas": []})
            gp_games["pas"].append({**pa, "bt": batter, "pt": pitcher})
            bat_team = t.away if t.tb == "Top" else t.home
            fld_team = t.home if t.tb == "Top" else t.away
            gp = pal_p.setdefault((pitcher, season), {})
            gp.setdefault(int(t.game_pk), {"d": str(t.game_date), "o": bat_team, "pas": []})["pas"].append(pa)
            gh = pal_h.setdefault((batter, season), {})
            gh.setdefault(int(t.game_pk), {"d": str(t.game_date), "o": fld_team, "pas": []})["pas"].append(pa)
        n_pal = 0
        for (pid, season), games in pal_p.items():
            if (pid, season) not in pitcher_pop:
                continue
            jwrite_gz(out / "pa_log" / f"{pid}-{season}.json.gz", {
                "id": str(pid), "side": "P", "season": season,
                "games": [{"k": int(k), **g} for k, g in
                          sorted(games.items(), key=lambda kv: (kv[1]["d"], kv[0]))],
            }, sort_keys=True)
            n_pal += 1
        counts["pitcher_pa_log_files"] = n_pal
        for (pid, season), games in pal_h.items():
            if (pid, season) not in h_pop:
                continue
            jwrite_gz(out / "pa_log" / f"{pid}-{season}.json.gz", {
                "id": str(pid), "side": "H", "season": season,
                "games": [{"k": int(k), **g} for k, g in
                          sorted(games.items(), key=lambda kv: (kv[1]["d"], kv[0]))],
            }, sort_keys=True)
            n_pal += 1
        counts["pa_log_files"] = n_pal
        print(f"pa_log files (both sides): {n_pal}")

        # ---- game reports (R2): one file per game — both teams' pitching and
        # hitting lines (the same RE24-style runs the game logs carry) plus the
        # full PA table with sequences. A record of the game, ungated like the
        # PA pass: excluded pitchers still appear, because a box score without
        # the closer is not a box score.
        h_names = None
        if level == "aaa":
            h_names = milb_names("hitters")
        else:
            rq = con.sql(f"""
                SELECT DISTINCT person_id AS id, full_name AS name
                FROM read_parquet('{MART_DIR}/data/daily/rosters_*.parquet')
                WHERE full_name IS NOT NULL
            """).df()
            h_names = {int(t.id): t.name for t in rq.itertuples()}
        plines: dict = {}
        for t in pg.itertuples():
            plines.setdefault(int(t.game_pk), []).append({
                "id": str(int(t.id)), "n": p_names.get(int(t.id)), "tm": t.team,
                "ip": f(t.outs / 3, 1), "h": int(t.h), "r": int(t.runs), "bb": int(t.bb),
                "k": int(t.k), "hr": int(t.hr), "bf": int(t.pa), "pc": int(t.pitches),
            })
        hlines: dict = {}
        for t in hg.itertuples():
            hlines.setdefault(int(t.game_pk), []).append({
                "id": str(int(t.id)), "n": h_names.get(int(t.id), str(int(t.id))), "tm": t.team,
                "pa": int(t.pa), "h": int(t.h), "hr": int(t.hr), "bb": int(t.bb), "k": int(t.k),
                "ev": f(t.avg_ev, 1),
            })
        n_games = 0
        recent_games = []
        for gpk, gmeta in games_pas.items():
            pas = gmeta["pas"]
            if not pas:
                continue
            # final score: the last PA's post state; home runs in the ninth count
            final = pas[-1]["s"] if pas else [0, 0]
            jwrite_gz(out / "games" / f"{gpk}.json.gz", {
                "g": int(gpk), "d": gmeta["d"], "home": gmeta["home"], "away": gmeta["away"],
                "final": final,
                "p": sorted(plines.get(gpk, []), key=lambda x: -float(x["ip"])),
                "b": sorted(hlines.get(gpk, []), key=lambda x: (-x["pa"],)),
                "pas": pas,
            }, sort_keys=True)
            recent_games.append({"g": int(gpk), "d": gmeta["d"], "home": gmeta["home"],
                                 "away": gmeta["away"], "final": final})
            n_games += 1
        recent_games.sort(key=lambda x: (x["d"], x["g"]), reverse=True)
        jwrite(out / "recent_games.json", {"games": recent_games[:20]}, sort_keys=True)
        counts["game_report_files"] = n_games
        print(f"game report files: {n_games}")

        # ---- hitter spray (PH3 raw): per-BIP balls with position, EV, LA, result.
        # Value overlays (xwOBA) are NEEDS-MODEL and stay out. League refs per
        # season x batter-hand: mean/SD of the spray angle, so the panel can
        # draw where his hand's average tendency sits.
        # Raw hc_x/hc_y are sensor units, not feet. The standard Statcast spray
        # transform centres them (x - 125.42, 198.27 - y) so y runs toward centre
        # field; the angle's sign then checks against the pull facts: RHH home
        # runs land negative (third-base side), LHH positive (first-base side).
        sp = con.sql(f"""
            SELECT batter AS id, season, stand,
                   ROUND(hc_x - 125.42, 1) AS x, ROUND(198.27 - hc_y, 1) AS y,
                   ROUND(launch_speed, 1) AS ev, ROUND(launch_angle, 1) AS la,
                   events, bb_type, substr(CAST(game_date AS VARCHAR), 6, 5) AS d
            FROM pitches_all
            WHERE game_type = 'R' AND season IN ({season_list}) AND batter IS NOT NULL
              AND hc_x IS NOT NULL AND hc_y IS NOT NULL
              AND stand IN ('L','R') AND p_throws IN ('L','R')
            -- chronological (the season replay animates in this order); ties broken deterministically
            ORDER BY id, season, game_date, game_pk, at_bat_number, pitch_number
        """).df()
        sp["ang"] = [
            round(math.degrees(math.atan2(x, y)), 1) if y else None
            for x, y in zip(sp["x"], sp["y"])
        ]
        refs_pool = sp.dropna(subset=["ang"]).groupby(["season", "stand"])["ang"].agg(["mean", "std", "count"])
        refs = {f"{int(s)}|{st}": {"mean": f(row["mean"], 1), "sd": f(row["std"], 1), "n": int(row["count"])}
                for (s, st), row in refs_pool.iterrows()}
        jwrite(out / "spray_refs.json", {
            "comment": "League spray angle (deg from centre field, negative toward the third-base side) per season x batter hand, over all balls in play.",
            "refs": refs,
        }, sort_keys=True)
        sp_by = {}
        for row in sp.itertuples():
            key = (int(row.id), int(row.season))
            if key not in h_pop:
                continue
            sp_by.setdefault(key, []).append({
                "x": row.x, "y": row.y, "ev": row.ev, "la": row.la,
                "e": row.events, "t": row.bb_type, "s": row.stand,  # side he batted from (switch hitters)
                "d": row.d,  # game date MM-DD; balls are in chronological order
            })
        n_sp = 0
        for (pid, season), balls in sp_by.items():
            jwrite_gz(out / "spray" / f"{pid}-{season}.json.gz", {
                "id": str(pid), "season": season,
                "n": len(balls), "balls": balls,
            }, sort_keys=True)
            n_sp += 1
        counts["spray_files"] = n_sp
        print(f"spray files: {n_sp}; refs {len(refs)} season-hand cells")

    # ------------------------------------------- hitter scouting card (H10) + skill grades (H9)
    # Where he swings, what happens there, and what he does in each count —
    # plus descriptive 20-80 estimates and a hitter type off the season
    # percentiles. All measured; the grades are labelled estimates, never a
    # model. Cells mirror plate_x by the BATTER's hand so "inside" is his
    # inside; values under 5 pitches are the panel's job to thin-mark — the
    # bake ships every cell with its n.
    print(f"[{time.time() - t0:.0f}s] scouting", flush=True)  # per-family timing
    if "scouting" in fams:
        from statistics import NormalDist
        hpop2 = con.sql(f"""
            SELECT batter AS id, season
            FROM pitches_all
            WHERE game_type = 'R' AND season IN ({season_list}) AND batter IS NOT NULL
              AND stand IN ('L','R') AND p_throws IN ('L','R')
            GROUP BY 1, 2
            HAVING COUNT(DISTINCT (game_pk, at_bat_number)) >= 50
        """).df()
        sc_pop = {(int(rr.id), int(rr.season)) for rr in hpop2.itertuples()}

        # season populations for the three skill axes (self-contained: this
        # family must bake alone, without the hitters block's tables)
        sk = con.sql(f"""
            SELECT batter AS id, season,
                   COUNT(DISTINCT (game_pk, at_bat_number)) AS pa,
                   COUNT(*) AS seen,
                   SUM(CASE WHEN description IN ('swinging_strike','swinging_strike_blocked','foul_tip') THEN 1 ELSE 0 END) AS whiffs,
                   SUM(CASE WHEN description IN {SWING} THEN 1 ELSE 0 END) AS swings,
                   SUM(CASE WHEN zone BETWEEN 10 AND 14 AND description IN {SWING} THEN 1 ELSE 0 END) AS chase,
                   SUM(CASE WHEN zone BETWEEN 10 AND 14 THEN 1 ELSE 0 END) AS ooz,
                   SUM(CASE WHEN bb_type IS NOT NULL THEN 1 ELSE 0 END) AS bip,
                   SUM(CASE WHEN launch_speed_angle = 6 AND bb_type IS NOT NULL THEN 1 ELSE 0 END) AS barrels  -- was EV >= 95 (hard-hit)
            FROM pitches_all
            WHERE game_type = 'R' AND season IN ({season_list}) AND batter IS NOT NULL
              AND stand IN ('L','R') AND p_throws IN ('L','R')
              AND description IS NOT NULL
            GROUP BY 1, 2
            HAVING COUNT(DISTINCT (game_pk, at_bat_number)) >= 50
        """).df()
        sk["swingPct"] = 100 * sk["swings"] / sk["seen"].clip(lower=1)
        sk["barrelPct"] = 100 * sk["barrels"] / sk["bip"].clip(lower=1)
        sk["whiffPct"] = 100 * sk["whiffs"] / sk["swings"].clip(lower=1)
        sk["oSwingPct"] = 100 * sk["chase"] / sk["ooz"].clip(lower=1)

        def grade_of(season: int, metric: str, value: float, invert: bool) -> int | None:
            """Percentile rank within the season's 50+ PA population -> normal z ->
            50 + 10z (the site's grade scale), rounded to 5, clamped [30, 80]."""
            if value is None or (isinstance(value, float) and not np.isfinite(value)):
                return None
            sub = sk[sk["season"] == season][metric].dropna()
            if len(sub) < 30:
                return None
            pct = 100 * float((sub < value).mean())
            if invert:
                pct = 100 - pct
            z = max(-2.0, min(2.0, NormalDist().inv_cdf(max(1, min(99, pct)) / 100)))
            return int(max(30, min(80, round((50 + 10 * z) / 5) * 5)))

        CELL_H = """CASE WHEN plate_z > sz_bot + 0.67 * (sz_top - sz_bot) THEN 'high'
                   WHEN plate_z > sz_bot + 0.33 * (sz_top - sz_bot) THEN 'mid' ELSE 'low' END"""
        CELL_X = """CASE WHEN plate_x * (CASE WHEN stand = 'R' THEN -1 ELSE 1 END) > 0.28 THEN 'inside'
                   WHEN plate_x * (CASE WHEN stand = 'R' THEN -1 ELSE 1 END) < -0.28 THEN 'away' ELSE 'center' END"""
        sc = con.sql(f"""
            SELECT batter AS id, season,
                   {CELL_X} AS zx,
                   CASE WHEN plate_z IS NULL OR sz_top IS NULL OR sz_bot IS NULL OR sz_top <= sz_bot THEN 'off'
                        WHEN plate_z > sz_top + 0.35 THEN 'above'
                        WHEN plate_z < sz_bot - 0.35 THEN 'below'
                        ELSE {CELL_H} END AS zz,
                   COUNT(*) AS n,
                   SUM(CASE WHEN description IN {SWING} THEN 1 ELSE 0 END) AS swings,
                   SUM(CASE WHEN description IN ('swinging_strike','swinging_strike_blocked','foul_tip') THEN 1 ELSE 0 END) AS whiffs,
                   SUM(CASE WHEN bb_type IS NOT NULL AND launch_speed >= 95 THEN 1 ELSE 0 END) AS hard,
                   SUM(CASE WHEN bb_type IS NOT NULL THEN 1 ELSE 0 END) AS bip,
                   AVG(launch_speed) FILTER (WHERE bb_type IS NOT NULL AND des NOT ILIKE '%bunt%') AS ev
            FROM pitches_all
            WHERE game_type = 'R' AND season IN ({season_list}) AND batter IS NOT NULL
              AND stand IN ('L','R') AND p_throws IN ('L','R')
              AND description IS NOT NULL
            GROUP BY 1, 2, 3, 4
            ORDER BY id, season, zx, zz
        """).df()
        cells_by = {}
        for row in sc.itertuples():
            key = (int(row.id), int(row.season))
            if key not in sc_pop:
                continue
            cells_by.setdefault(key, []).append({
                "zx": row.zx, "zz": row.zz, "n": int(row.n),
                "swingPct": f(100 * row.swings / row.n, 1) if row.n else None,
                "whiffPct": f(100 * row.whiffs / row.swings, 1) if row.swings else None,
                "hardHitPct": f(100 * row.hard / row.bip, 1) if row.bip else None,
                "avgEv": f(row.ev, 1),
            })
        cnt = con.sql(f"""
            SELECT batter AS id, season, balls, strikes,
                   COUNT(*) AS n,
                   SUM(CASE WHEN description IN {SWING} THEN 1 ELSE 0 END) AS swings,
                   SUM(CASE WHEN description IN ('swinging_strike','swinging_strike_blocked','foul_tip') THEN 1 ELSE 0 END) AS whiffs,
                   SUM(CASE WHEN zone BETWEEN 10 AND 14 AND description IN {SWING} THEN 1 ELSE 0 END) AS chase,
                   SUM(CASE WHEN zone BETWEEN 10 AND 14 THEN 1 ELSE 0 END) AS ooz,
                   SUM(CASE WHEN bb_type IS NOT NULL AND launch_speed >= 95 THEN 1 ELSE 0 END) AS hard,
                   SUM(CASE WHEN bb_type IS NOT NULL THEN 1 ELSE 0 END) AS bip
            FROM pitches_all
            WHERE game_type = 'R' AND season IN ({season_list}) AND batter IS NOT NULL
              AND stand IN ('L','R') AND p_throws IN ('L','R')
              AND description IS NOT NULL AND balls BETWEEN 0 AND 3 AND strikes BETWEEN 0 AND 2
            GROUP BY 1, 2, 3, 4
        """).df()
        counts_by = {}
        for row in cnt.itertuples():
            key = (int(row.id), int(row.season))
            if key not in sc_pop:
                continue
            counts_by.setdefault(key, []).append({
                "count": f"{int(row.balls)}-{int(row.strikes)}", "n": int(row.n),
                "swingPct": f(100 * row.swings / row.n, 1) if row.n else None,
                "whiffPct": f(100 * row.whiffs / row.swings, 1) if row.swings else None,
                "chasePct": f(100 * row.chase / row.ooz, 1) if row.ooz else None,
                "hardHitPct": f(100 * row.hard / row.bip, 1) if row.bip else None,
            })

        # League overlays (wave 6): the same zone cells and counts over the
        # whole league per season x batter hand, so a card can show where he
        # sits against everyone else in each cell. Rates are computed
        # client-side from these totals. One small shared file.
        lg_cells = con.sql(f"""
            SELECT season, stand,
                   {CELL_X} AS zx,
                   CASE WHEN plate_z IS NULL OR sz_top IS NULL OR sz_bot IS NULL OR sz_top <= sz_bot THEN 'off'
                        WHEN plate_z > sz_top + 0.35 THEN 'above'
                        WHEN plate_z < sz_bot - 0.35 THEN 'below'
                        ELSE {CELL_H} END AS zz,
                   COUNT(*) AS n,
                   SUM(CASE WHEN description IN {SWING} THEN 1 ELSE 0 END) AS sw,
                   SUM(CASE WHEN description IN {WHIFF} THEN 1 ELSE 0 END) AS wh,
                   SUM(CASE WHEN bb_type IS NOT NULL AND launch_speed >= 95 THEN 1 ELSE 0 END) AS hard,
                   SUM(CASE WHEN bb_type IS NOT NULL THEN 1 ELSE 0 END) AS bip
            FROM pitches_all
            WHERE game_type = 'R' AND season IN ({season_list}) AND batter IS NOT NULL
              AND stand IN ('L','R') AND p_throws IN ('L','R')
              AND description IS NOT NULL
            GROUP BY 1, 2, 3, 4
        """).df()
        lg_counts = con.sql(f"""
            SELECT season, balls, strikes,
                   COUNT(*) AS n,
                   SUM(CASE WHEN description IN {SWING} THEN 1 ELSE 0 END) AS sw,
                   SUM(CASE WHEN description IN {WHIFF} THEN 1 ELSE 0 END) AS wh,
                   SUM(CASE WHEN zone BETWEEN 10 AND 14 AND description IN {SWING} THEN 1 ELSE 0 END) AS chase,
                   SUM(CASE WHEN zone BETWEEN 10 AND 14 THEN 1 ELSE 0 END) AS ooz,
                   SUM(CASE WHEN bb_type IS NOT NULL AND launch_speed >= 95 THEN 1 ELSE 0 END) AS hard,
                   SUM(CASE WHEN bb_type IS NOT NULL THEN 1 ELSE 0 END) AS bip
            FROM pitches_all
            WHERE game_type = 'R' AND season IN ({season_list}) AND batter IS NOT NULL
              AND stand IN ('L','R') AND p_throws IN ('L','R')
              AND description IS NOT NULL AND balls BETWEEN 0 AND 3 AND strikes BETWEEN 0 AND 2
            GROUP BY 1, 2, 3
        """).df()
        league: dict = {}
        for t in lg_cells.itertuples():
            s = league.setdefault(int(t.season), {"cells": {"R": {}, "L": {}}, "counts": {}})
            s["cells"][t.stand][f"{t.zz}-{t.zx}"] = {
                "n": int(t.n), "sw": int(t.sw), "wh": int(t.wh), "hard": int(t.hard), "bip": int(t.bip)}
        for t in lg_counts.itertuples():
            s = league.setdefault(int(t.season), {"cells": {"R": {}, "L": {}}, "counts": {}})
            s["counts"][f"{int(t.balls)}-{int(t.strikes)}"] = {
                "n": int(t.n), "sw": int(t.sw), "wh": int(t.wh), "chase": int(t.chase),
                "ooz": int(t.ooz), "hard": int(t.hard), "bip": int(t.bip)}
        jwrite(out / "scouting_league.json", {"seasons": league}, sort_keys=True)
        counts["scouting_league"] = 1

        # The league-wide skill board (H9 view): the same grades the per-player
        # cards carry, one row per hitter-season, so the board can never show a
        # number the card does not. Names/teams join on the /hitters page.
        skill_rows: dict = {}
        n_sc = 0
        for (pid, season) in sorted(cells_by.keys()):
            srow = sk[(sk["id"] == pid) & (sk["season"] == season)]
            power = contact = eye = None
            htype = None
            if not srow.empty:
                s0 = srow.iloc[0]
                power = grade_of(season, "barrelPct", float(s0["barrelPct"]) if s0["bip"] else None, invert=False)
                contact = grade_of(season, "whiffPct", float(s0["whiffPct"]), invert=True)
                eye = grade_of(season, "oSwingPct", float(s0["oSwingPct"]), invert=True)
                p = (power or 50) - 50
                c = (contact or 50) - 50
                if p >= 10 and c >= 0:
                    htype = "Slugger — the damage carries the profile"
                elif p >= 10 and c < 0:
                    htype = "Damage-first — big impact, big misses"
                elif p <= -10 and c >= 10:
                    htype = "Contact — puts the bat on the ball, leans on singles"
                elif p <= -10 and c <= -10:
                    htype = "Offensive lean-down — contact without impact yet"
                else:
                    htype = "Balanced — no carrying tool this season"
            approach = grade_of(season, "swingPct", float(s0["swingPct"]), invert=False) if not srow.empty else None
            jwrite_gz(out / "hitter_scouting" / f"{pid}-{season}.json.gz", {
                "id": str(pid), "season": season,
                "cells": cells_by[(pid, season)],
                "counts": sorted(counts_by.get((pid, season), []), key=lambda r: (r["count"],)),
                "skill": {"power": power, "contact": contact, "eye": eye, "approach": approach, "type": htype},
            }, sort_keys=True)
            skill_rows.setdefault(season, []).append({
                "id": str(pid), "pa": int(s0["pa"]) if not srow.empty else 0,
                "power": power, "contact": contact, "eye": eye, "approach": approach, "type": htype,
            })
            n_sc += 1
        jwrite(out / "hitter_skill_index.json",
               {"_comment": "per-season 20-80 skill grades; names/teams join from hitters.json on the board",
                "seasons": {str(k): v for k, v in sorted(skill_rows.items())}}, sort_keys=True)
        counts["scouting_files"] = n_sc
        print(f"hitter scouting files: {n_sc}")

    # --------------------------------------------- career files (season selector + career arsenal)
    # One small file per player: the seasons he appears in at THIS level with a
    # headline line, and — pitchers — the pitch mix per season, so a profile
    # can offer season switching and show how an arsenal evolved ("added the
    # sweeper in 2025") without fetching every season's full doc. Level-scoped:
    # the MLB bake and the AAA bake write into different directories.
    print(f"[{time.time() - t0:.0f}s] career", flush=True)  # per-family timing
    if "career" in fams:
        car_p = con.sql(f"""
            SELECT pitcher AS id, season,
                   SUM(CASE WHEN events IN {OUT_EVENTS_1} THEN 1 ELSE 0 END
                        + CASE WHEN events IN {OUT_EVENTS_2} THEN 2 ELSE 0 END
                        + CASE WHEN events IN {OUT_EVENTS_3} THEN 3 ELSE 0 END) AS outs,
                   COUNT(DISTINCT (game_pk, at_bat_number)) AS bf,
                   COUNT(*) AS np,
                   SUM(CASE WHEN events IN ('strikeout','strikeout_double_play') THEN 1 ELSE 0 END) AS nk,
                   SUM(CASE WHEN events IN ('walk','intentional_walk','intent_walk') THEN 1 ELSE 0 END) AS nbb,
                   SUM(CASE WHEN description IN ('called_strike','swinging_strike','swinging_strike_blocked','foul_tip') THEN 1 ELSE 0 END) AS ncsw,
                   SUM(CASE WHEN description IN ('swinging_strike','swinging_strike_blocked','foul_tip') THEN 1 ELSE 0 END) AS nwh
            FROM pitches_all
            WHERE game_type = 'R' AND season IN ({season_list}) AND pitcher IS NOT NULL
              {DETAIL_GATE}
            GROUP BY 1, 2
        """).df()
        oo_c = official_er(level)  # official outs, as the season rows (event outs miss outs on the bases)
        car_p["outs"] = [oo_c[k][1] if k in oo_c and oo_c[k][1] > 0 else o
                         for k, o in zip(zip(car_p["id"].astype(int), car_p["season"].astype(int)), car_p["outs"])]
        mix_p = con.sql(f"""
            SELECT pitcher AS id, season, {site_case_sql()} AS site, COUNT(*) AS n,
                   AVG(release_speed) AS v, AVG(pfx_z) AS ivb, AVG(pfx_x) AS hb
            FROM pitches_all
            WHERE game_type = 'R' AND season IN ({season_list}) AND pitcher IS NOT NULL
              {DETAIL_GATE}
            GROUP BY 1, 2, 3
        """).df()
        mixes: dict = {}
        for t in mix_p.itertuples():
            mixes.setdefault((int(t.id), int(t.season)), {})[t.site] = [
                int(t.n), round(float(t.v), 1) if t.v is not None else None,
                round(float(t.ivb), 1) if t.ivb is not None else None,
                round(float(t.hb), 1) if t.hb is not None else None]
        del mix_p
        car_by: dict = {}
        for t in car_p.itertuples():
            key = (int(t.id), int(t.season))
            mx = mixes.get(key, {})
            total = sum(v[0] for v in mx.values())
            car_by.setdefault(int(t.id), []).append({
                "s": int(t.season), "ip": f(t.outs / 3, 1), "bf": int(t.bf), "np": int(t.np),
                "kPct": f(100 * t.nk / t.bf, 1) if t.bf else None,
                "bbPct": f(100 * t.nbb / t.bf, 1) if t.bf else None,
                "cswPct": f(100 * t.ncsw / t.np, 1) if t.np else None,
                "whiffPct": f(100 * t.nwh / t.np, 1) if t.np else None,
                "mix": [[k2, v2[0], v2[1], v2[2], v2[3]] for k2, v2 in sorted(mx.items(), key=lambda kv: -kv[1][0])],
                "usage": {k2: round(100 * v2[0] / total, 1) for k2, v2 in mx.items()} if total else {},
            })
        del car_p, mixes
        n_car = 0
        for pid, seasons_rows in sorted(car_by.items()):
            jwrite(out / "career" / f"{pid}.json", {
                "id": str(pid), "kind": "P",
                "seasons": sorted(seasons_rows, key=lambda x: x["s"]),
            }, sort_keys=True)
            n_car += 1
        counts["pitcher_career_files"] = n_car
        print(f"pitcher career files: {n_car}")

        car_h = con.sql(f"""
            SELECT batter AS id, season,
                   COUNT(DISTINCT (game_pk, at_bat_number)) AS pa,
                   SUM(CASE WHEN bb_type IS NOT NULL THEN 1 ELSE 0 END) AS bip,
                   AVG(launch_speed) FILTER (WHERE bb_type IS NOT NULL AND des NOT ILIKE '%bunt%') AS ev,
                   SUM(CASE WHEN events = 'single' THEN 1 ELSE 0 END) AS s1,
                   SUM(CASE WHEN events = 'double' THEN 1 ELSE 0 END) AS s2,
                   SUM(CASE WHEN events = 'triple' THEN 1 ELSE 0 END) AS s3,
                   SUM(CASE WHEN events = 'home_run' THEN 1 ELSE 0 END) AS hr,
                   SUM(CASE WHEN events IN ('walk','intentional_walk','intent_walk') THEN 1 ELSE 0 END) AS bb,
                   SUM(CASE WHEN events = 'hit_by_pitch' THEN 1 ELSE 0 END) AS hbp,
                   SUM(CASE WHEN events IN ('sac_fly','sac_fly_double_play') THEN 1 ELSE 0 END) AS sf,
                   SUM(CASE WHEN events = 'sac_bunt' THEN 1 ELSE 0 END) AS sh,
                   SUM(CASE WHEN events = 'catcher_interf' THEN 1 ELSE 0 END) AS ci,
                   SUM(CASE WHEN events IN ('strikeout','strikeout_double_play') THEN 1 ELSE 0 END) AS k
            FROM pitches_all
            WHERE game_type = 'R' AND season IN ({season_list}) AND batter IS NOT NULL
              AND stand IN ('L','R') AND p_throws IN ('L','R')
            GROUP BY 1, 2
        """).df()
        hcar_by: dict = {}
        for t in car_h.itertuples():
            ab = t.pa - t.bb - t.hbp - t.sf - t.sh - t.ci
            obp_den = ab + t.bb + t.hbp + t.sf + t.ci
            tb = t.s1 + 2 * t.s2 + 3 * t.s3 + 4 * t.hr
            hcar_by.setdefault(int(t.id), []).append({
                "s": int(t.season), "pa": int(t.pa), "bip": int(t.bip),
                "ev": f(t.ev, 1) if t.ev is not None else None,
                "avg": f((t.s1 + t.s2 + t.s3 + t.hr) / ab, 3) if ab else None,
                "obp": f((t.s1 + t.s2 + t.s3 + t.hr + t.bb + t.hbp + t.ci) / obp_den, 3) if obp_den else None,
                "slg": f(tb / ab, 3) if ab else None,
                "ops": f(((t.s1 + t.s2 + t.s3 + t.hr + t.bb + t.hbp + t.ci) / obp_den if obp_den else 0)
                          + (tb / ab if ab else 0), 3) if (obp_den and ab) else None,
                "kPct": f(100 * t.k / t.pa, 1) if t.pa else None,
                "bbPct": f(100 * t.bb / t.pa, 1) if t.pa else None,
            })
        del car_h
        n_hcar = 0
        for pid, seasons_rows in sorted(hcar_by.items()):
            jwrite(out / "career" / f"{pid}.json", {
                "id": str(pid), "kind": "H",
                "seasons": sorted(seasons_rows, key=lambda x: x["s"]),
            }, sort_keys=True)
            n_hcar += 1
        counts["hitter_career_files"] = n_hcar
        print(f"hitter career files: {n_hcar}")

    # --------------------------------------------- per-player chart datasets (visuals)
    # The college front end's chart library, re-fed with MLB data: velocity
    # distribution, spin clock, release cloud, location density surfaces, count
    # lattice, usage vs batter hand. The college computed these client-side from
    # per-pitch events; here the densities/aggregates are computed IN THE BAKE
    # so each payload stays a few KB. All measured, all descriptive.
    print(f"[{time.time() - t0:.0f}s] visuals", flush=True)  # per-family timing
    if "visuals" in fams:
        import numpy as _np

        # Same populations the detail family publishes (self-contained: this
        # family bakes alone).
        pitcher_pop = {(pid, s) for (pid, s) in g.index
                       if keep_row(int(pid), int(s)) and (pid, s) in tot_indexed.index}
        hpop_v = con.sql(f"""
            SELECT batter AS id, season
            FROM pitches_all
            WHERE game_type = 'R' AND season IN ({season_list}) AND batter IS NOT NULL
              AND stand IN ('L','R') AND p_throws IN ('L','R')
            GROUP BY 1, 2
            HAVING COUNT(DISTINCT (game_pk, at_bat_number)) >= 50
        """).df()
        h_pop = {(int(t.id), int(t.season)) for t in hpop_v.itertuples()}

        def _kde_curve(vals: list[float], lo: float, hi: float, bw_min: float = 0.4,
                       samples: int = 240) -> tuple[list[float], list[float], dict]:
            """Usage-scaled 1D gaussian KDE on a shared grid. Silverman's window
            with the college's 0.4-mph floor: below it a curve would draw
            measurement noise as arsenal structure."""
            x = _np.asarray(vals, dtype=float)
            n = len(x)
            sd = float(x.std())
            iqr = float(_np.subtract(*_np.percentile(x, [75, 25]))) if n > 3 else 0.0
            scale = min(sd, iqr / 1.34) if iqr > 0 else sd
            bw = max(bw_min, 0.9 * scale * n ** (-0.2))
            grid = _np.linspace(lo, hi, samples)
            z = (grid[:, None] - x[None, :]) / bw
            dens = _np.exp(-0.5 * z ** 2).sum(axis=1) / (n * bw * float(_np.sqrt(2 * _np.pi)))
            peak = int(dens.argmax())
            return ([float(v) for v in grid], [round(float(v), 5) for v in dens],
                    {"peak_x": round(float(grid[peak]), 2), "peak_y": round(float(dens[peak]), 5)})

        def _stride(points: list, cap: int) -> list:
            """Deterministic thinning for dot clouds: keep the order, cap the count."""
            if len(points) <= cap:
                return points
            step = len(points) // cap + 1
            return points[::step]

        # One raw pass carries velo/spin/release/location; aggregates below come
        # from their own GROUP BYs. Ordered so the stride thinning is stable.
        pv = con.sql(f"""
            SELECT pitcher AS id, season, {site_case_sql()} AS site,
                   game_pk, at_bat_number, pitch_number,
                   release_speed, spin_axis, release_spin_rate,
                   release_pos_x, release_pos_z, plate_x, plate_z
            FROM pitches_all
            WHERE game_type = 'R' AND season IN ({season_list}) AND pitcher IS NOT NULL
              {DETAIL_GATE}
            ORDER BY id, season, game_pk, at_bat_number, pitch_number
        """).df()
        buckets: dict = {}
        seqs: dict = {}
        prev_pa = None
        prev_site = None
        for t in pv.itertuples():
            key = (int(t.id), int(t.season))
            b = buckets.get(key)
            if b is None:
                buckets[key] = b = {}
            col = b.get(t.site)
            if col is None:
                b[t.site] = col = {"v": [], "ax": [], "rpm": [], "rx": [], "rz": [], "px": [], "pz": []}
            # D-11: consecutive type pairs within a PA — what he goes to next
            pa_key = (int(t.game_pk), int(t.at_bat_number))
            if prev_pa == pa_key and prev_site and prev_site != t.site:
                sk_key = f"{prev_site}>{t.site}"
                seqs.setdefault(key, {})
                seqs[key][sk_key] = seqs[key].get(sk_key, 0) + 1
            prev_pa, prev_site = pa_key, t.site
            if t.release_speed is not None:
                col["v"].append(float(t.release_speed))
            if t.spin_axis is not None:
                col["ax"].append(float(t.spin_axis))
                col["rpm"].append(float(t.release_spin_rate) if t.release_spin_rate is not None else None)
            if t.release_pos_x is not None and t.release_pos_z is not None:
                col["rx"].append(round(float(t.release_pos_x), 2))
                col["rz"].append(round(float(t.release_pos_z), 2))
            if t.plate_x is not None and t.plate_z is not None:
                col["px"].append(round(float(t.plate_x), 2))
                col["pz"].append(round(float(t.plate_z), 2))
        del pv

        # Count lattice (college lib/count-lattice.ts): transitions read off the
        # call, never a rebuilt sequence — the PAs that took (b,s) -> (b+1,s) are
        # exactly the balls thrown at (b,s). Terminals are the PA-ending pitches.
        BALLS = ("ball", "intent_ball", "automatic_ball", "pitchout", "blocked_ball")
        # Fouls move the count below two strikes (a two-strike foul is a self-loop, not drawn).
        # Split by batter side for the RHH/LHH chips; "pa" = distinct PAs with a pitch at the
        # count, so a PA a reliever inherits mid-count counts where he joined it.
        STRIKES = ("called_strike", "swinging_strike", "swinging_strike_blocked",
                   "foul_tip", "bunt_foul_tip", "missed_bunt", "foul", "foul_bunt")
        pa_n = con.sql(f"""
            SELECT pitcher AS id, season, stand, balls, strikes,
                   COUNT(DISTINCT (game_pk, at_bat_number)) AS pa
            FROM pitches_all
            WHERE game_type = 'R' AND season IN ({season_list}) AND pitcher IS NOT NULL
              {DETAIL_GATE} AND balls BETWEEN 0 AND 3 AND strikes BETWEEN 0 AND 2
            GROUP BY GROUPING SETS ((pitcher, season, stand, balls, strikes), (pitcher, season, balls, strikes),
                           (pitcher, season, stand), (pitcher, season))
        """).df()
        pa_by = {(int(t.id), int(t.season), t.stand if isinstance(t.stand, str) else "all",
                  None if pd.isna(t.balls) else f"{int(t.balls)}-{int(t.strikes)}"): int(t.pa)
                 for t in pa_n.itertuples()}
        del pa_n
        cn = con.sql(f"""
            SELECT pitcher AS id, season, stand, balls, strikes, {site_case_sql()} AS site,
                   COUNT(*) AS n,
                   SUM(CASE WHEN description IN {BALLS} THEN 1 ELSE 0 END) AS nb,
                   SUM(CASE WHEN description IN {STRIKES} THEN 1 ELSE 0 END) AS ns,
                   SUM(CASE WHEN events IN ('strikeout','strikeout_double_play') THEN 1 ELSE 0 END) AS nk,
                   SUM(CASE WHEN events IN ('walk','intentional_walk','intent_walk') THEN 1 ELSE 0 END) AS nbb,
                   SUM(CASE WHEN events = 'hit_by_pitch' THEN 1 ELSE 0 END) AS nhbp
            FROM pitches_all
            WHERE game_type = 'R' AND season IN ({season_list}) AND pitcher IS NOT NULL
              {DETAIL_GATE} AND balls BETWEEN 0 AND 3 AND strikes BETWEEN 0 AND 2
            GROUP BY 1, 2, 3, 4, 5, 6
        """).df()
        counts_by: dict = {}
        for t in cn.itertuples():
            key = (int(t.id), int(t.season))
            for side in ("all", t.stand):
                counts_by.setdefault(key, {}).setdefault(side, {}).setdefault((int(t.balls), int(t.strikes)), []).append(t)
        del cn

        # Usage vs batter hand (back-to-back bars)
        hv = con.sql(f"""
            SELECT pitcher AS id, season, {site_case_sql()} AS site, stand, COUNT(*) AS n
            FROM pitches_all
            WHERE game_type = 'R' AND season IN ({season_list}) AND pitcher IS NOT NULL
              {DETAIL_GATE}
            GROUP BY 1, 2, 3, 4
        """).df()
        hand_by: dict = {}
        for t in hv.itertuples():
            key = (int(t.id), int(t.season))
            hand_by.setdefault(key, []).append(t)
        del hv

        # League-average rulebook zone for the surfaces' dashed outline (the
        # player's own zone varies night to night; the league frame is the
        # reference a reader expects).
        zq = con.sql(f"""
            SELECT season, AVG(sz_bot) AS sb, AVG(sz_top) AS st
            FROM pitches_all
            WHERE game_type = 'R' AND season IN ({season_list})
              AND sz_top IS NOT NULL AND sz_bot IS NOT NULL AND sz_top > sz_bot
            GROUP BY 1
        """).df()
        zone_by = {int(t.season): [round(float(t.sb), 2), round(float(t.st), 2)] for t in zq.itertuples()}

        n_vis = 0
        tasks: list = []
        cheap: dict = {}
        for (pid, season), b in sorted(buckets.items()):
            if (pid, season) not in pitcher_pop:
                continue
            all_v = [v for col in b.values() for v in col["v"]]
            if len(all_v) < 50:
                continue
            # -- count lattice nodes (cheap: pre-aggregated rows)
            lat = {}
            for side, by_count in counts_by.get((pid, season), {}).items():
                lat[side] = {"pa": pa_by.get((pid, season, side, None), 0), "c": {}}
                for (bb, ss), rows in by_count.items():
                    mix = {}
                    n_node = nb = ns = nk = nbb = nhbp = 0
                    for t in rows:
                        mix[t.site] = mix.get(t.site, 0) + int(t.n)
                        n_node += int(t.n)
                        nb += int(t.nb)
                        ns += int(t.ns)
                        nk += int(t.nk)
                        nbb += int(t.nbb)
                        nhbp += int(t.nhbp)
                    cnt = f"{bb}-{ss}"
                    lat[side]["c"][cnt] = {  # b / s = PAs leaving on a ball / strike (0 at the 3-ball / 2-strike walls)
                        "n": n_node, "pa": pa_by.get((pid, season, side, cnt), 0),
                        "m": sorted(mix.items(), key=lambda kv: (-kv[1], kv[0])),
                        "b": nb if bb < 3 else 0, "s": ns if ss < 2 else 0,
                        "k": nk, "bb": nbb, "hbp": nhbp,
                    }
            seq = sorted((seqs.get((pid, season)) or {}).items(), key=lambda kv: -kv[1])[:40]
            hand_rows = []
            hrows = hand_by.get((pid, season), [])
            tot = {"L": 0, "R": 0}
            per = {}
            for t in hrows:
                tot[t.stand] = tot.get(t.stand, 0) + int(t.n)
                per.setdefault(t.site, {})[t.stand] = int(t.n)
            for site, d in sorted(per.items(), key=lambda kv: -(kv[1].get("L", 0) + kv[1].get("R", 0))):
                n_site = d.get("L", 0) + d.get("R", 0)
                lhb = round(100 * d.get("L", 0) / tot["L"], 1) if tot["L"] else None
                rhb = round(100 * d.get("R", 0) / tot["R"], 1) if tot["R"] else None
                hand_rows.append({"t": site, "n": n_site, "lhb": lhb, "rhb": rhb,
                                  "delta": round(lhb - rhb, 1) if lhb is not None and rhb is not None else None})
            cheap[(pid, season)] = (lat, [[k2, v2] for k2, v2 in seq], hand_rows)
            tasks.append((pid, season, b, zone_by.get(season)))
        # The KDE/grid fits are pure per-player numpy — run them in a process
        # pool (deterministic: every task is independent and results are written
        # in key order). GOAT_POOL=0 falls back to serial.
        pool_size = 0 if os.environ.get("GOAT_POOL") == "0" else min(8, (os.cpu_count() or 4))
        payloads: list = []
        if pool_size >= 2 and len(tasks) >= 16:
            from concurrent.futures import ProcessPoolExecutor
            with ProcessPoolExecutor(max_workers=pool_size) as ex:
                payloads = [rr for rr in ex.map(_visuals_payload, tasks, chunksize=16) if rr is not None]
        else:
            payloads = [rr for rr in map(_visuals_payload, tasks) if rr is not None]
        for pid, season, payload in payloads:
            lat, seq, hand_rows = cheap[(pid, season)]
            payload["seq"] = seq
            payload["counts"] = lat
            payload["hand"] = hand_rows
            jwrite_gz(out / "visuals" / f"{pid}-{season}.json.gz", payload, sort_keys=True)
            n_vis += 1
        del buckets, tasks
        counts["pitcher_visuals"] = n_vis
        print(f"pitcher visuals: {n_vis}")

        # ---- hitter side: the pitches-seen location surface (his zone, mirrored
        # client-side by stand like the scouting grid)
        hp = con.sql(f"""
            SELECT batter AS id, season, stand, {site_case_sql()} AS site,
                   plate_x, plate_z
            FROM pitches_all
            WHERE game_type = 'R' AND season IN ({season_list}) AND batter IS NOT NULL
              AND stand IN ('L','R') AND p_throws IN ('L','R')
              AND plate_x IS NOT NULL AND plate_z IS NOT NULL
              AND pitch_type IN ('FF','SI','FC','SL','CU','KC','SW','SV','ST','CH','FS','FO','EP')
                AND release_speed BETWEEN 55 AND 105 AND release_extension > 3
                AND pfx_z IS NOT NULL AND pfx_x IS NOT NULL AND release_spin_rate IS NOT NULL
            ORDER BY id, season
        """).df()
        hb: dict = {}
        for t in hp.itertuples():
            key = (int(t.id), int(t.season))
            h = hb.get(key)
            if h is None:
                hb[key] = h = {"stand": t.stand, "types": {}}
            col = h["types"].get(t.site)
            if col is None:
                h["types"][t.site] = col = {"px": [], "pz": []}
            col["px"].append(round(float(t.plate_x), 2))
            col["pz"].append(round(float(t.plate_z), 2))
        del hp
        n_hvis = 0
        for (pid, season), h in sorted(hb.items()):
            if (pid, season) not in h_pop:
                continue
            loc = {}
            for site, col in sorted(h["types"].items(), key=lambda kv: -len(kv[1]["px"])):
                g = _loc_grid(col["px"], col["pz"])
                if g:
                    loc[site] = g
            if not loc:
                continue
            jwrite_gz(out / "visuals" / f"{pid}-{season}.json.gz", {
                "id": str(pid), "side": "H", "season": season, "stand": h["stand"],
                "zone": zone_by.get(season),
                "loc": {"x": VIS_LOC_X, "z": VIS_LOC_Z, "n": VIS_GRID_N, "types": loc},
            }, sort_keys=True)
            n_hvis += 1
        counts["hitter_visuals"] = n_hvis
        print(f"hitter visuals: {n_hvis}")

    # ------------------------------------------------- prospect rankings (prospects)
    # MLB Pipeline's public rankings (pipeline/prospects_fetch.py, all lists and
    # years back to 2011), keyed by mlbam id. Baked three ways from one source:
    # per-season page files, per-player rank files for the profile badges, and
    # nothing graded — rankings are Pipeline editors' opinions, quoted as such.
    # The per-row shape leaves a `value` key open for a prospect-value metric.
    if "prospects" in fams:
        SRC = ROOT / "data" / "milb" / "prospects.json"
        if SRC.exists():
            ORG_ABBR = {
                "Arizona Diamondbacks": "AZ", "Athletics": "ATH", "Atlanta Braves": "ATL",
                "Baltimore Orioles": "BAL", "Boston Red Sox": "BOS", "Chicago Cubs": "CHC",
                "Chicago White Sox": "CWS", "Cincinnati Reds": "CIN", "Cleveland Guardians": "CLE",
                "Colorado Rockies": "COL", "Detroit Tigers": "DET", "Houston Astros": "HOU",
                "Kansas City Royals": "KC", "Los Angeles Angels": "LAA", "Los Angeles Dodgers": "LAD",
                "Miami Marlins": "MIA", "Milwaukee Brewers": "MIL", "Minnesota Twins": "MIN",
                "New York Mets": "NYM", "New York Yankees": "NYY", "Philadelphia Phillies": "PHI",
                "Pittsburgh Pirates": "PIT", "San Diego Padres": "SD", "San Francisco Giants": "SF",
                "Seattle Mariners": "SEA", "St. Louis Cardinals": "STL", "Tampa Bay Rays": "TB",
                "Texas Rangers": "TEX", "Toronto Blue Jays": "TOR", "Washington Nationals": "WSH",
            }
            POS_LABEL = {"of": "OF", "rhp": "RHP", "lhp": "LHP", "ss": "SS", "c": "C",
                         "1b": "1B", "2b": "2B", "3b": "3B"}
            # slug -> site abbr, same pairs the /prospects page's chips use
            SLUG_ABBR = {
                "angels": "LAA", "astros": "HOU", "athletics": "ATH", "bluejays": "TOR",
                "braves": "ATL", "brewers": "MIL", "cardinals": "STL", "cubs": "CHC",
                "dbacks": "AZ", "dodgers": "LAD", "giants": "SF", "guardians": "CLE",
                "mariners": "SEA", "marlins": "MIA", "mets": "NYM", "nationals": "WSH",
                "orioles": "BAL", "padres": "SD", "phillies": "PHI", "pirates": "PIT",
                "rangers": "TEX", "rays": "TB", "redsox": "BOS", "reds": "CIN",
                "rockies": "COL", "royals": "KC", "tigers": "DET", "twins": "MIN",
                "whitesox": "CWS", "yankees": "NYY",
            }
            # Pipeline's ARCHIVED lists return each player's CURRENT org: graduated
            # major leaguers carry null (no activeRoster), released players read
            # "Office of the Commissioner". List MEMBERSHIP is historical, though —
            # a player on the 2011 Angels' top 30 was an Angel in 2011 — so the
            # historical org is reconstructed from that year's team lists before
            # the rows are cleaned (rank stays Pipeline's; only the org is filled).
            RECON_NULL = {None, "", "Office of the Commissioner"}

            # debut marks for list rows + the farm/riser tables (loaded before the
            # year loop — _clean_row reads it while the loop runs)
            ppl_fp0 = ROOT / "data" / "milb" / "people.parquet"
            debut_year = {}
            if ppl_fp0.exists():
                for prow in pd.read_parquet(ppl_fp0).itertuples():
                    if pd.notna(getattr(prow, "debut", None)):
                        debut_year[int(prow.id)] = int(str(prow.debut)[:4])

            def _clean_row(r: dict, hist_org: dict | None = None, year: int = 0) -> dict:
                # Membership first: a club list's own players are that club's, at
                # list time — the current org (a trade, a coaching job, the
                # Commissioner's pool) must never overwrite the historical one.
                org = hist_org.get(r["id"]) if hist_org else None
                if org is None:
                    org = ORG_ABBR.get(r["org"] or "", r["org"])
                if org in RECON_NULL:
                    org = None
                return {
                    "rank": int(r["rank"]), "id": str(r["id"]), "n": r["name"],
                    "pos": r["pos"], "org": org,
                    "eta": r.get("eta"), "age": r.get("age"), "bats": r.get("bats"),
                    "debut": debut_year.get(int(r["id"])),
                    "gradesH": r.get("gradesHitting"), "gradesP": r.get("gradesPitching"),
                }

            raw = json.loads(SRC.read_text())
            per_player: dict = {}
            n_season_files = 0
            for year, lists in sorted(raw.items(), key=lambda kv: int(kv[0])):
                season_out = {}
                # membership org, keyed by player id; a traded prospect can sit on
                # two club lists — keep the BETTER (lower) rank's club.
                hist_org: dict = {}
                for key, rows in sorted(lists.items()):
                    if not key.startswith("team:"):
                        continue
                    abbr = SLUG_ABBR.get(key.partition(":")[2])
                    if not abbr:
                        continue
                    for r0 in rows:
                        pid = r0["id"]
                        if pid not in hist_org or int(r0["rank"]) < int(hist_org[pid][0]):
                            hist_org[pid] = (int(r0["rank"]), abbr)
                hist = {pid: abbr for pid, (_, abbr) in hist_org.items()}
                for key, rows in sorted(lists.items()):
                    cleaned = [_clean_row(r, hist, int(year)) for r in rows]
                    if key == "top100":
                        season_out["top100"] = cleaned
                    else:
                        kind, _, slug = key.partition(":")
                        season_out.setdefault(f"{kind}s", {})[slug] = cleaned
                    for row in cleaned:
                        entry = {"season": int(year), "list": key, "rank": row["rank"]}
                        if key.startswith("team:"):
                            entry["team"] = row["org"]
                            entry["teamSlug"] = key.split(":")[1]
                        if key.startswith("position:"):
                            entry["pos"] = POS_LABEL.get(key.split(":")[1], key.split(":")[1].upper())
                            entry["posSlug"] = key.split(":")[1]
                        per_player.setdefault(row["id"], {"id": row["id"], "n": row["n"], "ranks": []})["ranks"].append(entry)
                jwrite(out / "prospects" / f"{year}.json", {
                    "season": int(year),
                    **season_out,
                }, sort_keys=True)
                n_season_files += 1
            n_rank_files = 0
            # Draft + debut context (depth item 5): every ranked player's draft
            # line and MLB debut from the amateur fetch, so the profile badge
            # carries "1st round · 11th overall" and the hit-rate joins share
            # the same file. Static fetched data; guarded when absent.
            draft_by_id = {}
            if (ROOT / "data" / "milb" / "draft.json").exists():
                # A player can be drafted several times (the HS flier that
                # doesn't sign, then the college pick that does) — the badge
                # carries the SIGNED draft (the pick with a bonus), and the
                # latest year breaks ties.
                for picks in json.loads((ROOT / "data" / "milb" / "draft.json").read_text()).values():
                    for dp in picks:
                        if not dp.get("id"):
                            continue
                        cur = draft_by_id.get(dp["id"])
                        if cur is None:
                            draft_by_id[dp["id"]] = dp
                        elif (dp.get("bonus") and not cur.get("bonus")) or                              (bool(dp.get("bonus")) == bool(cur.get("bonus")) and dp["year"] > cur["year"]):
                            draft_by_id[dp["id"]] = dp
            people_by_id = {}
            ppl_fp = ROOT / "data" / "milb" / "people.parquet"
            if ppl_fp.exists():
                ppl = pd.read_parquet(ppl_fp)
                for prow in ppl.itertuples():
                    people_by_id[int(prow.id)] = prow
            for pid, doc in sorted(per_player.items()):
                doc["ranks"] = sorted(doc["ranks"], key=lambda e: (-e["season"], e["list"]))
                dp = draft_by_id.get(int(pid))
                if dp:
                    doc["draft"] = {"year": dp["year"], "pick": dp["pick"],
                                    "round": dp["round"], "team": dp["team"],
                                    "school": dp["school"]}
                pr = people_by_id.get(int(pid))
                if pr is not None:
                    if getattr(pr, "debut", None):
                        doc["debut"] = str(pr.debut)[:10]
                    if getattr(pr, "pos", None):
                        doc["pos"] = pr.pos
                jwrite(out / "prospect_rank" / f"{pid}.json", doc, sort_keys=True)
                n_rank_files += 1
            counts["prospect_season_files"] = n_season_files
            counts["prospect_rank_files"] = n_rank_files

            # ------------------------------------------- farm output / risers (item 8)
            # Org table on the MATURED window (2011-2019 lists: essentially every
            # debut that will happen has happened). Tier mix matters — a farm with
            # eight top-100s should graduate more than one with two — so the table
            # shows the org's own reach rate against the league's rate on the SAME
            # tier slots, plus a tier-weighted output index (top-10 4, 11-25 3,
            # 26-50 2, 51-100 1, unranked 0.5) and the MLB playing time its alumni
            # produced (PA + BF from the mart).
            MATURED = range(2011, 2020)
            t100 = {}   # (year, id) -> rank
            for y0, lists in raw.items():
                if int(y0) in MATURED:
                    for r0 in lists.get("top100", []) or []:
                        t100[(int(y0), int(r0["id"]))] = int(r0["rank"])

            def tier_w(rank: int | None) -> float:
                if rank is None:
                    return 0.5
                return 4.0 if rank <= 10 else 3.0 if rank <= 25 else 2.0 if rank <= 50 else 1.0

            pa_made = {}
            bf_made = {}
            try:
                made = con.sql("SELECT batter, count(DISTINCT (game_pk, at_bat_number)) AS pa FROM pitches_all WHERE game_type = 'R' GROUP BY 1").df()
                pa_made = {int(r0.batter): int(r0.pa) for r0 in made.itertuples()}
                made2 = con.sql("SELECT pitcher, count(DISTINCT (game_pk, at_bat_number)) AS bf FROM pitches_all WHERE game_type = 'R' GROUP BY 1").df()
                bf_made = {int(r0.pitcher): int(r0.bf) for r0 in made2.itertuples()}
            except Exception:  # noqa: BLE001
                pass

            for y0, lists in raw.items():  # top-100 ranks for every list year (the by-year tables use them all)
                for r0 in lists.get("top100", []) or []:
                    t100.setdefault((int(y0), int(r0["id"])), int(r0["rank"]))

            def farm_table(years) -> tuple[list, float]:
                """Org rows over the list years in `years`; reach is read against the league on the same years."""
                orgs = {}
                league_slots = {"n": 0, "reached": 0}
                for y0, lists in raw.items():
                    if int(y0) not in years:
                        continue
                    for key, rows0 in lists.items():
                        if not key.startswith("team:"):
                            continue
                        abbr = SLUG_ABBR.get(key.partition(":")[2])
                        if not abbr:
                            continue
                        o = orgs.setdefault(abbr, {"slots": 0, "reached": 0, "t100": 0, "index": 0.0,
                                                   "pa": 0, "bf": 0, "names": []})
                        for r0 in rows0:
                            pid = int(r0["id"])
                            rank = t100.get((int(y0), pid))
                            reached = pid in debut_year
                            o["slots"] += 1
                            o["t100"] += 1 if rank else 0
                            o["reached"] += 1 if reached else 0
                            o["index"] += tier_w(rank) if reached else 0.0
                            o["pa"] += pa_made.get(pid, 0)
                            o["bf"] += bf_made.get(pid, 0)
                            league_slots["n"] += 1
                            league_slots["reached"] += 1 if reached else 0
                lg_rate = league_slots["reached"] / max(1, league_slots["n"])
                farm_rows = []
                for abbr, o in orgs.items():
                    rate = o["reached"] / max(1, o["slots"])
                    farm_rows.append({"org": abbr, "slots": o["slots"], "top100": o["t100"],
                                      "reached": o["reached"], "reachedPct": f(100 * rate, 1),
                                      "vsLeague": f(100 * (rate - lg_rate), 1),
                                      "outputIndex": f(o["index"], 0),
                                      "mlbPa": o["pa"], "mlbBf": o["bf"]})
                farm_rows.sort(key=lambda e: -float(e["outputIndex"] or 0))
                return farm_rows, lg_rate

            farm_rows, lg_rate = farm_table(MATURED)
            # one table per list year; years after 2019 are still maturing, so reach reads low for every org alike
            farm_by_year = {}
            for y0 in sorted({int(y) for y in raw}):
                rows_y, rate_y = farm_table({y0})
                if rows_y:
                    farm_by_year[str(y0)] = {"leagueReachedPct": f(100 * rate_y, 1), "matured": y0 in MATURED, "orgs": rows_y}

            # tier time-to-MLB curves: cumulative % debuted by years since the
            # FIRST top-100 appearance (matured classes only)
            first_seen: dict = {}
            for (y0, pid), rank in t100.items():
                if y0 not in MATURED:
                    continue
                if pid not in first_seen or y0 < first_seen[pid][0]:
                    first_seen[pid] = (y0, rank)
            tier_of_rank = lambda rk: "top 10" if rk <= 10 else "11-25" if rk <= 25 else "26-50" if rk <= 50 else "51-100"
            curves_acc: dict = {}
            for pid, (y0, rank) in first_seen.items():
                tier = tier_of_rank(rank)
                dy = debut_year.get(pid)
                delta = (dy - y0) if dy is not None and dy >= y0 else None
                c = curves_acc.setdefault(tier, {"n": 0, "by": [0] * 7})
                c["n"] += 1
                if delta is not None:
                    for k in range(min(delta, 6), 7):
                        c["by"][k] += 1
            tier_curves = [{"tier": tier, "n": c["n"],
                            "cumPct": [f(100 * c["by"][k] / c["n"], 1) for k in range(7)]}
                           for tier, c in sorted(curves_acc.items(),
                                                 key=lambda kv: ["top 10", "11-25", "26-50", "51-100"].index(kv[0]))]

            # risers: consecutive top-100 rank deltas per year
            t100_by_year: dict = {}
            for y0, lists in raw.items():
                t100_by_year[int(y0)] = {int(r0["id"]): int(r0["rank"]) for r0 in lists.get("top100", []) or []}
            risers = {}
            for y0 in sorted(t100_by_year):
                if y0 - 1 not in t100_by_year:
                    continue
                prev = t100_by_year[y0 - 1]
                cur = t100_by_year[y0]
                moves = [(prev[pid] - rk, pid, prev[pid], rk) for pid, rk in cur.items() if pid in prev]
                up = sorted(moves, reverse=True)[:8]
                down = sorted(moves)[:8]
                def row_of(mv):
                    _, pid, p0, c0 = mv
                    return {"id": str(pid), "name": draft_by_id.get(pid, {}).get("name") or per_player.get(str(pid), {}).get("n"),
                            "from": p0, "to": c0, "debut": debut_year.get(pid)}
                risers[str(y0)] = {"up": [row_of(m0) for m0 in up], "down": [row_of(m0) for m0 in down]}
            jwrite(out / "prospects" / "farm.json", {
                "_comment": ("org farm output on 2011-2019 lists (matured), tier-weighted index (top10 4 / "
                             "11-25 3 / 26-50 2 / 51-100 1 / unranked 0.5, counted only when the player "
                             "reached MLB); vs-league is the org's reach rate on its own slots minus the "
                             "league's on the same window; risers are consecutive top-100 rank deltas"),
                "leagueReachedPct": f(100 * lg_rate, 1),
                "orgs": farm_rows, "byYear": farm_by_year, "tierCurves": tier_curves, "risers": risers,
            }, sort_keys=True)
            print(f"prospect season files: {n_season_files}; rank files: {n_rank_files}; farm: {len(farm_rows)} orgs")
        else:
            print("prospects: data/milb/prospects.json missing — run pipeline/prospects_fetch.py first")

    # --------------------------------------------------------------- mechanism
    # The physics study's published tables (depth item 9). These are kb-
    # session's measurements (pipeline/MECHANISM-MLB.md, physics.py, 2023-25
    # regular season, 2.12M pitches) — the "why whiffs happen" layer that
    # travel under every Whiff+ grade. Re-published verbatim with provenance;
    # recompute there, not here.
    print(f"[{time.time() - t0:.0f}s] mechanism", flush=True)
    if "mechanism" in fams and level == "mlb":
        jwrite(out / "mechanism" / "tables.json", {
            "_provenance": "pipeline/MECHANISM-MLB.md (2026-10-25); physics.py over Statcast 2023-25, "
                           "2.12M regular-season pitches; marginal effects within pitch type",
            "activeSpinQuartiles": {
                "_read": "Whiff rate by active-spin quartile (Q1 lowest → Q4 highest). The sign flips by class: ride helps fastballs, gyro delays break on sliders.",
                "rows": [
                    {"type": "FF", "q1": 8.3, "q4": 10.2, "effect": "+1.9 pts — more active spin = more carry"},
                    {"type": "SI", "q1": 5.2, "q4": 6.3, "effect": "+1.1 pts"},
                    {"type": "SL", "q1": 17.0, "q4": 14.8, "effect": "-2.2 pts — gyro sliders whiff MORE"},
                    {"type": "CU", "q1": 12.9, "q4": 12.1, "effect": "-0.8 pts"},
                    {"type": "CH", "q1": 14.9, "q4": 14.3, "effect": "-0.6 pts"},
                ],
            },
            "veloShapeGrid": {
                "_read": "FB/SI whiff% by velocity tercile x IVB tercile: shape matters more as velocity rises — velo is the enabler, shape the multiplier.",
                "rows": [
                    {"velo": "low", "ivbLow": 5.2, "ivbMid": 6.5, "ivbHi": 7.4, "spread": 2.2},
                    {"velo": "mid", "ivbLow": 5.7, "ivbMid": 7.9, "ivbHi": 9.8, "spread": 4.1},
                    {"velo": "high", "ivbLow": 6.5, "ivbMid": 9.6, "ivbHi": 12.6, "spread": 6.1},
                ],
            },
            "drag": {
                "_read": "Higher deceleration (drag) whiffs more within type — a Hawk-Eye-only measurement, consistent with seam-orientation effects.",
                "rows": [
                    {"type": "SI", "spread": "+1.7 pts"},
                    {"type": "SL", "spread": "+2.3 pts"},
                    {"type": "CH", "spread": "+1.1 pts"},
                ],
            },
        }, sort_keys=True)
        counts["mechanism"] = 1
    elif "mechanism" in fams:
        print("mechanism: MLB-only — skipped at AAA")

    # --------------------------------------------------------------- deception
    # Swing disruption (depth item 10): how far a pitcher pushes each batter's
    # swing off that batter's OWN season norm — bat speed below it, contact
    # point pushed out of it. Batter quality cancels by construction (every
    # delta is vs the same batter's mean), which is the probe's design
    # (pipeline/probe_bat_tracking.py: timing disruption survives a pitch-mix
    # control on CSW%). Descriptive; the Deception+ model request is queued
    # model-lane and will gate any forecast claim.
    print(f"[{time.time() - t0:.0f}s] deception", flush=True)
    if "deception" not in fams:
        pass
    elif level == "aaa":
        print("deception: no bat tracking at AAA — skipped")
    else:
        dec_seasons = [s for s in seasons if s >= 2023]
        if dec_seasons:
            dec_csv = ",".join(str(s) for s in dec_seasons)
            dec = con.sql(f"""
                WITH norms AS (
                    SELECT season, batter, avg(bat_speed) AS bs, avg(intercept_ball_minus_batter_pos_y_inches) AS ic
                    FROM pitches_all
                    WHERE game_type = 'R' AND season IN ({dec_csv}) AND bat_speed IS NOT NULL
                    GROUP BY 1, 2 HAVING count(*) >= 100
                )
                SELECT p.pitcher, p.season, count(*) AS n,
                       avg(p.bat_speed - n.bs) AS d_bs,
                       avg(abs(p.intercept_ball_minus_batter_pos_y_inches - n.ic)) AS d_icpt
                FROM pitches_all p JOIN norms n ON n.season = p.season AND n.batter = p.batter
                WHERE p.game_type = 'R' AND p.season IN ({dec_csv}) AND p.bat_speed IS NOT NULL
                GROUP BY 1, 2 HAVING count(*) >= 200
            """).df()
            names = dict(con.sql(
                "SELECT CAST(key_mlbam AS BIGINT), name_first || ' ' || name_last FROM register "
                "WHERE TRY_CAST(key_mlbam AS BIGINT) IS NOT NULL").fetchall())
            # Deception+ (model request 2): the gated grade joins the descriptive
            # panel — SHIP verdict, results/deception_plus.json (split-half
            # .62/.82, YTY .63/.79, dR2 +.0104 over naive+Stuff+).
            plus_map = {}
            dp_fp = ROOT / "pipeline" / "results" / "deception_plus_scores.csv"
            if dp_fp.exists():
                dpsc = pd.read_csv(dp_fp)
                for r_ in dpsc.itertuples():
                    plus_map[(int(r_.pitcher), int(r_.season))] = float(r_.plus)
            dec = dec.sort_values(["season", "d_bs"]).reset_index(drop=True)
            n_dec = 0
            index_rows: dict = {}
            for s in dec_seasons:
                sub = dec[dec["season"] == s]
                sub = sub.assign(pctBs=((sub["d_bs"].rank() / len(sub)) * 100).round(1))  # low rank = drops bats more
                for r_ in sub.itertuples():
                    if player is not None and int(r_.pitcher) != player:
                        continue
                    jwrite_gz(out / "deception" / f"{int(r_.pitcher)}-{s}.json.gz", {
                        "id": str(int(r_.pitcher)), "season": s, "name": names.get(int(r_.pitcher)),
                        "nSwings": int(r_.n),
                        "batSpeedVsNorm": f(r_.d_bs, 2), "batSpeedPct": float(r_.pctBs) if pd.notna(r_.pctBs) else None,
                        "timingDisruption": f(r_.d_icpt, 1),
                        "plus": plus_map.get((int(r_.pitcher), s)),
                        "_comment": ("per-swing bat speed minus THAT batter's season mean (100+ swing norms), "
                                     "averaged over the pitcher's tracked swings (200+); timing disruption is the "
                                     "mean absolute contact-point shift off the batter's norm, inches. Descriptive."),
                    }, sort_keys=True)
                    index_rows.setdefault(str(s), []).append({
                        "id": str(int(r_.pitcher)), "name": names.get(int(r_.pitcher)), "nSwings": int(r_.n),
                        "batSpeedVsNorm": f(r_.d_bs, 2), "timingDisruption": f(r_.d_icpt, 1),
                        "plus": plus_map.get((int(r_.pitcher), s)),
                        "pctBs": float(r_.pctBs) if pd.notna(r_.pctBs) else None})
                    n_dec += 1
            jwrite(out / "deception_index.json", {
                "_comment": ("swing disruption per pitcher-season: mean bat-speed delta vs each batter's own norm "
                             "(negative = batters swing slower against him), timing disruption = mean |contact-depth "
                             "shift| in inches. 200+ tracked swings. Descriptive — probe item 4 found timing "
                             "disruption survives a pitch-mix control; the model gate is queued model-lane"),
                "seasons": {k: sorted(v, key=lambda e: (e["batSpeedVsNorm"] if e["batSpeedVsNorm"] is not None else 0))
                            for k, v in sorted(index_rows.items())},
            }, sort_keys=True)
            counts["deception_files"] = n_dec
            print(f"deception files: {n_dec}")

    # ------------------------------------------------------------------ framing
    # Framing+ (D-13 leg 1), the model-lane request the owner redirected here:
    # results/framing_plus.csv from pipeline/framing_plus.py (PREREG first,
    # catcher-grouped 5-fold, gates vs Savant PASSED — mean r .946, YTY
    # non-inferior). This family only re-publishes the scored artifact with
    # names and the referee's own numbers beside ours.
    print(f"[{time.time() - t0:.0f}s] framing", flush=True)
    if "framing" not in fams:
        pass
    elif level == "aaa":
        print("framing: MLB-only — skipped at AAA")
    else:
        fp_csv = ROOT / "pipeline" / "results" / "framing_plus.csv"
        if not fp_csv.exists():
            print("framing: results/framing_plus.csv missing — run pipeline/framing_plus.py first")
        else:
            fr = pd.read_csv(fp_csv)
            names = dict(con.sql(
                "SELECT CAST(key_mlbam AS BIGINT), name_first || ' ' || name_last FROM register "
                "WHERE TRY_CAST(key_mlbam AS BIGINT) IS NOT NULL").fetchall())
            sav = []
            for s in sorted(fr["season"].unique()):
                try:
                    tb = con.sql(f"SELECT id, rv_tot FROM lb_catcher_framing_{int(s)}").df()
                except Exception:  # noqa: BLE001
                    continue
                tb["season"] = int(s)
                sav.append(tb)
            sav_df = pd.concat(sav, ignore_index=True) if sav else pd.DataFrame(columns=["id", "rv_tot", "season"])
            sav_map = {(int(r_.id), int(r_.season)): round(float(r_.rv_tot), 2) for r_ in sav_df.itertuples()}
            zone_grids: dict = {}
            zfp = ROOT / "pipeline" / "results" / "framing_zone.parquet"
            if zfp.exists():
                zn = pd.read_parquet(zfp)
                for r_ in zn.itertuples():
                    zone_grids.setdefault((int(r_.catcher), int(r_.season)), {})[f"{int(r_.zi)}-{int(r_.xi)}"] = {
                        "r": float(r_.resid_mean), "n": int(r_.n)}
            rows_out: dict = {}
            for r_ in fr.itertuples():
                rows_out.setdefault(str(int(r_.season)), []).append({
                    "id": str(int(r_.catcher)), "name": names.get(int(r_.catcher)),
                    "taken": int(r_.taken), "strikes": float(r_.strikes_above),
                    "runs": float(r_.runs), "plus": float(r_.plus),
                    "savantRv": sav_map.get((int(r_.catcher), int(r_.season))),
                    "zone": zone_grids.get((int(r_.catcher), int(r_.season)) or {}) or None})
            jwrite(out / "framing_plus.json", {
                "_comment": ("Framing+ — strikes stolen above a catcher-grouped called-strike model's "
                             "expectation (PREREG-framing-plus.md; gates: per-season r vs Savant's board "
                             "mean .946 2021-26, YTY .602 vs their .600, location-dominant). runs value each "
                             "stolen strike at the season's empirical count run-value gap (~.15); 100/10 "
                             "scale among 2,500+ taken-pitch catchers. savantRv is THEIR board, shown beside, "
                             "positive-good on both"),
                "seasons": {k: sorted(v, key=lambda e: -e["plus"]) for k, v in sorted(rows_out.items())},
            }, sort_keys=True)
            counts["framing_rows"] = sum(len(v) for v in rows_out.values())
            print(f"framing rows: {counts['framing_rows']}")

    # ------------------------------------------------------------ defense_board
    # D-14, the league surface of the §81 range model: per fielder-position-
    # season runs (defense_fielders_v3.csv — chance model with Savant start
    # positions + hang time, game-grouped folds, AUC ~.95) beside Savant's own
    # OAA and fielding run value as reference columns. Ours labelled, theirs
    # labelled; the profile Defense tab carries the same numbers per card.
    print(f"[{time.time() - t0:.0f}s] defense_board", flush=True)
    if "defense_board" not in fams:
        pass
    elif level == "aaa":
        print("defense_board: MLB-only — skipped at AAA")
    else:
        v3_fp = ROOT / "pipeline" / "results" / "defense_fielders_v3.csv"
        if not v3_fp.exists():
            print("defense_board: defense_fielders_v3.csv missing — run pipeline/defense_mlb.py --v3 first")
        else:
            dv = pd.read_csv(v3_fp)
            dv = dv[dv["pos"].isin([3, 4, 5, 6, 7, 8, 9])]
            names = dict(con.sql(
                "SELECT CAST(key_mlbam AS BIGINT), name_first || ' ' || name_last FROM register "
                "WHERE TRY_CAST(key_mlbam AS BIGINT) IS NOT NULL").fetchall())
            sav_oaa, sav_frv = {}, {}
            for s in sorted(dv["season"].unique()):
                try:
                    tb = con.sql(f"SELECT * FROM lb_outs_above_average_{int(s)}").df()
                except Exception:  # noqa: BLE001
                    tb = pd.DataFrame()
                cols = {c.lower(): c for c in tb.columns}
                idc = cols.get("player_id") or cols.get("id")
                posc = cols.get("pos") or cols.get("position") or cols.get("primary_pos_formatted")
                if idc and posc and cols.get("outs_above_average"):
                    tbr = tb[[idc, posc, cols["outs_above_average"]]].copy()
                    tbr.columns = ["id", "pos", "oaa"]
                    for r_ in tbr.itertuples():
                        sav_oaa[(int(r_.id), str(r_.pos).upper(), int(s))] = round(float(r_.oaa), 1)
                try:
                    fr = con.sql(f"SELECT * FROM lb_fielding_run_value_{int(s)}").df()
                except Exception:  # noqa: BLE001
                    fr = pd.DataFrame()
                fcols = {c.lower(): c for c in fr.columns}
                fid = fcols.get("player_id") or fcols.get("id")
                if fid and (fcols.get("fielding_run_value") or fcols.get("total_runs")):
                    frv_col = fcols.get("fielding_run_value") or fcols["total_runs"]
                    frr = fr[[fid, frv_col]].copy()
                    frr.columns = ["id", "frv"]
                    for r_ in frr.itertuples():
                        sav_frv[(int(r_.id), int(s))] = round(float(r_.frv), 1)
            POS_LABEL = {3: "1B", 4: "2B", 5: "3B", 6: "SS", 7: "LF", 8: "CF", 9: "RF"}
            SAV_OF = {"LF", "CF", "RF", "OF"}
            rows_out2: dict = {}
            for r_ in dv.itertuples():
                if r_.chances < 30:
                    continue
                grp = "OF" if r_.pos >= 7 else "IF"
                pl = POS_LABEL[int(r_.pos)]
                soaa = None
                for sp in ([pl] + (["OF"] if grp == "OF" else [])):
                    v0 = sav_oaa.get((int(r_.mlbam), sp, int(r_.season)))
                    if v0 is not None:
                        soaa = v0
                        break
                rows_out2.setdefault(str(int(r_.season)), []).append({
                    "id": str(int(r_.mlbam)), "name": names.get(int(r_.mlbam)),
                    "pos": pl, "group": grp, "chances": round(float(r_.chances), 0),
                    "runs": round(float(r_.runs), 1), "oaaOurs": round(float(r_.oaa), 1),
                    "savOaa": soaa, "savFrv": sav_frv.get((int(r_.mlbam), int(r_.season)))})
            jwrite(out / "defense_index.json", {
                "_comment": ("league range board: §81's chance model (Savant start positions + hang time, "
                             "game-grouped folds, AUC .94-.95 per season) — runs vs an average fielder at the "
                             "position and our chance-weighted OAA-equivalent; Savant's OAA and fielding run "
                             "value sit beside as reference columns. 30+ chances; profile Defense tab carries "
                             "the per-card version"),
                "seasons": {k: sorted(v, key=lambda e: -e["runs"]) for k, v in sorted(rows_out2.items())},
            }, sort_keys=True)
            counts["defense_board_rows"] = sum(len(v) for v in rows_out2.values())
            print(f"defense board rows: {counts['defense_board_rows']}")

    # ------------------------------------------------------------------ swing
    # Hitter swing profiles from bat tracking (depth list item 1). MLB-only:
    # AAA Hawk-Eye carries no bat data (0 of 1.35M rows, checked 2026-10-28),
    # so this family is skipped at --level aaa. Sources: the per-pitch tracked
    # swings in pitches_all (bat_speed IS NOT NULL, 2023+, ~100% of swings
    # carry speed/length/attack-angle/tilt/contact depth) for the distributions
    # and splits, plus Savant's own aggregates — lb_bat_tracking (swords,
    # squared-up / blast / hard-swing rates, competitive-swing counts) and
    # lb_swingpath (path tilt, ideal attack-angle rate, contact depth, 2025+)
    # — so Savant-named numbers match their leaderboard exactly. Descriptive
    # throughout; the gate is 100 tracked swings (the probe's MIN_SWINGS).
    print(f"[{time.time() - t0:.0f}s] swing", flush=True)
    if "swing" not in fams:
        pass
    elif level == "aaa":
        print("swing: no bat tracking at AAA — skipped")
    else:
        sw_seasons = [s for s in seasons if s >= 2023]
        if not sw_seasons:
            print("swing: no 2023+ seasons in range — skipped")
        else:
            # Same region constants as the zone-mix family (heart/shadow/chase/
            # waste on the standardised zone) so the two surfaces never disagree.
            sw_zone_sql = ("CASE WHEN abs(plate_x) <= 0.558 AND plate_z BETWEEN 1.833 AND 3.500 THEN 'heart' "
                           "WHEN abs(plate_x) <= 1.108 AND plate_z BETWEEN 1.166 AND 4.000 THEN 'shadow' "
                           "WHEN abs(plate_x) <= 1.666 AND plate_z BETWEEN 0.500 AND 4.500 THEN 'chase' "
                           "ELSE 'waste' END")
            sw_df = con.sql(f"""
                SELECT batter, season, stand, bat_speed, swing_length,
                       attack_angle, swing_path_tilt,
                       intercept_ball_minus_batter_pos_y_inches AS icpt_y,
                       description, balls, strikes, p_throws, release_speed,
                       {site_case_sql()} AS ptype, {sw_zone_sql} AS zreg
                FROM pitches_all
                WHERE game_type = 'R' AND season IN ({",".join(str(s) for s in sw_seasons)})
                  AND batter IS NOT NULL AND bat_speed IS NOT NULL
            """).df()
            sw_df["whiff"] = sw_df["description"].isin(WHIFF)
            sw_df["velo_band"] = pd.cut(sw_df["release_speed"], [0, 85, 90, 95, 200],
                                        labels=["v85", "v85-90", "v90-95", "v95+"])

            sw_agg = (sw_df.groupby(["batter", "season"], sort=True)
                      .agg(n=("bat_speed", "size"),
                           avgBatSpeed=("bat_speed", "mean"),
                           bsP90=("bat_speed", lambda s: float(s.quantile(0.9))),
                           swingLength=("swing_length", "mean"),
                           attackAngle=("attack_angle", "mean"),
                           pathTilt=("swing_path_tilt", "mean"),
                           contactDepth=("icpt_y", "mean"),
                           nWhiff=("whiff", "sum"))
                      .reset_index())
            sw_agg["whiffPerSwing"] = 100 * sw_agg["nWhiff"] / sw_agg["n"]

            # Savant's own aggregates, joined per season (their avg_bat_speed is
            # the cross-check for ours; their swords/rates are definitionally
            # theirs and we do not recompute them).
            sw_lb = []
            for s in sw_seasons:
                try:
                    t = con.sql(f"SELECT * FROM lb_bat_tracking_{s}").df()
                except Exception:  # noqa: BLE001
                    print(f"swing: lb_bat_tracking_{s} missing — skipped")
                    continue
                t = t[["id", "swings_competitive", "percent_swings_competitive", "avg_bat_speed",
                       "hard_swing_rate", "squared_up_per_swing", "blast_per_swing",
                       "swords", "whiff_per_swing", "batter_run_value"]].copy()
                t["season"] = s
                sw_lb.append(t)
            lb = pd.concat(sw_lb, ignore_index=True) if sw_lb else pd.DataFrame(
                columns=["id", "season", "swings_competitive", "percent_swings_competitive", "avg_bat_speed",
                         "hard_swing_rate", "squared_up_per_swing", "blast_per_swing",
                         "swords", "whiff_per_swing", "batter_run_value"])
            lb["swordRate"] = 100 * lb["swords"] / lb["swings_competitive"].where(
                lb["swings_competitive"] > 0)

            sp = pd.DataFrame()
            sp_parts = []
            for s in sw_seasons:
                try:
                    t = con.sql(f"SELECT * FROM lb_swingpath_{s}").df()
                except Exception:  # noqa: BLE001
                    continue
                t = t[["id", "side", "swing_tilt", "attack_angle", "ideal_attack_angle_rate",
                       "avg_intercept_y_vs_plate", "competitive_swings"]].copy()
                t["season"] = s
                sp_parts.append(t)
            if sp_parts:
                sp = pd.concat(sp_parts, ignore_index=True)

            qual = sw_agg[sw_agg["n"] >= SWING_MIN_SWINGS].copy()

            def sw_pct(series: pd.Series, higher_better: bool = True) -> pd.Series:
                """Percentile among qualified hitters, 0–100 (higher = more of the stat)."""
                if len(series) < 2:
                    return pd.Series(dtype=float)
                ranked = series if higher_better else -series
                return (100 * (ranked.rank(method="average") - 1) / (len(series) - 1)).round(1)

            for col, hb in (("avgBatSpeed", True), ("bsP90", True), ("swingLength", True),
                            ("attackAngle", True), ("whiffPerSwing", False)):
                qual[f"{col}Pct"] = sw_pct(qual[col], hb)
            # Swords and the Savant rate metrics rank only where the lb table
            # has the player-season (join keeps NaN, UI shows them only with data).
            lb_qual = lb.merge(qual[["batter", "season"]].rename(columns={"batter": "id"}),
                               on=["id", "season"], how="inner")
            for col in ("swordRate", "squared_up_per_swing", "blast_per_swing"):
                q = lb_qual[col].reset_index(drop=True)
                if len(q):
                    lb_qual[f"{col}Pct"] = sw_pct(q, True).values
                else:
                    lb_qual[f"{col}Pct"] = pd.Series(dtype=float)
            sw_pcols = [c for c in lb_qual.columns if c.endswith("Pct")]
            lb_pct = (lb_qual.set_index(["id", "season"])[sw_pcols]
                      if sw_pcols and len(lb_qual) else pd.DataFrame())

            def _sw_split(gdf: pd.DataFrame, by: str, min_n: int = 20) -> dict:
                out: dict = {}
                for key, sub in gdf.groupby(by, sort=True, observed=True):
                    row = {"n": int(len(sub)),
                           "avgBatSpeed": f(sub["bat_speed"].mean(), 1),
                           "swingLength": f(sub["swing_length"].mean(), 2),
                           "whiffPct": f(100 * sub["whiff"].mean(), 1)}
                    if len(sub) >= min_n:
                        out[str(key)] = row
                return out

            n_swing = 0
            index_rows: dict = {}
            for pid, grp in sw_df.groupby("batter", sort=True):
                if player is not None and int(pid) != player:
                    continue
                trend = []
                arows = grp.merge(sw_agg[sw_agg["batter"] == pid][
                    ["season", "n", "avgBatSpeed", "swingLength", "attackAngle", "pathTilt",
                     "whiffPerSwing"]], on="season")
                for t in arows.drop_duplicates("season").itertuples():
                    if t.n >= 50:
                        trend.append({"season": int(t.season), "n": int(t.n),
                                      "avgBatSpeed": f(t.avgBatSpeed, 1),
                                      "swingLength": f(t.swingLength, 2),
                                      "attackAngle": f(getattr(t, "attackAngle", float("nan")), 1),
                                      "pathTilt": f(getattr(t, "pathTilt", float("nan")), 1),
                                      "whiffPerSwing": f(t.whiffPerSwing, 1)})
                qrows = qual[qual["batter"] == pid]
                for a in qrows.itertuples():
                    season = int(a.season)
                    sub = grp[grp["season"] == season]
                    side = sub["stand"].mode()
                    side = str(side.iloc[0]) if len(side) else None
                    bsx, bsy, bs_meta = sw_kde_curve(sub["bat_speed"].tolist(), 55, 90, bw_min=0.5)
                    slx, sly, sl_meta = sw_kde_curve(sub["swing_length"].clip(4.5, 10.5).tolist(),
                                                   4.5, 10.5, bw_min=0.15)
                    lbrow = lb[(lb["id"] == pid) & (lb["season"] == season)]
                    lbdoc: dict = {}
                    if len(lbrow):
                        b0 = lbrow.iloc[0]
                        lbdoc = {
                            "competitiveSwings": int(b0["swings_competitive"]) if pd.notna(b0["swings_competitive"]) else None,
                            "pctCompetitive": f(100 * b0["percent_swings_competitive"], 1) if pd.notna(b0["percent_swings_competitive"]) else None,
                            # Savant averages COMPETITIVE swings; our avgBatSpeed covers all
                            # tracked swings — both shown, glossary explains the difference.
                            "savantAvgBatSpeed": f(b0["avg_bat_speed"], 1) if pd.notna(b0["avg_bat_speed"]) else None,
                            "swords": int(b0["swords"]) if pd.notna(b0["swords"]) else None,
                            "swordRate": f(b0["swordRate"], 2) if pd.notna(b0["swordRate"]) else None,
                            "hardSwingRate": f(100 * b0["hard_swing_rate"], 1) if pd.notna(b0["hard_swing_rate"]) else None,
                            "squaredUpPerSwing": f(100 * b0["squared_up_per_swing"], 1) if pd.notna(b0["squared_up_per_swing"]) else None,
                            "blastPerSwing": f(100 * b0["blast_per_swing"], 1) if pd.notna(b0["blast_per_swing"]) else None,
                            "savantRunValue": f(b0["batter_run_value"], 1) if pd.notna(b0["batter_run_value"]) else None,
                        }
                    spdoc = None
                    if len(sp):
                        sprow = sp[(sp["id"] == pid) & (sp["season"] == season) & (sp["side"] == side)]
                        if len(sprow):
                            s0 = sprow.iloc[0]
                            spdoc = {"idealAttackAngleRate": f(100 * s0["ideal_attack_angle_rate"], 1)
                                     if pd.notna(s0["ideal_attack_angle_rate"]) else None,
                                     "interceptVsPlate": f(s0["avg_intercept_y_vs_plate"], 1)
                                     if pd.notna(s0["avg_intercept_y_vs_plate"]) else None}
                    pcts = {"n": int(len(qual[(qual["season"] == season)])),
                            "avgBatSpeed": a.avgBatSpeedPct, "bsP90": a.bsP90Pct,
                            "swingLength": a.swingLengthPct, "attackAngle": a.attackAnglePct,
                            "whiffPerSwing": a.whiffPerSwingPct}
                    for key in ("swordRate", "squared_up_per_swing", "blast_per_swing"):
                        if (pid, season) in lb_pct.index:
                            v = lb_pct.loc[(pid, season)].get(f"{key}Pct")
                            pcts[key] = float(v) if pd.notna(v) else None
                    doc = {
                        "id": str(pid), "season": season, "side": side,
                        "n": int(a.n),
                        "summary": {
                            "avgBatSpeed": f(a.avgBatSpeed, 1), "batSpeedP90": f(a.bsP90, 1),
                            "swingLength": f(a.swingLength, 2),
                            "attackAngle": f(a.attackAngle, 1), "pathTilt": f(a.pathTilt, 1),
                            "contactDepth": f(a.contactDepth, 1),
                            "whiffPerSwing": f(a.whiffPerSwing, 1),
                            **lbdoc,
                        },
                        "savant": spdoc,
                        "percentiles": pcts,
                        "dist": {
                            "batSpeed": {"x": [f(v, 1) for v in bsx], "y": bsy,
                                         "meta": bs_meta, "rug": sw_stride(
                                             sorted(sub["bat_speed"].round(1).tolist()), 60)},
                            "swingLength": {"x": [f(v, 1) for v in slx], "y": sly, "meta": sl_meta},
                        },
                        "byZoneRegion": _sw_split(sub, "zreg"),
                        "byPitchType": _sw_split(sub, "ptype"),
                        "byCount": _sw_split(sub.assign(
                            cnt=sub["balls"].astype(int).astype(str) + "-" + sub["strikes"].astype(int).astype(str)), "cnt"),
                        "byVeloBand": _sw_split(sub, "velo_band"),
                        "byHand": {"vsL": _sw_split(sub[sub["p_throws"] == "L"], "p_throws").get("L"),
                                   "vsR": _sw_split(sub[sub["p_throws"] == "R"], "p_throws").get("R")},
                        "trend": sorted(trend, key=lambda e: e["season"]),
                    }
                    jwrite_gz(out / "swing" / f"{pid}-{season}.json.gz", _clean(doc), sort_keys=True)
                    row = {"id": str(pid), "n": int(a.n),
                           "avgBatSpeed": f(a.avgBatSpeed, 1), "batSpeedP90": f(a.bsP90, 1),
                           "swingLength": f(a.swingLength, 2), "attackAngle": f(a.attackAngle, 1),
                           "contactDepth": f(a.contactDepth, 1),
                           "whiffPerSwing": f(a.whiffPerSwing, 1),
                           "avgBatSpeedPct": a.avgBatSpeedPct, "whiffPerSwingPct": a.whiffPerSwingPct}
                    if lbdoc:
                        row.update({"swords": lbdoc["swords"], "swordRate": lbdoc["swordRate"],
                                    "squaredUpPerSwing": lbdoc["squaredUpPerSwing"],
                                    "blastPerSwing": lbdoc["blastPerSwing"],
                                    "hardSwingRate": lbdoc["hardSwingRate"]})
                    index_rows.setdefault(str(season), []).append(row)
                    n_swing += 1
            jwrite(out / "swing_index.json", {
                "_comment": ("hitter swing profiles per season (bat tracking, 100+ tracked swings); "
                             "names/teams join from hitters.json on the board; Savant fields keep "
                             "Savant definitions (swords, squared-up, blast, competitive swings)"),
                "minSwings": SWING_MIN_SWINGS,
                "seasons": {k: sorted(v, key=lambda rw: -(rw.get("avgBatSpeedPct") or -1))
                            for k, v in sorted(index_rows.items())},
            }, sort_keys=True)
            counts["swing_files"] = n_swing
            print(f"swing files: {n_swing}")

    # ------------------------------------------------------------------- load
    # Fatigue surfaces (depth list item 3): velo and outcomes by times through
    # the order, by rest days, and velo by pitch number within a start. All
    # from columns already on every pitch row (n_thruorder_pitcher,
    # pitcher_days_since_prev_game; the pitch index within a start is a window
    # count), AAA included. Descriptive; no model grades involved.
    print(f"[{time.time() - t0:.0f}s] load", flush=True)
    if "load" not in fams:
        pass
    else:
        # the WHIFF/SWING tuples as SQL literals (foul_tip counts as a whiff,
        # matching the site convention)
        ld_whiff = "('swinging_strike', 'swinging_strike_blocked', 'foul_tip')"
        ld_swing = ("('swinging_strike', 'swinging_strike_blocked', 'foul', 'foul_tip', "
                    "'foul_bunt', 'missed_bunt', 'bunt_foul_tip', 'hit_into_play')")
        ld_rest_case = ("CASE WHEN rest <= 3 THEN '0-3' WHEN rest = 4 THEN '4' "
                        "WHEN rest = 5 THEN '5' WHEN rest = 6 THEN '6' ELSE '7+' END")
        # one PA row per (game, pitcher, at-bat): the TTO ordinal as of the PA,
        # and the PA-ending event (events populates only on the final pitch)
        con.execute(f"""
            CREATE OR REPLACE TEMP VIEW ld_pa AS
            SELECT game_pk, pitcher, at_bat_number, season,
                   max(n_thruorder_pitcher) AS tto, max(events) AS ev
            FROM pitches_all
            WHERE game_type = 'R' AND season IN ({season_list})
              AND pitcher IS NOT NULL AND n_thruorder_pitcher IS NOT NULL
            GROUP BY 1, 2, 3, 4
        """)
        con.execute(f"""
            CREATE OR REPLACE TEMP VIEW ld_game AS
            SELECT game_pk, pitcher, season,
                   min(pitcher_days_since_prev_game) AS rest, count(*) AS np
            FROM pitches_all
            WHERE game_type = 'R' AND season IN ({season_list}) AND pitcher IS NOT NULL
            GROUP BY 1, 2, 3
        """)
        # PA outcomes by TTO ordinal (4 folds into 4+)
        ld_tto_pa = con.sql(f"""
            SELECT pitcher, season, CASE WHEN tto >= 4 THEN 4 ELSE tto END AS tto,
                   count(*) AS pa,
                   count(*) FILTER (WHERE ev IN ('strikeout', 'strikeout_double_play')) AS k,
                   count(*) FILTER (WHERE ev IN ('walk', 'intent_walk')) AS bb
            FROM ld_pa GROUP BY 1, 2, 3
        """).df()
        # pitch-level rates by TTO ordinal (joined to the PA's ordinal)
        ld_tto_p = con.sql(f"""
            SELECT p.pitcher, p.season, CASE WHEN t.tto >= 4 THEN 4 ELSE t.tto END AS tto,
                   count(*) AS np, avg(p.release_speed) AS velo,
                   avg(CASE WHEN p.pitch_type = 'FF' THEN p.release_speed END) AS ffvelo,
                   count(*) FILTER (WHERE p.description IN {ld_swing}) AS swings,
                   count(*) FILTER (WHERE p.description IN {ld_whiff}) AS whiffs,
                   avg(p.launch_speed) AS ev,
                   sum(p.delta_pitcher_run_exp) AS rv
            FROM pitches_all p
            JOIN ld_pa t ON p.game_pk = t.game_pk AND p.pitcher = t.pitcher
                        AND p.at_bat_number = t.at_bat_number AND p.season = t.season
            WHERE p.game_type = 'R' AND p.season IN ({season_list})
            GROUP BY 1, 2, 3
        """).df()
        # velo/whiff/runs by rest days (bucketed on the outing's rest)
        ld_rest = con.sql(f"""
            SELECT g.pitcher, g.season, {ld_rest_case} AS rb,
                   count(DISTINCT g.game_pk) AS outings,
                   avg(p.release_speed) AS velo,
                   count(*) FILTER (WHERE p.description IN {ld_swing}) AS swings,
                   count(*) FILTER (WHERE p.description IN {ld_whiff}) AS whiffs,
                   sum(p.delta_pitcher_run_exp) AS rv, count(*) AS np
            FROM pitches_all p JOIN ld_game g
              ON p.game_pk = g.game_pk AND p.pitcher = g.pitcher AND p.season = g.season
            WHERE p.game_type = 'R' AND p.season IN ({season_list})
              AND g.rest IS NOT NULL
            GROUP BY 1, 2, 3
        """).df()
        # velo by pitch number within the start (FF carries the fade signal)
        ld_fade = con.sql(f"""
            SELECT pitcher, season,
                   CASE WHEN k <= 15 THEN '01-15' WHEN k <= 30 THEN '16-30'
                        WHEN k <= 45 THEN '31-45' WHEN k <= 60 THEN '46-60'
                        WHEN k <= 75 THEN '61-75' WHEN k <= 90 THEN '76-90'
                        ELSE '91+' END AS bucket,
                   count(*) AS np, avg(release_speed) AS velo,
                   count(*) FILTER (WHERE pitch_type = 'FF') AS nff,
                   avg(CASE WHEN pitch_type = 'FF' THEN release_speed END) AS ffvelo
            FROM (
                SELECT pitcher, season, game_pk, at_bat_number, pitch_number,
                       release_speed, pitch_type,
                       row_number() OVER (PARTITION BY game_pk, pitcher
                                          ORDER BY at_bat_number, pitch_number) AS k
                FROM pitches_all
                WHERE game_type = 'R' AND season IN ({season_list})
                  AND release_speed IS NOT NULL
            ) GROUP BY 1, 2, 3
        """).df()
        # league TTO baselines per season (the board's context rows)
        ld_lg = con.sql(f"""
            SELECT t.season, CASE WHEN t.tto >= 4 THEN 4 ELSE t.tto END AS tto,
                   count(*) AS pa,
                   count(*) FILTER (WHERE t.ev IN ('strikeout', 'strikeout_double_play')) AS k,
                   count(*) FILTER (WHERE t.ev IN ('walk', 'intent_walk')) AS bb,
                   avg(p.release_speed) AS velo,
                   count(*) FILTER (WHERE p.description IN {ld_swing}) AS swings,
                   count(*) FILTER (WHERE p.description IN {ld_whiff}) AS whiffs,
                   sum(p.delta_pitcher_run_exp) AS rv, count(*) AS np
            FROM pitches_all p
            JOIN ld_pa t ON p.game_pk = t.game_pk AND p.pitcher = t.pitcher
                        AND p.at_bat_number = t.at_bat_number AND p.season = t.season
            WHERE p.game_type = 'R' AND p.season IN ({season_list})
            GROUP BY 1, 2
        """).df()

        n_games = con.sql("SELECT pitcher, season, count(*) AS games FROM ld_game GROUP BY 1, 2").df().set_index(["pitcher", "season"])["games"]
        np_total = ld_tto_p.groupby(["pitcher", "season"])["np"].sum()

        def ld_tto_cell(pa_row, p_row):
            pa = int(pa_row["pa"]) if pa_row is not None else 0
            np_, swings = (int(p_row["np"]), int(p_row["swings"])) if p_row is not None else (0, 0)
            cell = {"pa": pa,
                    "kPct": f(100 * pa_row["k"] / pa, 1) if pa_row is not None and pa else None,
                    "bbPct": f(100 * pa_row["bb"] / pa, 1) if pa_row is not None and pa else None}
            if p_row is not None:
                cell.update({
                    "velo": f(p_row["velo"], 1),
                    "fbVelo": f(p_row["ffvelo"], 1) if pd.notna(p_row["ffvelo"]) else None,
                    "whiffPct": f(100 * p_row["whiffs"] / swings, 1) if swings else None,
                    "ev": f(p_row["ev"], 1) if pd.notna(p_row["ev"]) else None,
                    "runsPer100": f(100 * p_row["rv"] / np_, 2) if np_ else None,
                })
            return cell

        ld_tto_pa_g = ld_tto_pa.set_index(["pitcher", "season", "tto"])
        ld_tto_p_g = ld_tto_p.set_index(["pitcher", "season", "tto"])
        ld_rest_g = ld_rest.set_index(["pitcher", "season", "rb"])
        ld_fade_g = ld_fade.set_index(["pitcher", "season", "bucket"])
        TTO_ORDER = [1, 2, 3, 4]
        FADE_ORDER = ["01-15", "16-30", "31-45", "46-60", "61-75", "76-90", "91+"]
        league_out: dict = {}
        lg_g = ld_lg.set_index(["season", "tto"])
        for s in sorted(ld_lg["season"].unique()):
            cells = {}
            for tto in TTO_ORDER:
                if (s, tto) in lg_g.index:
                    lw = lg_g.loc[(s, tto)]
                    cells[str(tto)] = {"pa": int(lw["pa"]),
                                       "kPct": f(100 * lw["k"] / lw["pa"], 1) if lw["pa"] else None,
                                       "bbPct": f(100 * lw["bb"] / lw["pa"], 1) if lw["pa"] else None,
                                       "velo": f(lw["velo"], 1),
                                       "whiffPct": f(100 * lw["whiffs"] / lw["swings"], 1) if lw["swings"] else None,
                                       "runsPer100": f(100 * lw["rv"] / lw["np"], 2) if lw["np"] else None}
            league_out[str(int(s))] = cells

        n_load = 0
        index_rows: dict = {}
        for (pid, season), _ in np_total.groupby(level=[0, 1]):
            if player is not None and int(pid) != player:
                continue
            if int(np_total.loc[[(pid, season)]].sum()) < LOAD_MIN_PITCHES:
                continue
            tto_doc = {}
            for tto in TTO_ORDER:
                pa_row = ld_tto_pa_g.loc[(pid, season, tto)] if (pid, season, tto) in ld_tto_pa_g.index else None
                p_row = ld_tto_p_g.loc[(pid, season, tto)] if (pid, season, tto) in ld_tto_p_g.index else None
                if pa_row is None and p_row is None:
                    continue
                tto_doc[str(tto)] = ld_tto_cell(pa_row, p_row)
            rest_doc = {}
            for rb in ("0-3", "4", "5", "6", "7+"):
                if (pid, season, rb) in ld_rest_g.index:
                    rr = ld_rest_g.loc[(pid, season, rb)]
                    rest_doc[rb] = {"outings": int(rr["outings"]),
                                    "velo": f(rr["velo"], 1),
                                    "whiffPct": f(100 * rr["whiffs"] / rr["swings"], 1) if rr["swings"] else None,
                                    "runsPer100": f(100 * rr["rv"] / rr["np"], 2) if rr["np"] else None}
            fade_doc = []
            for bkt in FADE_ORDER:
                if (pid, season, bkt) in ld_fade_g.index:
                    fr = ld_fade_g.loc[(pid, season, bkt)]
                    fade_doc.append({"bucket": bkt, "n": int(fr["np"]), "velo": f(fr["velo"], 1),
                                     "nFf": int(fr["nff"]),
                                     "ffVelo": f(fr["ffvelo"], 1) if pd.notna(fr["ffvelo"]) else None})

            def tget(key, field):
                cell = tto_doc.get(key)
                return cell.get(field) if cell else None

            def drop(field, min_pa=30):
                c1, c3 = tto_doc.get("1"), tto_doc.get("3")
                if not c1 or not c3 or c1.get("pa", 0) < min_pa or c3.get("pa", 0) < min_pa:
                    return None, None, None
                a1, a3 = c1.get(field), c3.get(field)
                if a1 is None or a3 is None:
                    return a1, a3, None
                return a1, a3, f(round(a1 - a3, 1), 1)  # positive = a decline by T3

            veloT1, veloT3, veloDrop = drop("velo")
            whiffT1, whiffT3, whiffDrop = drop("whiffPct")
            kT1, kT3, kDrop = drop("kPct")
            ff01 = next((x["ffVelo"] for x in fade_doc if x["bucket"] == "01-15"), None)
            ff76 = next((x["ffVelo"] for x in fade_doc if x["bucket"] == "76-90"), None)
            n01 = next((x["nFf"] for x in fade_doc if x["bucket"] == "01-15"), 0)
            n76 = next((x["nFf"] for x in fade_doc if x["bucket"] == "76-90"), 0)
            ffFade = f(ff01 - ff76, 1) if (ff01 is not None and ff76 is not None and n01 >= 30 and n76 >= 30) else None
            doc = {
                "id": str(pid), "season": int(season),
                "nPitches": int(np_total.loc[[(pid, season)]].sum()),
                "nGames": int(n_games.get((pid, season), 0)),
                "tto": tto_doc, "rest": rest_doc, "fade": fade_doc,
                "summary": {"veloT1": veloT1, "veloT3": veloT3, "veloDropTto": veloDrop,
                            "whiffT1": whiffT1, "whiffT3": whiffT3, "whiffDropTto": whiffDrop,
                            "kT1": kT1, "kT3": kT3, "kDropTto": kDrop, "ffFade75": ffFade},
            }
            jwrite_gz(out / "load" / f"{pid}-{season}.json.gz", _clean(doc), sort_keys=True)
            index_rows.setdefault(str(int(season)), []).append({
                "id": str(pid), "nPitches": doc["nPitches"], "nGames": doc["nGames"],
                "veloT1": veloT1, "veloT3": veloT3, "veloDropTto": veloDrop,
                "whiffT1": whiffT1, "whiffT3": whiffT3, "whiffDropTto": whiffDrop,
                "kT1": kT1, "kT3": kT3, "kDropTto": kDrop, "ffFade75": ffFade,
            })
            n_load += 1
        jwrite(out / "load_index.json", {
            "_comment": ("fatigue surfaces per pitcher-season (TTO velo/outcome drops, rest-day splits, "
                         "FF velo fade by pitch number); league baselines under 'league'. Descriptive — "
                         "drops need 30+ PA in both the 1st and 3rd time through, fade 30+ FF in both buckets"),
            "minPitches": LOAD_MIN_PITCHES,
            "league": league_out,
            "seasons": {k: sorted(v, key=lambda rw: -(rw.get("veloDropTto") or -99))
                        for k, v in sorted(index_rows.items())},
        }, sort_keys=True)
        counts["load_files"] = n_load
        print(f"load files: {n_load}")

    # ------------------------------------------------------------------ draft
    # Draft + transactions surfaces (depth item 5), from pipeline/amateur_fetch.py
    # outputs: hit-rate tables (Pipeline rank buckets and draft rounds joined to
    # MLB debut dates) and per-player roster-move timelines. MLB only; every
    # join is a public-source descriptive read — no model claims.
    print(f"[{time.time() - t0:.0f}s] pitches", flush=True)
    if "pitches" in fams:
        counts["pitch_files"] = bake_pitches(con, out, seasons, site_case_sql(), level)
    print(f"[{time.time() - t0:.0f}s] draft", flush=True)
    if "draft" not in fams:
        pass
    elif level == "aaa":
        print("draft: MLB-only family — skipped at AAA")
    else:
        dr_fp = ROOT / "data" / "milb" / "draft.json"
        ppl_fp = ROOT / "data" / "milb" / "people.parquet"
        src_fp = ROOT / "data" / "milb" / "prospects.json"
        tx_fp = ROOT / "data" / "milb" / "transactions.parquet"
        if not (dr_fp.exists() and ppl_fp.exists() and src_fp.exists()):
            print("draft: data/milb draft.json/people.parquet/prospects.json missing — run pipeline/amateur_fetch.py first")
        else:
            debut = {}
            ppl = pd.read_parquet(ppl_fp)
            for prow in ppl.itertuples():
                if pd.notna(getattr(prow, "debut", None)):
                    debut[int(prow.id)] = str(prow.debut)[:10]
            draft_picks = [dp for picks in json.loads(dr_fp.read_text()).values() for dp in picks if dp.get("id")]
            dr_hits = []
            for dp in draft_picks:
                db = debut.get(int(dp["id"]))
                dr_hits.append({"year": dp["year"], "round": str(dp["round"]), "pick": dp["pick"],
                                "reached": db is not None,
                                "bonus": dp.get("bonus")})

            def round_bucket(rnd: str) -> str:
                if rnd in ("1", "1S"):
                    return "1st round (incl. supp)" if rnd == "1S" else "1st round"
                if rnd in ("2", "2S"):
                    return "2nd round"
                if rnd in ("3", "3S", "CB", "PB", "A", "B", "C"):
                    return "3rd + comp/prospect rounds"
                try:
                    ri = int(rnd)
                except ValueError:
                    return "other"
                if ri <= 5:
                    return f"rounds 4–5"
                if ri <= 10:
                    return "rounds 6–10"
                return "round 11+"

            by_round: dict = {}
            for h in dr_hits:
                rb = round_bucket(h["round"])
                c = by_round.setdefault(rb, {"n": 0, "reached": 0})
                c["n"] += 1
                c["reached"] += 1 if h["reached"] else 0
            rounds_out = [{"bucket": rb, "n": c["n"], "reached": c["reached"],
                           "pct": f(100 * c["reached"] / c["n"], 1) if c["n"] else None}
                          for rb, c in sorted(by_round.items(), key=lambda kv: -kv[1]["n"])]

            # Pipeline rank buckets: each (year, rank) row counts toward that
            # year's bucket — list quality, not player counting. Time-to-MLB
            # only for debuts after the list year.
            raw_ranks = json.loads(src_fp.read_text())
            rank_rows = []
            for y, lists in raw_ranks.items():
                for r0 in lists.get("top100", []) or []:
                    if r0.get("id"):
                        rank_rows.append({"year": int(y), "rank": int(r0["rank"]), "id": int(r0["id"])})
            rank_hits = []
            for rk in rank_rows:
                db = debut.get(rk["id"])
                ttm = None
                if db:
                    dy = int(db[:4])
                    if dy >= rk["year"]:
                        ttm = dy - rk["year"]
                rank_hits.append({"year": rk["year"], "rank": rk["rank"], "reached": db is not None, "ttm": ttm})

            def rank_bucket(rank: int) -> str:
                if rank <= 10:
                    return "top 10"
                if rank <= 25:
                    return "11–25"
                if rank <= 50:
                    return "26–50"
                return "51–100"

            by_rank: dict = {}
            for h in rank_hits:
                rb = rank_bucket(h["rank"])
                c = by_rank.setdefault(rb, {"n": 0, "reached": 0, "ttms": []})
                c["n"] += 1
                c["reached"] += 1 if h["reached"] else 0
                if h["ttm"] is not None:
                    c["ttms"].append(h["ttm"])
            order = ["top 10", "11–25", "26–50", "51–100"]
            ranks_out = [{"bucket": rb,
                          "n": by_rank[rb]["n"], "reached": by_rank[rb]["reached"],
                          "pct": f(100 * by_rank[rb]["reached"] / by_rank[rb]["n"], 1) if by_rank[rb]["n"] else None,
                          "medianYearsToMlb": sorted(by_rank[rb]["ttms"])[len(by_rank[rb]["ttms"]) // 2]
                          if by_rank[rb]["ttms"] else None}
                         for rb in order if rb in by_rank]
            # by rank year, for the trend read
            by_year_out = []
            for y in sorted({h["year"] for h in rank_hits}):
                sub = [h for h in rank_hits if h["year"] == y]
                by_year_out.append({"year": y, "n": len(sub),
                                    "reachedPct": f(100 * sum(1 for h in sub if h["reached"]) / len(sub), 1)})
            jwrite(out / "draft" / "hit_rates.json", {
                "_comment": ("descriptive joins of public sources: Pipeline top-100 rank buckets and draft "
                             "rounds vs MLB debut (statsapi people). List-year rows count per year (list "
                             "quality); time-to-MLB counts debuts after the list year only"),
                "rankBuckets": ranks_out, "rankByYear": by_year_out, "draftRounds": rounds_out,
            }, sort_keys=True)

            n_tx = 0
            if tx_fp.exists():
                tx = pd.read_parquet(tx_fp)
                tx["date"] = tx["date"].astype(str)
                for pid, grp in tx.groupby("id"):
                    if player is not None and int(pid) != player:
                        continue
                    rows_out = sorted(
                        [{"date": d, "type": ty, "desc": ds, "from": fm, "to": to}
                         for d, ty, ds, fm, to in zip(grp["date"], grp["type"], grp["desc"], grp["from"], grp["to"])],
                        key=lambda e: e["date"], reverse=True)
                    jwrite_gz(out / "transactions" / f"{pid}.json.gz",
                              {"id": str(pid), "rows": rows_out}, sort_keys=True)
                    n_tx += 1
            counts["transaction_files"] = n_tx
            print(f"hit-rate tables written; transaction files: {n_tx}")

    # -------------------------------------------------------------------- wpa
    # Win probability (depth list item 6): per-pitch delta_home_win_exp, home-
    # team framed, 100% coverage 2020+ at both levels. A PA's batting-team
    # swing is the telescoping per-PA sum x side (Bot +1, Top -1) — that equals
    # the event's win-prob shift exactly. Descriptive: WPA prices context, not
    # skill, and the glossary says so.
    print(f"[{time.time() - t0:.0f}s] wpa", flush=True)
    if "wpa" not in fams:
        pass
    else:
        con.execute(f"""
            CREATE OR REPLACE TEMP VIEW wpa_pa AS
            SELECT p.game_pk, p.at_bat_number, p.season, p.batter, p.pitcher,
                   p.inning, p.inning_topbot,
                   first(p.home_win_exp ORDER BY p.pitch_number) AS we_home_start,
                   sum(p.delta_home_win_exp) AS d_home,
                   arg_max(p.events, p.pitch_number) AS ev,
                   arg_max(p.des, p.pitch_number) AS des,
                   arg_max(p.bat_score_diff, p.pitch_number) AS bat_diff
            FROM pitches_all p
            WHERE p.game_type = 'R' AND p.season IN ({season_list})
              AND p.batter IS NOT NULL AND p.delta_home_win_exp IS NOT NULL
            GROUP BY 1, 2, 3, 4, 5, 6, 7
        """)
        wpa_pa = con.sql(f"""
            SELECT w.*, CASE WHEN w.inning_topbot = 'Bot' THEN w.d_home ELSE -w.d_home END AS swing,
                   w.we_home_start + w.d_home AS we_home_end,
                   r.name_first || ' ' || r.name_last AS batter_name,
                   rp.name_first || ' ' || rp.name_last AS pitcher_name
            FROM wpa_pa w
            LEFT JOIN register r ON r.key_mlbam = w.batter
            LEFT JOIN register rp ON rp.key_mlbam = w.pitcher
        """).df()
        # home_win_exp is stamped pre-pitch, so the PA's true end state is the
        # first pitch's state plus the PA's deltas — end minus start IS the
        # attribution by construction, whichever way the source stamps it.
        wpa_pa["we_before"] = wpa_pa["we_home_start"].where(
            wpa_pa["inning_topbot"] == "Bot", 1 - wpa_pa["we_home_start"]).round(3)
        wpa_pa["we_after"] = wpa_pa["we_home_end"].where(
            wpa_pa["inning_topbot"] == "Bot", 1 - wpa_pa["we_home_end"]).round(3)
        wpa_game = con.sql(f"""
            SELECT game_pk, season, min(game_date) AS date,
                   min(away_team) AS away, min(home_team) AS home,
                   max(post_away_score) AS away_runs, max(post_home_score) AS home_runs
            FROM pitches_all
            WHERE game_type = 'R' AND season IN ({season_list})
              AND delta_home_win_exp IS NOT NULL
            GROUP BY 1, 2
        """).df()
        n_wpa = 0
        h_rows: dict = {}
        p_rows: dict = {}
        top_swings: dict = {}
        by_game = dict(tuple(wpa_pa.groupby("game_pk", sort=True)))
        player_games = None
        if player is not None:
            player_games = (set(wpa_pa.loc[wpa_pa["batter"] == player, "game_pk"])
                            | set(wpa_pa.loc[wpa_pa["pitcher"] == player, "game_pk"]))
        for g0 in wpa_game.itertuples():
            if player_games is not None and g0.game_pk not in player_games:
                continue
            sub = by_game.get(g0.game_pk)
            if sub is None:
                continue
            moments = sub.reindex(sub["swing"].abs().sort_values(ascending=False).index).head(8)
            mom_out = [{"inning": int(m.inning), "half": m.inning_topbot,
                        "batter": m.batter_name, "batterId": str(int(m.batter)),
                        "pitcher": m.pitcher_name, "pitcherId": str(int(m.pitcher)),
                        "des": m.des, "swing": f(m.swing, 3),
                        "weBefore": f(m.we_before, 3), "weAfter": f(m.we_after, 3)}
                       for m in moments.itertuples()
                       if m.swing == m.swing and abs(m.swing) >= 0.05]
            tl = sub.groupby("inning", sort=True)["we_home_end"].last()
            timeline = [{"inning": int(k), "homeWe": f(v, 3)} for k, v in tl.items()]
            jwrite_gz(out / "wpa" / f"{g0.game_pk}.json.gz", {
                "gid": str(int(g0.game_pk)), "season": int(g0.season), "date": str(g0.date)[:10],
                "away": g0.away, "home": g0.home,
                "final": {"away": int(g0.away_runs), "home": int(g0.home_runs)},
                "timeline": timeline, "moments": mom_out,
            }, sort_keys=True)
            n_wpa += 1
            season = int(g0.season)
            for m in sub.itertuples():
                if m.swing != m.swing:
                    continue
                hc = h_rows.setdefault((int(m.batter), season),
                                       {"id": str(int(m.batter)), "name": m.batter_name,
                                        "pa": 0, "wpa": 0.0, "wpaPlus": 0.0, "lcWpa": 0.0, "lcPa": 0})
                hc["pa"] += 1
                hc["wpa"] += m.swing
                if m.swing > 0:
                    hc["wpaPlus"] += m.swing
                lc = int(m.inning) >= 7 and m.bat_diff == m.bat_diff and abs(m.bat_diff) <= 1
                if lc:
                    hc["lcWpa"] += m.swing
                    hc["lcPa"] += 1
                pc = p_rows.setdefault((int(m.pitcher), season),
                                       {"id": str(int(m.pitcher)), "name": m.pitcher_name,
                                        "bf": 0, "wpa": 0.0, "wpaMinus": 0.0, "lcWpa": 0.0})
                pc["bf"] += 1
                pc["wpa"] -= m.swing
                if m.swing < 0:
                    pc["wpaMinus"] -= m.swing
                if lc:
                    pc["lcWpa"] -= m.swing
            for mo in mom_out[:2]:
                if abs(mo["swing"] or 0) >= 0.25:
                    top_swings.setdefault(season, []).append(
                        {"gid": str(int(g0.game_pk)), "date": str(g0.date)[:10],
                         "away": g0.away, "home": g0.home, **mo})
        idx: dict = {}
        for (pid, season), c in h_rows.items():
            if c["pa"] < 50:
                continue
            idx.setdefault(str(season), {}).setdefault("hitters", []).append({
                **{k: c[k] for k in ("id", "name", "pa")},
                "wpa": f(c["wpa"], 2), "wpaPlus": f(c["wpaPlus"], 2),
                "lcWpa": f(c["lcWpa"], 2), "lcPa": c["lcPa"]})
        for (pid, season), c in p_rows.items():
            if c["bf"] < 50:
                continue
            idx.setdefault(str(season), {}).setdefault("pitchers", []).append({
                **{k: c[k] for k in ("id", "name", "bf")},
                "wpa": f(c["wpa"], 2), "wpaMinus": f(c["wpaMinus"], 2), "lcWpa": f(c["lcWpa"], 2)})
        for season, sw in top_swings.items():
            idx.setdefault(str(season), {})["topSwings"] = sorted(
                sw, key=lambda e: -abs(e["swing"] or 0))[:12]
        for season, doc in idx.items():
            for key in ("hitters", "pitchers"):
                if key in doc:
                    doc[key] = sorted(doc[key], key=lambda e: -(e["wpa"] or 0))
        jwrite(out / "wpa_index.json", {
            "_comment": ("win probability per batting-team PA (telescoped from per-pitch delta_home_win_exp); "
                         "positive = good for the batter / for the pitcher on wpa. Late & close = inning 7+ "
                         "within one run. 50+ PA/BF gate. Descriptive: context, not skill"),
            "seasons": dict(sorted(idx.items())),
        }, sort_keys=True)
        counts["wpa_files"] = n_wpa
        print(f"wpa game files: {n_wpa}")

    # ------------------------------------------------------------------ postseason
    if "postseason" in fams and level == "mlb":
        import postseason
        counts["postseason_game_files"] = postseason.bake(con, out / "postseason")

    # ------------------------------------------------------------------ aging
    # Aging curves and the decline read (depth list item 7, with the owner's
    # prospect bridges). Pools the FULL mart (2020-26) rather than the bake
    # seasons — age curves need the years. Curves weight each pitcher-season /
    # batter-season equally (a season is one dot, not its pitch count), the
    # classic survival caveat applies and the glossary says so. The Bayesian
    # changepoint early-warning version stays model-lane; what ships here is
    # the measured read: his dots on the league curve, YoY velo deltas with IL
    # context, and how draft age and prospect tier set debut clocks and peaks.
    print(f"[{time.time() - t0:.0f}s] aging", flush=True)
    if "aging" not in fams:
        pass
    elif level == "aaa":
        print("aging: MLB-only family — skipped at AAA (age_pit/age_bat are MLB columns)")
    else:
        ALL = "2020, 2021, 2022, 2023, 2024, 2025, 2026"
        # per pitcher-season FF velo (>=100 FF), equal weight per season
        ag_ff = con.sql(f"""
            SELECT pitcher, season, max(age_pit) AS age, avg(release_speed) AS v, count(*) AS n
            FROM pitches_all
            WHERE game_type = 'R' AND season IN ({ALL}) AND pitch_type = 'FF'
              AND release_speed IS NOT NULL AND age_pit BETWEEN 19 AND 43
            GROUP BY 1, 2 HAVING count(*) >= 100
        """).df()
        # per batter-season bat speed (>=100 tracked swings) and EV
        ag_bs = con.sql(f"""
            SELECT batter, season, max(age_bat) AS age, avg(bat_speed) AS v, count(*) AS n
            FROM pitches_all
            WHERE game_type = 'R' AND season IN ({ALL}) AND bat_speed IS NOT NULL
              AND age_bat BETWEEN 19 AND 43
            GROUP BY 1, 2 HAVING count(*) >= 100
        """).df()
        ag_ev = con.sql(f"""
            SELECT batter, season, max(age_bat) AS age, avg(launch_speed) AS v, count(*) AS n
            FROM pitches_all
            WHERE game_type = 'R' AND season IN ({ALL}) AND launch_speed IS NOT NULL
              AND age_bat BETWEEN 19 AND 43
            GROUP BY 1, 2 HAVING count(*) >= 50
        """).df()
        # per batter-season wOBA (Savant scale, from the per-pitch values)
        ag_wo = con.sql(f"""
            SELECT b.batter, b.season, max(b.age_bat) AS age,
                   sum(b.wv) / NULLIF(sum(b.wd), 0) AS v, sum(b.wv) AS wv, sum(b.wd) AS wd, count(*) AS pa
            FROM (
                SELECT batter, season, age_bat, game_pk, at_bat_number,
                       max(woba_value) AS wv, max(woba_denom) AS wd
                FROM pitches_all
                WHERE game_type = 'R' AND season IN ({ALL})
                  AND woba_value IS NOT NULL AND age_bat BETWEEN 19 AND 43
                GROUP BY 1, 2, 3, 4, 5
            ) b
            GROUP BY 1, 2 HAVING count(*) >= 100
        """).df()

        def curve(df, field, pooled=False):
            # pooled=True (wOBA): weight every plate appearance, not every season —
            # a mean-of-seasons wOBA at a thin age is one bench bat's year.
            if pooled:
                g = df.groupby("age").agg(wv=("wv", "sum"), wd=("wd", "sum"), n=("v", "count"))
                return [{"age": int(a), "n": int(r_.n), "mean": f(r_.wv / r_.wd, 3)}
                        for a, r_ in g.iterrows() if r_.n >= 20 and r_.wd > 0]
            g = df.groupby("age")[field].agg(["mean", "count"])
            return [{"age": int(a), "n": int(r_["count"]), "mean": f(r_["mean"], 1)}
                    for a, r_ in g.iterrows() if r_["count"] >= 20]

        jwrite(out / "aging" / "curves.json", {
            "_comment": ("league curves pooled 2020-26, one dot per qualified player-season (FF 100+, bat speed "
                         "100+ swings, EV 50+ BIP, wOBA 100+ PA on Savant's scale); survival bias applies — "
                         "each age's pool is only the players good enough to be there"),
            "ffVelo": curve(ag_ff.assign(v=ag_ff["v"].round(2)), "v"),
            "batSpeed": curve(ag_bs.assign(v=ag_bs["v"].round(2)), "v"),
            "ev": curve(ag_ev.assign(v=ag_ev["v"].round(2)), "v"),
            "woba": curve(ag_wo, "v", pooled=True),
        }, sort_keys=True)

        # per-player age tracks (any qualifying season type)
        tracks: dict = {}
        for df, kind in ((ag_ff, "ff"), (ag_bs, "bs"), (ag_ev, "ev"), (ag_wo, "wo")):
            # MERGE per season — assignment replaced the whole entry, so the last
            # metric (wOBA) silently erased bat speed / EV from every season it
            # shared with them.
            for r_ in df.itertuples():
                tr = tracks.setdefault(int(r_.pitcher if kind == "ff" else r_.batter), {})
                tr[int(r_.season)] = {
                    "season": int(r_.season), "age": int(r_.age),
                    **tr.get(int(r_.season), {}),
                    **({"ffVelo": f(r_.v, 1), "nPitches": int(r_.n)} if kind == "ff" else
                       {"batSpeed": f(r_.v, 1), "nSwings": int(r_.n)} if kind == "bs" else
                       {"ev": f(r_.v, 1), "nBip": int(r_.n)} if kind == "ev" else
                       {"woba": f(r_.v, 3), "pa": int(r_.pa)})}
        n_aging = 0
        for pid, seasons in sorted(tracks.items()):
            if player is not None and pid != player:
                continue
            if len(seasons) < 3:
                continue
            jwrite_gz(out / "aging" / f"{pid}.json.gz",
                      {"id": str(pid), "seasons": [seasons[s] for s in sorted(seasons)]},
                      sort_keys=True)
            n_aging += 1
        counts["aging_files"] = n_aging

        # decline flags: latest-season FF velo vs the pitcher's previous season,
        # with IL moves from the transactions feed (descriptive context, not the
        # changepoint model)
        il_moves = {}
        tx_fp = ROOT / "data" / "milb" / "transactions.parquet"
        if tx_fp.exists():
            tx = pd.read_parquet(tx_fp)
            tx = tx[tx["desc"].astype(str).str.contains("injured list", case=False, na=False)]
            for r_ in tx.itertuples():
                il_moves[(int(r_.id), int(str(r_.date)[:4]))] = il_moves.get((int(r_.id), int(str(r_.date)[:4])), 0) + 1
        ff_g = ag_ff.sort_values("season").groupby("pitcher")
        decline_rows = []
        names = dict(con.sql("SELECT CAST(key_mlbam AS BIGINT), name_first || ' ' || name_last FROM register").fetchall())
        for pid, g_ in ff_g:
            if len(g_) < 2:
                continue
            last = g_.iloc[-1]
            prev = g_.iloc[-2]
            if int(last.season) - int(prev.season) > 1:
                continue
            decline_rows.append({"id": str(int(pid)), "name": names.get(int(pid)),
                                 "season": int(last.season), "age": int(last.age),
                                 "ffVelo": f(last.v, 1), "prevSeason": int(prev.season),
                                 "prevFfVelo": f(prev.v, 1),
                                 "delta": f(last.v - prev.v, 1),
                                 "ilMoves": il_moves.get((int(pid), int(last.season)), 0)})
        decline_rows.sort(key=lambda e: (e["delta"] if e["delta"] is not None else 0))
        jwrite(out / "aging" / "decline_index.json", {
            "_comment": ("latest-season FF velo vs the pitcher's previous season (both 100+ FF), with IL moves "
                         "that year from the statsapi transactions feed — a descriptive decline read, not the "
                         "Bayesian changepoint model"),
            "pitchers": decline_rows,
        }, sort_keys=True)

        # prospect bridges (owner ask): draft age sets the clock; prospect tier
        # sets the debut age and the post-debut arc
        ppl_fp = ROOT / "data" / "milb" / "people.parquet"
        dr_fp = ROOT / "data" / "milb" / "draft.json"
        src_fp = ROOT / "data" / "milb" / "prospects.json"
        bridges: dict = {}
        if ppl_fp.exists() and dr_fp.exists() and src_fp.exists():
            ppl = pd.read_parquet(ppl_fp)[["id", "birth", "debut"]]
            ppl["birth_year"] = pd.to_datetime(ppl["birth"], errors="coerce").dt.year
            ppl["debut_year"] = pd.to_datetime(ppl["debut"], errors="coerce").dt.year
            by_id = ppl.set_index("id")
            # (a) draft age -> reached MLB + median years
            draft_picks = [dp for picks in json.loads(dr_fp.read_text()).values() for dp in picks if dp.get("id")]
            buckets = {"18 or younger": [], "19": [], "20": [], "21": [], "22": [], "23+": []}
            for dp in draft_picks:
                if dp["id"] not in by_id.index:
                    continue
                bw = by_id.loc[dp["id"], "birth_year"]
                dy = by_id.loc[dp["id"], "debut_year"]
                if pd.isna(bw):
                    continue
                age = dp["year"] - int(bw)
                key = ("18 or younger" if age <= 18 else "23+" if age >= 23 else str(age))
                buckets[key].append((dy is not None and not pd.isna(dy), (int(dy) - dp["year"]) if (not pd.isna(dy) and dy >= dp["year"]) else None))
            draft_age = []
            for key, vals in buckets.items():
                if not vals:
                    continue
                years = sorted(y for _, y in vals if y is not None)
                draft_age.append({"bucket": key, "n": len(vals),
                                  "reachedPct": f(100 * sum(1 for rch, _ in vals if rch) / len(vals), 1),
                                  "medianYears": years[len(years) // 2] if years else None})
            bridges["draftAge"] = draft_age
            # (b) first top-100 tier -> debut age + pooled post-debut wOBA by age
            raw_ranks = json.loads(src_fp.read_text())
            first_rank: dict = {}
            for y, lists in sorted(raw_ranks.items(), key=lambda kv: int(kv[0])):
                for r0 in lists.get("top100", []) or []:
                    pid = int(r0["id"])
                    if pid not in first_rank:
                        first_rank[pid] = (int(y), int(r0["rank"]))
            tier_of = {}
            for pid, (y, rank) in first_rank.items():
                tier_of[pid] = ("top 10" if rank <= 10 else "11-25" if rank <= 25 else "26-50" if rank <= 50 else "51-100")
            tiers = {}
            for pid, tier in tier_of.items():
                if pid not in by_id.index:
                    continue
                dw = by_id.loc[pid, "debut_year"]
                bw = by_id.loc[pid, "birth_year"]
                if pd.isna(dw):
                    continue
                c = tiers.setdefault(tier, {"n": 0, "debutAges": [], "pa": {}})
                c["n"] += 1
                if not pd.isna(bw):
                    c["debutAges"].append(int(dw) - int(bw))
            # pooled wOBA by age per tier from the batter-season aggregate
            wo_g = ag_wo.assign(tier=[tier_of.get(int(b), None) for b in ag_wo["batter"]])
            for tier in ("top 10", "11-25", "26-50", "51-100"):
                c = tiers.setdefault(tier, {"n": 0, "debutAges": [], "pa": {}})
                sub = wo_g[wo_g["tier"] == tier]
                for a, grp in sub.groupby("age"):
                    c["pa"][int(a)] = {"seasons": len(grp), "woba": f(grp["v"].mean(), 3)}
            bridges["tiers"] = []
            for tier in ("top 10", "11-25", "26-50", "51-100"):
                c = tiers.get(tier)
                if not c:
                    continue
                das = sorted(c["debutAges"])
                bridges["tiers"].append({"tier": tier, "n": c["n"],
                                         "medianDebutAge": das[len(das) // 2] if das else None,
                                         "byAge": [{"age": a, "seasons": c["pa"][a]["seasons"], "woba": c["pa"][a]["woba"]}
                                                   for a in sorted(c["pa"]) if c["pa"][a]["seasons"] >= 5]})
        jwrite(out / "aging" / "prospect_aging.json", {
            "_comment": ("prospect bridges: draft-age buckets -> reached MLB and median years; first top-100 tier "
                         "-> median debut age and mean season wOBA by age (100+ PA seasons, >=5 seasons per age)"),
            **bridges,
        }, sort_keys=True)
        print(f"aging files: {n_aging}; decline rows: {len(decline_rows)}")

    # ----------------------------------------------------------------- meta
    # The manifest doubles as the sync audit: per-file bytes + sha (16) so a
    # sync's --dry-run can be checked against what THIS bake produced.
    files_meta = {}
    for p in sorted(out.rglob("*")):
        if p.is_file():
            blob = p.read_bytes()
            files_meta[str(p.relative_to(out))] = {
                "bytes": len(blob),
                "sha256_16": hashlib.sha256(blob).hexdigest()[:16],
            }
    grades_sha = hashlib.sha256(GRADES_FILE.read_bytes()).hexdigest()[:16]
    prev = {}
    if (out / "meta.json").exists():
        try:
            prev = json.loads((out / "meta.json").read_text())
        except Exception:  # noqa: BLE001
            prev = {}
    meta = {
        "exportedAt": datetime.now(timezone.utc).isoformat(timespec="seconds"),
        "version": "goat-pro-mvp-1",
        "source": "pipeline/web_export.py over savant_mart (pitches_all, lb_*) + data/export/mlb_pitcher_grades.json",
        "seasons": seasons,
        "families": sorted(fams),
        "counts": {"prev": prev.get("counts", {}), "this_run": counts} if only else counts,
        "model_card": model_card,
        "grades_artifact": {"path": "data/export/mlb_pitcher_grades.json", "sha256_16": grades_sha},
        "models_artifact": {"path": "data/export/mlb_pitcher_models.json",
                            "sha256_16": hashlib.sha256(MODELS_FILE.read_bytes()).hexdigest()[:16]},
        "population": {
            "pitches": f"Statcast regular season {season_csv}, the FEATURE_SQL pitch gates "
                       "(12-cam Hawk-Eye era only), class key per the model card",
            "labels": "every grade renders under the descriptive label (gate_status descriptive-only)",
        },
        "code_map": {"FC->CT, ST->SW, SV->SL, CU/KC->CB, FO->FS": "Statcast type to site code"},
        "exclusions": {
            "rule": "position players are excluded from every leaderboard surface",
            "non_pitcher_ids": "40-man roster snapshots (position != P/TWP) — primary evidence",
            "thin_uncovered_seasons": "ids no snapshot covers (retired/traded arms) drop a season under 2 IP",
            "logos": "MLB static cap SVGs (one per club), stored in web/public/logos and mirrored to goatpro/logos/",
        },
        "files": files_meta,
        "savant_boards": savant_meta if "savant" in fams else prev.get("savant_boards", []),
    }
    jwrite(out / "meta.json", meta, sort_keys=True)

    # ------------------------------------------------------------ write rest
    print(f"[{time.time() - t0:.0f}s] pitchers", flush=True)  # per-family timing
    if "pitchers" in fams:
        n_bytes = jwrite(out / "pitchers.json", board.to_dict(orient="records"))
        # keep the other sections (hitters, hitters_dense, shrunk_by_season): a pitchers-only bake used to
        # drop the hitters section, which empties every hitter's percentile panel once synced
        prev_pct = json.loads((out / "percentiles.json").read_text()) if (out / "percentiles.json").exists() else {}
        jwrite(out / "percentiles.json", {**prev_pct,
            "_comment": f"percentile populations per season ({season_csv}); a profile ranks in its own season",
            "by_season": by_season, "pooled": pooled_pcts,
        })
        jwrite(out / "stuff_percentiles.json", stuff_pcts)
        jwrite(out / "scales.json", {
            "note": "Grade scale constants (train_mlb.grade): 100 + 10z per class x side, clipped [50, 175]. "
                    "The descriptive label rides the model card.",
            "grades": {"center": 100, "clip": [50, 175], "population_n": int(len(board))},
            "confidence_floors": conf_floor,
        })
        print(f"pitchers.json {n_bytes / 1e6:.1f} MB")
    print(f"[{time.time() - t0:.0f}s] arsenal", flush=True)  # per-family timing
    if "arsenal" in fams:
        jwrite(out / "arsenal_cards.json", arsenal_cards)
        for site, rows in arsenal_rows.items():
            jwrite(out / "arsenal" / f"{site.lower()}.json", rows)
        # the mix board (A2): one artifact for the latest season, percentiles vs
        # same-season pitchers with 100+ pitches (bake-side, like the college bake)
        mix_latest = {str(pid): v for (pid, s), v in mix_by_key.items() if s == max(seasons)}
        ref_latest = mix_ref.get(max(seasons), {})
        jwrite(out / "arsenal.json", {
            "_comment": "generated by pipeline/web_export.py — do not hand-edit",
            "season": max(seasons),
            "note": "Description, not a grade: these components predicted nothing beyond Pitching+ "
                    "and the pitcher's own prior season. pct = percentile vs pitchers with 100+ "
                    "pitches; for repeatSd a HIGHER percentile is MORE scatter.",
            "league": {mk: (f(float(np.median([x[mk] for x in ref_latest.values() if x[mk] is not None])), 2)
                            if any(x[mk] is not None for x in ref_latest.values()) else None)
                       for mk in MIX_KEYS},
            "nRef": len(ref_latest),
            "pitchers": mix_latest,
        }, sort_keys=True)
    print(f"[{time.time() - t0:.0f}s] slot", flush=True)  # per-family timing
    if "slot" in fams:
        jwrite(out / "slot_board.json", {"season": season_csv, "source": "goat-pro pipeline/web_export.py",
                                         "pitchers": slot_pitchers})
    print(f"[{time.time() - t0:.0f}s] vaa", flush=True)  # per-family timing
    if "vaa" in fams:
        jwrite(out / "vaa_zone_pct.json", vaa_file)
    if hitter_pct_out or pitcher_shrunk_out:
        pct_path = out / "percentiles.json"
        pct = json.loads(pct_path.read_text()) if pct_path.exists() else {}
        if pitcher_shrunk_out:
            for s, pcts in pitcher_shrunk_out["shrunk_by_season"].items():
                pct.setdefault("shrunk_by_season", {}).setdefault(s, {}).update(pcts)
        if hitter_pct_out:
            for s, pcts in hitter_pct_out.get("shrunk_by_season", {}).items():
                pct.setdefault("shrunk_by_season", {}).setdefault(s, {}).update(pcts)
            hitter_pct_out = {k: v for k, v in hitter_pct_out.items() if k != "shrunk_by_season"}
            pct.update(hitter_pct_out)
        jwrite(pct_path, pct)
    print(f"{time.time() - t0:.0f}s -> {out} (families {sorted(fams)})")
    return counts


def main() -> None:
    ap = argparse.ArgumentParser()
    ap.add_argument("--seasons", type=int, nargs="+",
                    help="default: 2020-26 for MLB (Hawk-Eye era), 2023-26 for AAA (its Statcast starts 2023)")
    ap.add_argument("--only", nargs="+", choices=FAMILIES, metavar="FAMILY",
                    help="bake only these families: " + " ".join(FAMILIES))
    ap.add_argument("--player", type=int, help="limit the players/slot per-player files to one id")
    ap.add_argument("--check", action="store_true",
                    help="run the same bake twice and diff — exits 1 on any difference "
                         "beyond meta.json's exportedAt (the no-op guarantee)")
    ap.add_argument("--keep-check", action="store_true", help="keep the --check temp dirs")
    ap.add_argument("--write", action="store_true",
                    help="with --check: on PASS, write the checked bake into the export dir "
                         "(replaces a third full bake)")
    ap.add_argument("--out", type=Path, help="bake into this directory instead of data/export/web")
    ap.add_argument("--level", choices=("mlb", "aaa"), default="mlb",
                    help="aaa: the same bake over pitches_aaa into data/export/web/aaa (no Savant boards)")
    args = ap.parse_args()
    only = set(args.only) if args.only else None
    level = args.level
    if args.seasons is None:
        args.seasons = list(range(2023 if level == "aaa" else 2020, 2027))
    if level == "aaa":
        only = (only or set(FAMILIES)) - {"savant"}

    real = args.out or (EXPORT / "aaa" if level == "aaa" else EXPORT)
    if args.check:
        skip = ("aaa",) if real == EXPORT else ()  # the MLB export dir holds the AAA one; an MLB bake never touches it
        base = Path(tempfile.mkdtemp(prefix="goat-web-check-"))
        try:
            with bake_lock(real) if args.write else contextlib.nullcontext():
                a, b = base / "a", base / "b"
                for d in (a, b):
                    seed_dir(real, d, skip)
                print(f"check: bake 1/2 -> {a}")
                run_bake(a, args.seasons, only, args.player, level)
                print(f"check: bake 2/2 -> {b}")
                run_bake(b, args.seasons, only, args.player, level)
                diffs = diff_dirs(a, b)
                if diffs:
                    print(f"check: FAIL — {len(diffs)} file(s) differ:")
                    for dline in diffs[:40]:
                        print(f"  {dline}")
                    sys.exit(1)
                print("check: PASS — the two bakes are byte-identical (meta.json exportedAt excepted)")
                if args.write:
                    apply_dir(a, real, skip)
                    print(f"check: written -> {real}")
        finally:
            if not args.keep_check:
                shutil.rmtree(base, ignore_errors=True)
        return

    run_bake(real, args.seasons, only, args.player, level)


if __name__ == "__main__":
    main()
